insert into public.email_automations(id,key,name,trigger_type,is_active) values('5fd092ed-e49e-5482-9537-2b9073440a4a','course_intensive-holiness','Интенсив «Святость»','course',false) on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('b0348150-dfc7-51ea-9449-88f913bd117f','5fd092ed-e49e-5482-9537-2b9073440a4a','Вводное письмо',1,0,'{Интенсив Святость} Добро пожаловать!','{"ru":"{Интенсив Святость} Добро пожаловать!","en":"{Intensive «Holiness»} Welcome!","de":"{Intensivkurs «Heiligkeit»} Willkommen!","fr":"{Intensif « Sainteté »} Bienvenue !","it":"{Intensivo «Santità»} Benvenuto!","es":"{Intensivo «Santidad»} ¡Bienvenido!","pt":"{Intensivo «Santidade»} Bem-vindo!","nl":"{Intensief «Heiligheid»} Welkom!"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png" alt="Интенсив «Святость»" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. На первый взгляд, я перечислил естественные состояния, свойственные многим людям. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением, порой приводя к тому, что жизнь становится материалистичной, наполненной экзистенциальными страхами, ощущением бессмысленности… Выполняя практики как на йоговском коврике, так и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p>В течение 30 дней вы получите 30 практик, направленных на гармонизацию седьмой чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «седьмая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Курс «Осуществи мечту»: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. На первый взгляд, я перечислил естественные состояния, свойственные многим людям. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением, порой приводя к тому, что жизнь становится материалистичной, наполненной экзистенциальными страхами, ощущением бессмысленности… Выполняя практики как на йоговском коврике, так и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p>В течение 30 дней вы получите 30 практик, направленных на гармонизацию седьмой чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «седьмая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Курс «Осуществи мечту»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>I am glad that you have decided to work purposefully with the seventh chakra for a month, that is, to direct attention to transcendent states that we perceive with awe, as contact with God. At first glance, I have listed natural states characteristic of many people. However, in society there are many both inciting and prohibitive scenarios that control our behavior, sometimes leading to life becoming materialistic, filled with existential fears, a sense of meaninglessness… By performing practices both on the yoga mat and in life, reflecting, correcting your thoughts and actions, over the course of a month you can obtain important results that will manifest both at the level of the body (healing) and at the level of psychological background (satisfaction and happiness).</p><p></p><p></p><p>Over the course of 30 days you will receive 30 practices aimed at harmonizing the seventh chakra. Read this letter carefully so that you understand what will happen and how. <br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “seventh chakra” has to do with this, I recommend that you combine taking this intensive with a workshop or course in which I gradually lead to an understanding of what we are doing here. It is important not simply to “believe” me, but to open understanding within yourself through personal experience—both on the yoga mat and in life. Then the practices begin to work much more deeply. Otherwise we get physical exercise—since this is the basic understanding (experience) of yoga that everyone has. </p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “Month of Strength”: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Course “Make the Dream Come True”: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p></p><p>Sergei Zamkovoi</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang gezielt mit dem siebten Chakra zu arbeiten, das heißt, Ihre Aufmerksamkeit auf transzendente Zustände zu richten, die wir mit innerer Ehrfurcht als Kontakt mit Gott wahrnehmen. Auf den ersten Blick habe ich natürliche Zustände aufgezählt, die vielen Menschen eigen sind. In der Gesellschaft wirken jedoch viele sowohl anspornende als auch verbietende Szenarien, die unser Verhalten steuern und mitunter dazu führen, dass das Leben materialistisch wird, voller existenzieller Ängste und eines Gefühls der Sinnlosigkeit… Wenn Sie die Praktiken sowohl auf der Yogamatte als auch im Leben ausführen, nachdenken und Ihre Gedanken und Handlungen korrigieren, können Sie im Laufe eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p>Im Laufe von 30 Tagen erhalten Sie 30 Praktiken, die auf die Harmonisierung des siebten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht absolviert haben und nicht verstehen, was es mit diesem „siebten Chakra“ auf sich hat, empfehle ich Ihnen, den Durchgang dieses Intensivkurses mit einem Praktikum oder Kurs zu verbinden, in dem ich Sie allmählich zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, nicht einfach mir zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen - sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls bekommen wir Gymnastik - denn dies ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Sie können diesen Intensivkurs mit folgenden Lehrprogrammen ergänzen:<br> - Praktikum «Monat der Kraft»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Kurs «Verwirkliche den Traum»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé de travailler pendant un mois de manière ciblée avec le septième chakra, c''est-à-dire de diriger l''attention vers les états transcendants que nous percevons avec un tremblement de l''âme, comme un contact avec Dieu. À première vue, j''ai énuméré des états naturels propres à de nombreuses personnes. Cependant, dans la société, il existe de nombreux scénarios à la fois incitatifs et prohibitifs, qui gouvernent notre comportement, conduisant parfois à ce que la vie devienne matérialiste, remplie de peurs existentielles, d''un sentiment d''absurdité… En pratiquant aussi bien sur le tapis de yoga que dans la vie, en réfléchissant, en corrigeant ses pensées et ses actes, on peut, pendant un mois, obtenir des résultats importants, qui se manifesteront tant au niveau du corps (guérison) qu''au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p>Pendant 30 jours, vous recevrez 30 pratiques destinées à harmoniser le septième chakra. Lisez attentivement cette lettre pour comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n''avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « septième chakra », je vous recommande d''associer le passage de cet intensif à un atelier pratique ou à un cours dans lequel je vous amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d''ouvrir en vous une compréhension par l''expérience personnelle - aussi bien sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, on obtient de la gym - car c''est la compréhension (l''expérience) de base du yoga que chacun possède. </p><p></p><p></p><p>Vous pouvez compléter cet intensif par les programmes d''étude suivants :<br> - Atelier pratique « Mois de force » : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Cours « Réalise ton rêve » : <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p></p><p>Sergei Zamkovoi</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Mi fa piacere che tu abbia deciso di lavorare per un mese in modo mirato con il settimo chakra, cioè di dirigere l''attenzione verso gli stati trascendenti che percepiamo con sacro timore, come un contatto con Dio. A prima vista, ho elencato stati naturali propri di molte persone. Tuttavia, nella società agiscono molti scenari, sia incentivanti sia inibitori, che governano il nostro comportamento, portando talvolta al fatto che la vita diventa materialistica, piena di paure esistenziali, di sensazione di mancanza di senso… Eseguendo le pratiche sia sul tappetino da yoga sia nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nell''arco di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (risanamento), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p>In 30 giorni riceverai 30 pratiche volte ad armonizzare il settimo chakra. Leggi attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non hai seguito i miei corsi e non capisci cosa c''entri qui un qualche «settimo chakra», ti consiglio di abbinare la partecipazione a questo intensivo a un seminario pratico o a un corso in cui ti conduco gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non semplicemente «credermi», ma aprire in te la comprensione attraverso l''esperienza personale - sia sul tappetino da yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo ginnastica - poiché questa è la comprensione (esperienza) di base dello yoga che ciascuno ha. </p><p></p><p></p><p>Puoi integrare questo intensivo con i seguenti programmi didattici:<br> - Seminario pratico «Mese della forza»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Corso «Realizza il sogno»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p></p><p>Sergei Zamkovoi</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>Me alegra que se hayan decidido durante un mes a trabajar de manera intencionada con el séptimo chakra, es decir, dirigir la atención hacia estados trascendentes que percibimos con sobrecogimiento del alma, como contacto con Dios. A primera vista, he enumerado estados naturales propios de muchas personas. Sin embargo, en la sociedad actúan muchos guiones tanto incentivadores como prohibitivos que gobiernan nuestra conducta, llevando a veces a que la vida se vuelva materialista, llena de miedos existenciales, de sensación de sinsentido… Realizando prácticas tanto en la esterilla de yoga como en la vida, reflexionando, corrigiendo sus pensamientos y actos, durante un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p>Durante 30 días recibirá 30 prácticas dirigidas a armonizar el séptimo chakra. Lea atentamente esta carta para comprender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si usted no ha tomado mis cursos y no entiende qué tiene que ver aquí esa tal «séptimo chakra», le recomiendo combinar la realización de este intensivo con un prácticum o un curso en el que conduzco suavemente hacia la comprensión de lo que hacemos aquí. Es importante no simplemente «creerme», sino abrir en usted la comprensión a través de la experiencia personal, tanto en la esterilla de yoga como en la vida. Entonces las prácticas comienzan a funcionar mucho más profundamente. De lo contrario, obtenemos educación física, ya que es la comprensión (experiencia) básica del yoga que cada uno tiene. </p><p></p><p></p><p>Puede complementar este intensivo con los siguientes programas de estudio:<br> - Prácticum «Mes de la fuerza»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Curso «Haz realidad el sueño»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Fico feliz que você tenha decidido trabalhar intencionalmente com o sétimo chakra durante um mês, ou seja, direcionar a atenção para estados transcendentes que percebemos com reverência, como um contato com Deus. À primeira vista, enumerei estados naturais próprios de muitas pessoas. No entanto, na sociedade atuam muitos cenários tanto incentivadores quanto proibitivos, que governam nosso comportamento, por vezes levando a que a vida se torne materialista, repleta de medos existenciais, sensação de falta de sentido… Ao realizar as práticas tanto no tapete de yoga quanto na vida, refletindo, corrigindo seus pensamentos e ações, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p>Ao longo de 30 dias, você receberá 30 práticas voltadas para a harmonização do sétimo chakra. Leia atentamente esta carta para entender o que e como acontecerá. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso algum «sétimo chakra» aí, recomendo combinar a realização deste intensivo com um praticum ou curso no qual eu conduzo suavemente à compreensão do que fazemos aqui. É importante não apenas «acreditar» em mim, mas abrir em você a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos ginástica - pois esta é a compreensão (experiência) básica do yoga que cada um tem. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Praticum «Mês da Força»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Curso «Realize o Sonho»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>Ik ben blij dat je hebt besloten om een maand lang gericht met de zevende chakra te werken, dat wil zeggen de aandacht te richten op transcendente toestanden die wij met ontzag ervaren als contact met God. Op het eerste gezicht heb ik natuurlijke toestanden opgesomd die veel mensen eigen zijn. Echter, in de samenleving werken talrijke zowel aanmoedigende als verbiedende scenario''s die ons gedrag sturen, soms leidend tot een leven dat materialistisch wordt, vervuld van existentiële angsten, van een gevoel van zinloosheid… Door praktijken te beoefenen, zowel op de yogamat als in het leven, na te denken, je gedachten en daden bij te sturen, kun je in de loop van een maand belangrijke resultaten behalen, die zich zowel op het niveau van het lichaam (gezondheid) als op het niveau van de psychologische achtergrond (tevredenheid en geluk) zullen manifesteren.</p><p></p><p></p><p>Gedurende 30 dagen ontvang je 30 praktijken die gericht zijn op het harmoniseren van de zevende chakra. Lees deze brief aandachtig, zodat je begrijpt wat er gaat gebeuren en hoe. <br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat die ‘zevende chakra’ daar in vredesnaam mee te maken heeft, raad ik je aan dit intensief te combineren met een practicum of cursus waarin ik je geleidelijk naar het begrip breng waar we hier mee bezig zijn. Het is belangrijk om mij niet alleen maar te ‘geloven’, maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan beginnen de praktijken veel dieper te werken. Anders krijgen we gymnastiek - omdat dit het basisbegrip (de ervaring) van yoga is die iedereen heeft. </p><p></p><p></p><p>Dit intensief kun je aanvullen met de volgende leerprogramma''s:<br> - Practicum ‘Maand van kracht’: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Cursus ‘Verwezenlijk de droom’: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p></p><p>Sergei Zamkovoi</p>"}'::jsonb,'{"ru":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Я рад, что вы решились в течение месяца целенаправленно поработать с седьмой чакрой, то есть направить внимание на трансцендентные состояния, которые мы воспринимаем с душевным трепетом, как контакт с Богом. На первый взгляд, я перечислил естественные состояния, свойственные многим людям. Однако, в социуме действует множество как побудительных, так и запретительных сценариев, которые управляют нашим поведением, порой приводя к тому, что жизнь становится материалистичной, наполненной экзистенциальными страхами, ощущением бессмысленности… Выполняя практики как на йоговском коврике, так и в жизни, размышляя, корректируя свои мысли и поступки, в течение месяца можно получить важные результаты, которые проявятся как на уровне тела (оздоравливание), так и на уровне психологического фона (удовлетворённость и счастье).</p><p></p><p></p><p>В течение 30 дней вы получите 30 практик, направленных на гармонизацию седьмой чакры. Внимательно прочитайте это письмо, чтобы понимать, что и как будет происходить. <br> <br><strong>1. Самая суть</strong><br> Это не учебный курс, а интенсивный практикум, ядром которого являются ежедневные практики йоги. Данные практики я проводил по утрам в прямом эфире, синхронизируя направление каждой практики с планетными ритмами в тот день. В этом интенсиве я собрал видеозаписи лучших практик, которые были направлены именно на первую чакру (иногда во взаимодействии с какой-нибудь ещё чакрой), дополнил их поведенческими (психологическими) практиками. В результате получился мощнейший заряд для гармонизации сферы здоровья. </p><p></p><p></p><p>Если вы не проходили моих курсов и не понимаете при чём здесь какая-то там «седьмая чакра», я рекомендую вам совместить прохождение данного интенсива с практикумом или курсом, в котором я плавно подвожу к пониманию того, чем мы здесь занимаемся. Важно не просто «поверить» мне, а открыть в себе понимание через личный опыт - как на йоговском коврике, так и в жизни. Тогда практики начинают работать гораздо глубже. Иначе получаем физкультуру - так как это базовое понимание (опыт) йоги, которое есть у каждого. </p><p></p><p></p><p>Данный интенсив вы можете дополнить следующими учебными программами:<br> - Практикум «Месяц силы»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Курс «Осуществи мечту»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Практики йоги</strong><br> Практики йоги, которые вас ожидают, отличаются от того, что вы можете встретить в фитнес-центре. Я предполагаю, что вам важен результат, а не лицедейство. Мы работаем с внутренними состояниями (то есть с энергиями), соединяя медитацию, пранаяму и асаны в той мере, в которой это необходимо для получения желаемого результата на максимально глубоком уровне. Большинство практик начинаются с небольшого введения, которое необходимо, чтобы ваше сознание переключилось с обыденности на волну практики, вы вошли в соответствующий энергетический поток и активировалось ваше внутреннее намерение. Далее следует сама практика, которая в разные дни имеет разную длительность и состав элементов. После практики я рекомендую вам некоторое время побыть в медитации, а может быть в возникшем состоянии осознанности продолжить выполнять асаны, которые будет просить ваше тело. Средняя продолжительность практик 30-40 минут. Но некоторые практики короче, а некоторые длятся около часа. Важно, чтобы во время практики вас ничто не отвлекало и не торопило. И ещё очень важно - начав практику, не прерывайтесь до её окончания!!! Каждая практика - это живая история, которая проводит вас по определённому пути. Прервав практику, вы можете оказаться в менее ресурсном состоянии, чем были в её начале. Даже если сейчас эти слова вам кажутся мистификацией и пустой эзотерикой, прислушайтесь к моим рекомендациям. <br>  <br><strong>3. Поведенческие практики</strong><br> Каждый день в письме вместе с практикой йоги я буду присылать вам «совет дня». Попробуйте воспринимать его не как ещё одну умную мысль, подобную которой вы уже много раз слышали. У меня нет цели вас удивить, сказав то, что вы ещё не слышали. Воспринимайте этот «совет» как задание, как поведенческую практику! Выполняйте эту практику в данный день. И поверьте - вам станет гораздо интересней, и этот интенсив принесёт вам гораздо больше пользы. Некоторые такие практики могут казаться вам проще, некоторые сложнее. Некоторые прагматичнее, некоторые более психологическими. В любом случае, это не как если бы я предложил вам 20 раз присесть. Тут мы работаем с вашими поведенческими и психологическими шаблонами. И ключ к успеху в том, чтобы не сражаться с собой, не вызывать дополнительное внутреннее напряжение, а как в асанах - дышать и расслабляться. Поэтому практика звучит мягко - как &quot;совет дня&quot; - чтобы не вызывать сигнал тревоги. Прочитайте, примерьте, попробуйте в течение дня мягко следовать этому совету или хотя бы вспоминать его, вновь примеряя и возвращаясь в ощущение, что вы ему следуете. Адаптируйтесь к новым состояниям... В некоторых случаях одна такая практика может растянуться на несколько дней или даже месяцев, потому что вы ощутите её значимость, и начнёте внедрять её в свою жизнь на уровне привычки, то есть корректируя текущий гомеостаз системы. И, хотя я не закладывал чёткую связь между поведенческими практиками и практиками йоги, которые предлагаю в одном письме, тем не менее вы можете выполнять каждую практику йоги в состоянии, возникшем когда вы воспринимаете себя следующим моему совету. Однако, это вовсе не обязательно, так как каждая из этих двух практик самодостаточна.<br>  <br><strong>4. Расписание занятий</strong><br> Каждый день в полночь вам будет открываться новая практика (прошлая при этом будет исчезать, как прошлый день). Благодаря такому подходу, у вас не будет накапливаться снежный ком невыполненных практик. В течение суток вы можете выбрать любое удобное вам время, и позаниматься. Я рекомендую вам заниматься утром, чтобы в полученном в результате практики состоянии проживать день, а не спать лечь. Воспринимайте этот интенсив не как компьютерную иллюзию, а как реальную жизнь - в которой всё важное происходит СЕГОДНЯ, и практика йоги расширяется с коврика на пространство вашей проявленности в том мире, который вы воспринимаете, как наиболее реальный!</p><p></p><p></p><p>Кстати, есть небольшой нюанс с временем получения второй практики. Если вы записались до 18:00, то вторую практику вы получите в ближайшую полночь. Если же вы записались после 18:00, то вторую практику вы получите не в ближайшую, а в следующую полночь. То есть у вас будет запас времени на случай, если вы не успеете выполнить практику в день записи на интенсив. <br>  <br><strong>5. Не насилуйте себя</strong><br> Когда вы покупаете месячный абонемент в фитнес центр, вы ведь понимаете, что вам не обязательно ходить в него каждый день? Более того, взяв слишком быстрый темп, вы можете забросить занятия не дойдя даже до конца месяца... В отношении практик данного интенсива действует то же правило - не жадничайте! Занимайтесь в удобном вам ритме - через день, через два... Конечно, хорошо заниматься каждый день, но ещё лучше - понимать свои долгосрочные задачи, и действовать соответственно. Скорее всего, ваши задачи выходят за рамки одного месяца, и вам необходимо регулярно действовать длительное время. Данный интенсив я задумал так, чтобы вы могли проходить его месяц за месяцем столько раз, сколько потребуется, пока поставленная вами цель не будет достигнута. Эта стратегия эффективней, чем один месяц втопить, а потом забросить практики или рвануть в другом направлении.<br>  <br><strong>6. Техника безопасности</strong><br> Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, которые я буду предлагать, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу контролировать ваше состояние. У вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените её другой асаной - такой, которая приблизительно также включает тело, но проще для вас.<br>  <br><strong>7. Ответы на вопросы</strong><br> Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.<br> <br>Желаю вам плодотворных практик!</p><p></p><p>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>I am glad that you have decided to work purposefully with the seventh chakra for a month, that is, to direct attention to transcendent states that we perceive with awe, as contact with God. At first glance, I have listed natural states characteristic of many people. However, in society there are many both inciting and prohibitive scenarios that control our behavior, sometimes leading to life becoming materialistic, filled with existential fears, a sense of meaninglessness… By performing practices both on the yoga mat and in life, reflecting, correcting your thoughts and actions, over the course of a month you can obtain important results that will manifest both at the level of the body (healing) and at the level of psychological background (satisfaction and happiness).</p><p></p><p></p><p>Over the course of 30 days you will receive 30 practices aimed at harmonizing the seventh chakra. Read this letter carefully so that you understand what will happen and how. <br> <br><strong>1. The very essence</strong><br> This is not a training course, but an intensive workshop, the core of which is daily yoga practices. I conducted these practices in the mornings in live broadcasts, synchronizing the direction of each practice with the planetary rhythms on that day. In this intensive I have gathered video recordings of the best practices that were aimed specifically at the first chakra (sometimes in interaction with some other chakra), and supplemented them with behavioral (psychological) practices. The result is a most powerful charge for harmonizing the sphere of health. </p><p></p><p></p><p>If you have not taken my courses and do not understand what some “seventh chakra” has to do with this, I recommend that you combine taking this intensive with a workshop or course in which I gradually lead to an understanding of what we are doing here. It is important not simply to “believe” me, but to open understanding within yourself through personal experience—both on the yoga mat and in life. Then the practices begin to work much more deeply. Otherwise we get physical exercise—since this is the basic understanding (experience) of yoga that everyone has. </p><p></p><p></p><p>You can supplement this intensive with the following educational programs:<br> - Workshop “Month of Strength”: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Course “Make the Dream Come True”: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yoga practices</strong><br> The yoga practices that await you differ from what you may encounter in a fitness center. I assume that the result matters to you, not playacting. We work with inner states (that is, with energies), combining meditation, pranayama, and asanas to the extent necessary to obtain the desired result at the deepest possible level. Most practices begin with a short introduction, which is necessary so that your consciousness switches from everydayness to the wave of the practice, you enter the corresponding energy flow, and your inner intention becomes activated. Then comes the practice itself, which on different days has a different duration and composition of elements. After the practice, I recommend that you spend some time in meditation, or perhaps, in the arising state of awareness, continue to perform the asanas that your body will ask for. The average duration of the practices is 30-40 minutes. But some practices are shorter, and some last about an hour. It is important that during the practice nothing distracts you and nothing hurries you. And one more very important thing - having begun the practice, do not interrupt it until it ends!!! Each practice is a living story that takes you along a certain path. If you interrupt the practice, you may end up in a less resourceful state than you were in at its beginning. Even if right now these words seem to you like mystification and empty esotericism, heed my recommendations. <br>  <br><strong>3. Behavioral practices</strong><br> Every day in the email, together with the yoga practice, I will send you a “tip of the day.” Try to perceive it not as yet another clever thought, similar to which you have already heard many times. I have no goal of surprising you by saying something you have not yet heard. Perceive this “tip” as a task, as a behavioral practice! Perform this practice on the given day. And believe me - it will become much more interesting for you, and this intensive will bring you much more benefit. Some such practices may seem easier to you, some harder. Some more pragmatic, some more psychological. In any case, it is not as if I suggested that you do 20 squats. Here we work with your behavioral and psychological patterns. And the key to success is not to fight with yourself, not to create additional inner tension, but, as in asanas, to breathe and relax. That is why the practice sounds soft - like a “tip of the day” - so as not to trigger an alarm signal. Read it, try it on, try during the day to gently follow this tip or at least to remember it, again trying it on and returning to the feeling that you are following it. Adapt to new states... In some cases, one such practice may stretch over several days or even months, because you will feel its significance and begin to introduce it into your life at the level of a habit, that is, adjusting the current homeostasis of the system. And although I did not build in a clear connection between the behavioral practices and the yoga practices that I offer in one email, nevertheless you can perform each yoga practice in the state that arises when you perceive yourself as following my tip. However, this is not at all obligatory, since each of these two practices is self-sufficient.<br>  <br><strong>4. Class schedule</strong><br> Every day at midnight a new practice will open for you (the previous one will disappear, like the previous day). Thanks to this approach, uncompleted practices will not accumulate into a snowball. During the day you can choose any time convenient for you and practice. I recommend that you practice in the morning, so that you live the day in the state obtained as a result of the practice, rather than go to sleep. Perceive this intensive not as a computer illusion, but as real life - in which everything important happens TODAY, and the yoga practice expands from the mat into the space of your manifestation in that world which you perceive as the most real!</p><p></p><p></p><p>By the way, there is a small nuance with the time you receive the second practice. If you signed up before 18:00, then you will receive the second practice at the nearest midnight. If you signed up after 18:00, then you will receive the second practice not at the nearest midnight, but at the following midnight. That is, you will have a reserve of time in case you do not manage to complete the practice on the day you signed up for the intensive. <br>  <br><strong>5. Do not force yourself</strong><br> When you buy a monthly membership at a fitness center, you do understand that you do not have to go there every day, right? Moreover, by taking too fast a pace, you may abandon the classes before you even reach the end of the month... The same rule applies to the practices of this intensive - do not be greedy! Practice at a pace convenient for you - every other day, every two days... Of course, it is good to practice every day, but it is even better to understand your long-term tasks and act accordingly. Most likely, your tasks go beyond one month, and you need to act regularly for a long time. I conceived this intensive so that you could go through it month after month as many times as needed until the goal you have set is achieved. This strategy is more effective than going all out for one month and then abandoning the practices or rushing off in another direction.<br>  <br><strong>6. Safety precautions</strong><br> I care about your health and remind you that only you bear responsibility for the adequacy of performing the asanas, pranayamas, and meditations that I will offer to your physical capabilities and mental state. It is important to understand that these are online classes, and I cannot control your state. You may have physical and psychological particularities. Please be attentive to your state. If you feel that some asana that I suggest performing is premature for you, perform it not very deeply, at a compromise level, or replace it altogether with another asana - one that approximately also engages the body but is easier for you.<br>  <br><strong>7. Answers to questions</strong><br> Every week (usually on Saturdays) I hold group online consultations (webinars) in Zoom, at which we communicate, maintain motivation, and discuss difficulties and questions that arise. Before each such consultation, I will send you an email indicating the date and time of its holding, as well as a link to join it. What is interesting to you will surely also be interesting to many others. Therefore, discussing questions at group consultations is most effective. If it happens that the time of the consultation is inconvenient for you, in that case send your questions by email before it begins. I will answer them at the consultation, and I will send you a link to the recording so that you can watch it at a time convenient for you. Consultation recordings are kept for one week.<br> <br>I wish you fruitful practices!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Ich freue mich, dass Sie sich entschieden haben, einen Monat lang gezielt mit dem siebten Chakra zu arbeiten, das heißt, Ihre Aufmerksamkeit auf transzendente Zustände zu richten, die wir mit innerer Ehrfurcht als Kontakt mit Gott wahrnehmen. Auf den ersten Blick habe ich natürliche Zustände aufgezählt, die vielen Menschen eigen sind. In der Gesellschaft wirken jedoch viele sowohl anspornende als auch verbietende Szenarien, die unser Verhalten steuern und mitunter dazu führen, dass das Leben materialistisch wird, voller existenzieller Ängste und eines Gefühls der Sinnlosigkeit… Wenn Sie die Praktiken sowohl auf der Yogamatte als auch im Leben ausführen, nachdenken und Ihre Gedanken und Handlungen korrigieren, können Sie im Laufe eines Monats wichtige Ergebnisse erzielen, die sich sowohl auf der Ebene des Körpers (Gesundung) als auch auf der Ebene des psychologischen Hintergrunds (Zufriedenheit und Glück) zeigen.</p><p></p><p></p><p>Im Laufe von 30 Tagen erhalten Sie 30 Praktiken, die auf die Harmonisierung des siebten Chakras ausgerichtet sind. Lesen Sie diesen Brief sorgfältig, damit Sie verstehen, was und wie geschehen wird. <br> <br><strong>1. Das Wesentliche</strong><br> Das ist kein Lehrkurs, sondern ein intensives Praktikum, dessen Kern tägliche Yoga-Praktiken sind. Diese Praktiken habe ich morgens live durchgeführt und dabei die Ausrichtung jeder Praxis mit den planetaren Rhythmen jenes Tages synchronisiert. In diesem Intensivkurs habe ich Videoaufzeichnungen der besten Praktiken gesammelt, die genau auf das erste Chakra ausgerichtet waren (manchmal in Wechselwirkung mit einem anderen Chakra), und sie um verhaltensbezogene (psychologische) Praktiken ergänzt. Daraus ist eine äußerst kraftvolle Ladung für die Harmonisierung des Bereichs Gesundheit entstanden. </p><p></p><p></p><p>Wenn Sie meine Kurse nicht absolviert haben und nicht verstehen, was es mit diesem „siebten Chakra“ auf sich hat, empfehle ich Ihnen, den Durchgang dieses Intensivkurses mit einem Praktikum oder Kurs zu verbinden, in dem ich Sie allmählich zum Verständnis dessen hinführe, womit wir uns hier beschäftigen. Wichtig ist, nicht einfach mir zu „glauben“, sondern in sich selbst ein Verständnis durch persönliche Erfahrung zu eröffnen - sowohl auf der Yogamatte als auch im Leben. Dann beginnen die Praktiken viel tiefer zu wirken. Andernfalls bekommen wir Gymnastik - denn dies ist das grundlegende Verständnis (die Erfahrung) des Yoga, das jeder hat. </p><p></p><p></p><p>Sie können diesen Intensivkurs mit folgenden Lehrprogrammen ergänzen:<br> - Praktikum «Monat der Kraft»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Kurs «Verwirkliche den Traum»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yoga-Praktiken</strong><br> Die Yoga-Praktiken, die Sie erwarten, unterscheiden sich von dem, was Sie in einem Fitnesscenter antreffen können. Ich gehe davon aus, dass Ihnen das Ergebnis wichtig ist und nicht die Schauspielerei. Wir arbeiten mit inneren Zuständen (das heißt mit Energien) und verbinden Meditation, Pranayama und Asanas in dem Maße, wie es nötig ist, um das gewünschte Ergebnis auf möglichst tiefer Ebene zu erzielen. Die meisten Praktiken beginnen mit einer kurzen Einführung, die notwendig ist, damit Ihr Bewusstsein von der Alltäglichkeit auf die Welle der Praxis umschaltet, Sie in den entsprechenden energetischen Fluss eintreten und Ihr inneres Vorhaben aktiviert wird. Danach folgt die eigentliche Praxis, die an verschiedenen Tagen eine unterschiedliche Dauer und Zusammensetzung der Elemente hat. Nach der Praxis empfehle ich Ihnen, einige Zeit in Meditation zu verweilen, und vielleicht im entstandenen Zustand der Achtsamkeit weiter Asanas auszuführen, die Ihr Körper erbitten wird. Die durchschnittliche Dauer der Praktiken beträgt 30-40 Minuten. Aber manche Praktiken sind kürzer, und manche dauern etwa eine Stunde. Wichtig ist, dass Sie während der Praxis nichts ablenkt und nichts zur Eile treibt. Und noch sehr wichtig – wenn Sie die Praxis begonnen haben, unterbrechen Sie sie nicht bis zu ihrem Ende!!! Jede Praxis ist eine lebendige Geschichte, die Sie einen bestimmten Weg entlangführt. Wenn Sie die Praxis unterbrechen, können Sie in einem weniger ressourcenreichen Zustand landen, als Sie zu Beginn waren. Auch wenn Ihnen diese Worte jetzt wie Mystifikation und leere Esoterik erscheinen mögen, hören Sie auf meine Empfehlungen. <br>  <br><strong>3. Verhaltenspraktiken</strong><br> Jeden Tag werde ich Ihnen im Brief zusammen mit der Yoga-Praxis einen „Tipp des Tages“ schicken. Versuchen Sie, ihn nicht als einen weiteren klugen Gedanken zu betrachten, von der Art, wie Sie sie schon viele Male gehört haben. Ich habe nicht das Ziel, Sie zu überraschen, indem ich etwas sage, das Sie noch nicht gehört haben. Betrachten Sie diesen „Tipp“ als Aufgabe, als Verhaltenspraxis! Führen Sie diese Praxis an diesem Tag aus. Und glauben Sie mir – es wird Ihnen viel interessanter werden, und dieser Intensivkurs wird Ihnen viel mehr Nutzen bringen. Manche solcher Praktiken mögen Ihnen einfacher erscheinen, manche schwieriger. Manche pragmatischer, manche psychologischer. In jedem Fall ist es nicht so, als hätte ich Ihnen vorgeschlagen, 20 Kniebeugen zu machen. Hier arbeiten wir mit Ihren Verhaltens- und psychologischen Mustern. Und der Schlüssel zum Erfolg liegt darin, nicht mit sich zu kämpfen, keine zusätzliche innere Spannung zu erzeugen, sondern wie in den Asanas zu atmen und sich zu entspannen. Deshalb klingt die Praxis sanft – wie ein „Tipp des Tages“ –, damit kein Alarmsignal ausgelöst wird. Lesen Sie ihn, probieren Sie ihn aus, versuchen Sie im Laufe des Tages, diesem Tipp sanft zu folgen oder ihn wenigstens in Erinnerung zu rufen, ihn erneut anzuprobieren und in das Gefühl zurückzukehren, dass Sie ihm folgen. Passen Sie sich an die neuen Zustände an... In manchen Fällen kann sich eine solche Praxis über mehrere Tage oder sogar Monate erstrecken, weil Sie ihre Bedeutung spüren und beginnen, sie auf der Ebene der Gewohnheit in Ihr Leben einzuführen, das heißt, die aktuelle Homöostase des Systems zu korrigieren. Und obwohl ich keine klare Verbindung zwischen den Verhaltenspraktiken und den Yoga-Praktiken, die ich in einem Brief anbiete, angelegt habe, können Sie dennoch jede Yoga-Praxis in dem Zustand ausführen, der entsteht, wenn Sie sich als jemanden wahrnehmen, der meinem Tipp folgt. Das ist jedoch keineswegs zwingend, da jede dieser beiden Praktiken für sich genügt.<br>  <br><strong>4. Zeitplan der Übungen</strong><br> Jeden Tag um Mitternacht wird Ihnen eine neue Praxis freigeschaltet (die vorherige verschwindet dabei, wie der vergangene Tag). Durch diesen Ansatz wird sich bei Ihnen kein Schneeball unerledigter Praktiken ansammeln. Innerhalb von 24 Stunden können Sie jede Ihnen passende Zeit wählen und praktizieren. Ich empfehle Ihnen, morgens zu praktizieren, um den Tag in dem durch die Praxis entstandenen Zustand zu erleben, statt sich schlafen zu legen. Betrachten Sie diesen Intensivkurs nicht als Computer-Illusion, sondern als reales Leben – in dem alles Wichtige HEUTE geschieht und sich die Yoga-Praxis von der Matte auf den Raum Ihrer Manifestation in der Welt ausdehnt, die Sie als die realste wahrnehmen!</p><p></p><p></p><p>Übrigens gibt es eine kleine Besonderheit mit dem Zeitpunkt, zu dem Sie die zweite Praxis erhalten. Wenn Sie sich vor 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis in der nächsten Mitternacht. Wenn Sie sich jedoch nach 18:00 Uhr angemeldet haben, erhalten Sie die zweite Praxis nicht in der nächsten, sondern in der darauffolgenden Mitternacht. Das heißt, Sie haben einen Zeitpuffer für den Fall, dass Sie die Praxis am Tag der Anmeldung zum Intensivkurs nicht mehr schaffen. <br>  <br><strong>5. Zwingen Sie sich nicht</strong><br> Wenn Sie ein Monatsabo in einem Fitnesscenter kaufen, verstehen Sie doch, dass Sie nicht unbedingt jeden Tag hingehen müssen? Mehr noch: Wenn Sie ein zu schnelles Tempo anschlagen, können Sie die Übungen aufgeben, ohne sogar das Ende des Monats erreicht zu haben... Für die Praktiken dieses Intensivkurses gilt dieselbe Regel – seien Sie nicht gierig! Praktizieren Sie in einem Ihnen angenehmen Rhythmus – jeden zweiten Tag, jeden dritten... Natürlich ist es gut, jeden Tag zu praktizieren, aber noch besser ist es, seine langfristigen Aufgaben zu verstehen und entsprechend zu handeln. Höchstwahrscheinlich gehen Ihre Aufgaben über einen Monat hinaus, und Sie müssen über einen längeren Zeitraum regelmäßig handeln. Diesen Intensivkurs habe ich so konzipiert, dass Sie ihn Monat für Monat so oft durchlaufen können, wie es nötig ist, bis das von Ihnen gesetzte Ziel erreicht ist. Diese Strategie ist effektiver, als einen Monat lang Vollgas zu geben und dann die Praktiken aufzugeben oder in eine andere Richtung davonzustürmen.<br>  <br><strong>6. Sicherheitstechnik</strong><br> Ich kümmere mich um Ihre Gesundheit und erinnere daran, dass allein Sie die Verantwortung dafür tragen, dass die Ausführung der Asanas, Pranayamas und Meditationen, die ich anbieten werde, Ihren körperlichen Möglichkeiten und Ihrem psychischen Zustand angemessen ist. Wichtig zu verstehen ist, dass dies Online-Kurse sind und ich Ihren Zustand nicht kontrollieren kann. Bei Ihnen können körperliche und psychologische Besonderheiten vorliegen. Bitte seien Sie aufmerksam gegenüber Ihrem Zustand. Wenn Sie spüren, dass eine bestimmte Asana, die ich zur Ausführung anbiete, für Sie verfrüht ist, führen Sie sie nicht sehr tief aus, auf einem Kompromissniveau, oder ersetzen Sie sie ganz durch eine andere Asana – eine, die den Körper ungefähr ebenfalls einbezieht, aber für Sie einfacher ist.<br>  <br><strong>7. Antworten auf Fragen</strong><br> Jede Woche (normalerweise samstags) führe ich in Zoom Gruppen-Online-Konsultationen (Webinare) durch, in denen wir uns austauschen, die Motivation aufrechterhalten und auftretende Schwierigkeiten und Fragen besprechen. Vor jeder solchen Konsultation werde ich Ihnen eine E-Mail mit Angabe von Datum und Uhrzeit ihrer Durchführung sowie einem Link zum Beitreten schicken. Was für Sie interessant ist, wird sicherlich auch für viele andere interessant sein. Deshalb ist die Besprechung von Fragen in den Gruppenkonsultationen am effektivsten. Sollte es geschehen, dass die Zeit der Konsultation für Sie ungünstig ist, senden Sie in diesem Fall Ihre Fragen vor ihrem Beginn per E-Mail. Ich werde sie in der Konsultation beantworten und Ihnen einen Link zur Aufzeichnung schicken, damit Sie sie zu einer Ihnen passenden Zeit ansehen können. Die Aufzeichnungen der Konsultationen werden eine Woche lang gespeichert.<br> <br>Ich wünsche Ihnen fruchtbare Praktiken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Je suis heureux que vous ayez décidé de travailler pendant un mois de manière ciblée avec le septième chakra, c''est-à-dire de diriger l''attention vers les états transcendants que nous percevons avec un tremblement de l''âme, comme un contact avec Dieu. À première vue, j''ai énuméré des états naturels propres à de nombreuses personnes. Cependant, dans la société, il existe de nombreux scénarios à la fois incitatifs et prohibitifs, qui gouvernent notre comportement, conduisant parfois à ce que la vie devienne matérialiste, remplie de peurs existentielles, d''un sentiment d''absurdité… En pratiquant aussi bien sur le tapis de yoga que dans la vie, en réfléchissant, en corrigeant ses pensées et ses actes, on peut, pendant un mois, obtenir des résultats importants, qui se manifesteront tant au niveau du corps (guérison) qu''au niveau du fond psychologique (satisfaction et bonheur).</p><p></p><p></p><p>Pendant 30 jours, vous recevrez 30 pratiques destinées à harmoniser le septième chakra. Lisez attentivement cette lettre pour comprendre ce qui va se passer et comment. <br> <br><strong>1. L’essentiel</strong><br> Ce n’est pas un cours d’apprentissage, mais un atelier intensif dont le cœur est constitué de pratiques quotidiennes de yoga. J’ai mené ces pratiques le matin en direct, en synchronisant l’orientation de chaque pratique avec les rythmes planétaires de ce jour-là. Dans cet intensif, j’ai réuni des enregistrements vidéo des meilleures pratiques qui étaient précisément destinées au premier chakra (parfois en interaction avec un autre chakra), et je les ai complétées par des pratiques comportementales (psychologiques). Il en est résulté une charge extrêmement puissante pour harmoniser le domaine de la santé. </p><p></p><p></p><p>Si vous n''avez pas suivi mes cours et ne comprenez pas ce que vient faire ici une quelconque « septième chakra », je vous recommande d''associer le passage de cet intensif à un atelier pratique ou à un cours dans lequel je vous amène progressivement à comprendre ce que nous faisons ici. Il est important non pas simplement de « me croire », mais d''ouvrir en vous une compréhension par l''expérience personnelle - aussi bien sur le tapis de yoga que dans la vie. Alors les pratiques commencent à agir beaucoup plus profondément. Sinon, on obtient de la gym - car c''est la compréhension (l''expérience) de base du yoga que chacun possède. </p><p></p><p></p><p>Vous pouvez compléter cet intensif par les programmes d''étude suivants :<br> - Atelier pratique « Mois de force » : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Cours « Réalise ton rêve » : <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Pratiques de yoga</strong><br> Les pratiques de yoga qui vous attendent diffèrent de ce que vous pouvez rencontrer dans un centre de fitness. Je suppose que le résultat vous importe, et non le jeu d’acteur. Nous travaillons avec les états intérieurs (c’est-à-dire avec les énergies), en unissant la méditation, le pranayama et les asanas dans la mesure nécessaire pour obtenir le résultat souhaité au niveau le plus profond possible. La plupart des pratiques commencent par une courte introduction, nécessaire pour que votre conscience passe du quotidien à la vague de la pratique, que vous entriez dans le flux énergétique correspondant et que votre intention intérieure s’active. Vient ensuite la pratique elle-même, qui selon les jours a une durée et une composition d’éléments différentes. Après la pratique, je vous recommande de rester quelque temps en méditation, et peut-être, dans l’état de conscience apparu, de continuer à exécuter les asanas que votre corps demandera. La durée moyenne des pratiques est de 30-40 minutes. Mais certaines pratiques sont plus courtes, et d’autres durent environ une heure. Il est important que pendant la pratique rien ne vous distraie ni ne vous presse. Et encore très important - une fois la pratique commencée, ne l’interrompez pas avant sa fin!!! Chaque pratique est une histoire vivante qui vous conduit sur un chemin déterminé. En interrompant la pratique, vous pouvez vous retrouver dans un état moins pourvu en ressources que celui dans lequel vous étiez au début. Même si maintenant ces mots vous semblent une mystification et de l’ésotérisme vide, écoutez mes recommandations. <br>  <br><strong>3. Pratiques comportementales</strong><br> Chaque jour, dans l’e-mail, avec la pratique de yoga, je vous enverrai un « conseil du jour ». Essayez de le percevoir non pas comme une pensée intelligente de plus, semblable à celles que vous avez déjà entendues bien des fois. Je n’ai pas pour but de vous surprendre en disant ce que vous n’avez encore jamais entendu. Percevez ce « conseil » comme une tâche, comme une pratique comportementale ! Accomplissez cette pratique ce jour-là. Et croyez-moi - cela vous paraîtra beaucoup plus intéressant, et cet intensif vous apportera beaucoup plus de bienfaits. Certaines de ces pratiques peuvent vous sembler plus simples, d’autres plus difficiles. Certaines plus pragmatiques, d’autres plus psychologiques. Dans tous les cas, ce n’est pas comme si je vous proposais de faire 20 squats. Ici, nous travaillons avec vos schémas comportementaux et psychologiques. Et la clé du succès est de ne pas lutter contre vous-même, de ne pas provoquer une tension intérieure supplémentaire, mais, comme dans les asanas, de respirer et de vous détendre. C’est pourquoi la pratique se présente doucement - comme un « conseil du jour » - afin de ne pas déclencher de signal d’alarme. Lisez-le, essayez-le, tentez pendant la journée de suivre doucement ce conseil ou du moins de vous en souvenir, en l’essayant à nouveau et en revenant à la sensation que vous le suivez. Adaptez-vous aux nouveaux états... Dans certains cas, une telle pratique peut s’étendre sur plusieurs jours ou même plusieurs mois, parce que vous en ressentirez l’importance et commencerez à l’intégrer dans votre vie au niveau de l’habitude, c’est-à-dire en corrigeant l’homéostasie actuelle du système. Et, bien que je n’aie pas établi de lien précis entre les pratiques comportementales et les pratiques de yoga que je propose dans un même e-mail, vous pouvez néanmoins accomplir chaque pratique de yoga dans l’état apparu lorsque vous vous percevez comme suivant mon conseil. Cependant, ce n’est pas du tout obligatoire, car chacune de ces deux pratiques est autosuffisante.<br>  <br><strong>4. Horaire des séances</strong><br> Chaque jour à minuit, une nouvelle pratique s’ouvrira pour vous (la précédente disparaîtra alors, comme le jour précédent). Grâce à cette approche, les pratiques non accomplies ne s’accumuleront pas en boule de neige. Pendant les vingt-quatre heures, vous pouvez choisir n’importe quel moment qui vous convient et pratiquer. Je vous recommande de pratiquer le matin, afin de vivre la journée dans l’état obtenu grâce à la pratique, et non d’aller vous coucher. Percevez cet intensif non pas comme une illusion informatique, mais comme la vie réelle - dans laquelle tout ce qui est important se produit AUJOURD’HUI, et la pratique du yoga s’étend du tapis à l’espace de votre manifestation dans ce monde que vous percevez comme le plus réel !</p><p></p><p></p><p>À propos, il y a une petite nuance concernant le moment où vous recevez la deuxième pratique. Si votre inscription a eu lieu avant 18:00, vous recevrez la deuxième pratique à la prochaine minuit. Si en revanche votre inscription a eu lieu après 18:00, vous recevrez la deuxième pratique non pas à la prochaine minuit, mais à la minuit suivante. Autrement dit, vous aurez une marge de temps au cas où vous n’auriez pas le temps d’accomplir la pratique le jour de l’inscription à l’intensif. <br>  <br><strong>5. Ne vous forcez pas</strong><br> Lorsque vous achetez un abonnement mensuel dans un centre de fitness, vous comprenez bien que vous n’êtes pas obligé d’y aller chaque jour ? De plus, en prenant un rythme trop rapide, vous risquez d’abandonner les séances avant même d’arriver à la fin du mois... En ce qui concerne les pratiques de cet intensif, la même règle s’applique - ne soyez pas gourmand ! Pratiquez à un rythme qui vous convient - tous les deux jours, tous les trois jours... Bien sûr, il est bon de pratiquer chaque jour, mais il est encore mieux de comprendre vos tâches à long terme et d’agir en conséquence. Très probablement, vos tâches dépassent le cadre d’un mois, et vous devez agir régulièrement pendant une longue période. J’ai conçu cet intensif de manière à ce que vous puissiez le suivre mois après mois autant de fois que nécessaire, jusqu’à ce que l’objectif que vous vous êtes fixé soit atteint. Cette stratégie est plus efficace que de se donner à fond pendant un mois, puis d’abandonner les pratiques ou de partir dans une autre direction.<br>  <br><strong>6. Consignes de sécurité</strong><br> Je me soucie de votre santé et je vous rappelle que c’est vous qui portez la responsabilité de l’adéquation de l’exécution des asanas, des pranayamas et des méditations que je proposerai à vos possibilités physiques et à votre état psychique. Il est important de comprendre qu’il s’agit de séances en ligne et que je ne peux pas contrôler votre état. Vous pouvez avoir des particularités physiques et psychologiques. Veuillez être attentif à votre état. Si vous sentez qu’une asana que je propose d’exécuter est prématurée pour vous, exécutez-la pas très profondément, à un niveau de compromis, ou remplacez-la entièrement par une autre asana - telle qui sollicite à peu près autant le corps, mais qui est plus simple pour vous.<br>  <br><strong>7. Réponses aux questions</strong><br> Chaque semaine (généralement le samedi), j’anime sur Zoom des consultations en ligne de groupe (webinaires), pendant lesquelles nous échangeons, maintenons la motivation, discutons des difficultés et des questions qui surviennent. Avant chacune de ces consultations, je vous enverrai un e-mail indiquant la date et l’heure de sa tenue, ainsi qu’un lien pour la rejoindre. Ce qui vous intéresse intéressera sûrement aussi beaucoup d’autres personnes. C’est pourquoi il est plus efficace de discuter des questions lors des consultations de groupe. S’il arrive que l’heure de la consultation ne vous convienne pas, dans ce cas envoyez vos questions par e-mail avant son début. Je répondrai à ces questions lors de la consultation, et je vous enverrai un lien vers l’enregistrement afin que vous puissiez le regarder au moment qui vous convient. Les enregistrements des consultations sont conservés pendant une semaine.<br> <br>Je vous souhaite des pratiques fructueuses !</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Mi fa piacere che tu abbia deciso di lavorare per un mese in modo mirato con il settimo chakra, cioè di dirigere l''attenzione verso gli stati trascendenti che percepiamo con sacro timore, come un contatto con Dio. A prima vista, ho elencato stati naturali propri di molte persone. Tuttavia, nella società agiscono molti scenari, sia incentivanti sia inibitori, che governano il nostro comportamento, portando talvolta al fatto che la vita diventa materialistica, piena di paure esistenziali, di sensazione di mancanza di senso… Eseguendo le pratiche sia sul tappetino da yoga sia nella vita, riflettendo, correggendo i propri pensieri e le proprie azioni, nell''arco di un mese si possono ottenere risultati importanti, che si manifesteranno sia a livello del corpo (risanamento), sia a livello dello sfondo psicologico (soddisfazione e felicità).</p><p></p><p></p><p>In 30 giorni riceverai 30 pratiche volte ad armonizzare il settimo chakra. Leggi attentamente questa lettera per capire cosa e come accadrà. <br> <br><strong>1. L''essenza stessa</strong><br> Non è un corso didattico, ma un praticum intensivo, il cui nucleo sono le pratiche yoga quotidiane. Queste pratiche le ho condotte al mattino in diretta, sincronizzando la direzione di ogni pratica con i ritmi planetari di quel giorno. In questo intensivo ho raccolto le videoregistrazioni delle migliori pratiche, che erano dirette proprio al primo chakra (a volte in interazione con qualche altro chakra), e le ho integrate con pratiche comportamentali (psicologiche). Il risultato è stato una carica potentissima per l''armonizzazione dell''ambito della salute. </p><p></p><p></p><p>Se non hai seguito i miei corsi e non capisci cosa c''entri qui un qualche «settimo chakra», ti consiglio di abbinare la partecipazione a questo intensivo a un seminario pratico o a un corso in cui ti conduco gradualmente alla comprensione di ciò di cui ci occupiamo qui. È importante non semplicemente «credermi», ma aprire in te la comprensione attraverso l''esperienza personale - sia sul tappetino da yoga sia nella vita. Allora le pratiche iniziano a funzionare molto più in profondità. Altrimenti otteniamo ginnastica - poiché questa è la comprensione (esperienza) di base dello yoga che ciascuno ha. </p><p></p><p></p><p>Puoi integrare questo intensivo con i seguenti programmi didattici:<br> - Seminario pratico «Mese della forza»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Corso «Realizza il sogno»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Pratiche yoga</strong><br> Le pratiche yoga che vi attendono sono diverse da ciò che potete trovare in un centro fitness. Presumo che per voi conti il risultato, non la messa in scena. Lavoriamo con gli stati interiori (cioè con le energie), unendo meditazione, pranayama e asana nella misura necessaria per ottenere il risultato desiderato al livello più profondo possibile. La maggior parte delle pratiche inizia con una breve introduzione, necessaria affinché la vostra coscienza passi dalla quotidianità all''onda della pratica, entriate nel corrispondente flusso energetico e si attivi la vostra intenzione interiore. Segue poi la pratica stessa, che nei diversi giorni ha durata e composizione di elementi diverse. Dopo la pratica vi raccomando di restare per un po'' in meditazione, e magari, nello stato di consapevolezza che è emerso, di continuare a eseguire le asana che il vostro corpo chiederà. La durata media delle pratiche è di 30-40 minuti. Ma alcune pratiche sono più brevi, e alcune durano circa un''ora. È importante che durante la pratica nulla vi distragga e vi metta fretta. E ancora molto importante - una volta iniziata la pratica, non interrompetela prima della fine!!! Ogni pratica è una storia viva, che vi conduce lungo un determinato percorso. Interrompendo la pratica, potete ritrovarvi in uno stato meno ricco di risorse di quello in cui eravate all''inizio. Anche se ora queste parole vi sembrano una mistificazione e vuoto esoterismo, ascoltate le mie raccomandazioni. <br>  <br><strong>3. Pratiche comportamentali</strong><br> Ogni giorno, nella lettera insieme alla pratica yoga, vi invierò il «consiglio del giorno». Provate a percepirlo non come un altro pensiero intelligente, simile al quale ne avete già sentiti molti. Non ho l''obiettivo di sorprendervi dicendo qualcosa che non avete ancora sentito. Percepite questo «consiglio» come un compito, come una pratica comportamentale! Eseguite questa pratica nel giorno dato. E credetemi - vi risulterà molto più interessante, e questo intensivo vi porterà molto più beneficio. Alcune di queste pratiche possono sembrarvi più semplici, alcune più difficili. Alcune più pragmatiche, alcune più psicologiche. In ogni caso, non è come se vi avessi proposto di fare 20 squat. Qui lavoriamo con i vostri schemi comportamentali e psicologici. E la chiave del successo sta nel non combattere con voi stessi, nel non provocare ulteriore tensione interiore, ma, come nelle asana, respirare e rilassarvi. Perciò la pratica suona morbida - come «consiglio del giorno» - per non attivare un segnale d''allarme. Leggete, provate su di voi, provate durante la giornata a seguire dolcemente questo consiglio o almeno a ricordarlo, provandolo di nuovo e tornando alla sensazione che lo state seguendo. Adattatevi ai nuovi stati... In alcuni casi una sola pratica del genere può protrarsi per diversi giorni o addirittura mesi, perché ne sentirete l''importanza e inizierete a introdurla nella vostra vita a livello di abitudine, cioè correggendo l''attuale omeostasi del sistema. E, sebbene io non abbia previsto un legame preciso tra le pratiche comportamentali e le pratiche yoga che propongo in una stessa lettera, potete comunque eseguire ogni pratica yoga nello stato che emerge quando percepite voi stessi come seguaci del mio consiglio. Tuttavia, questo non è affatto obbligatorio, poiché ciascuna di queste due pratiche è autosufficiente.<br>  <br><strong>4. Orario delle lezioni</strong><br> Ogni giorno a mezzanotte vi si aprirà una nuova pratica (quella precedente scomparirà, come il giorno passato). Grazie a questo approccio, non si accumulerà una palla di neve di pratiche non eseguite. Nell''arco delle ventiquattro ore potete scegliere qualsiasi momento conveniente per voi e fare pratica. Vi raccomando di praticare al mattino, per vivere la giornata nello stato ottenuto grazie alla pratica, e non andare a dormire. Percepite questo intensivo non come un''illusione informatica, ma come vita reale - in cui tutto ciò che è importante accade OGGI, e la pratica yoga si espande dal tappetino allo spazio della vostra manifestazione in quel mondo che percepite come il più reale!</p><p></p><p></p><p>A proposito, c''è una piccola sfumatura riguardo al momento in cui riceverete la seconda pratica. Se vi siete iscritti prima delle 18:00, riceverete la seconda pratica alla mezzanotte più vicina. Se invece vi siete iscritti dopo le 18:00, riceverete la seconda pratica non alla mezzanotte più vicina, ma a quella successiva. Cioè avrete un margine di tempo nel caso non riusciate a completare la pratica nel giorno dell''iscrizione all''intensivo. <br>  <br><strong>5. Non fatevi violenza</strong><br> Quando acquistate un abbonamento mensile in un centro fitness, capite bene che non dovete per forza andarci ogni giorno? Inoltre, prendendo un ritmo troppo veloce, potete abbandonare le lezioni senza nemmeno arrivare alla fine del mese... Riguardo alle pratiche di questo intensivo vale la stessa regola - non siate avidi! Praticate al ritmo che vi è comodo - a giorni alterni, ogni due... Certo, è bene praticare ogni giorno, ma ancora meglio è capire i propri compiti a lungo termine e agire di conseguenza. Molto probabilmente i vostri compiti vanno oltre un mese, e avete bisogno di agire regolarmente per lungo tempo. Ho concepito questo intensivo in modo che possiate seguirlo mese dopo mese tutte le volte che serve, finché l''obiettivo che vi siete posti non sarà raggiunto. Questa strategia è più efficace che darci dentro per un mese e poi abbandonare le pratiche o lanciarsi in un''altra direzione.<br>  <br><strong>6. Tecnica di sicurezza</strong><br> Mi prendo cura della vostra salute e vi ricordo che solo voi siete responsabili dell''adeguatezza dell''esecuzione delle asana, dei pranayama e delle meditazioni che vi proporrò rispetto alle vostre possibilità fisiche e al vostro stato psichico. È importante capire che queste sono lezioni online e io non posso controllare il vostro stato. Potete avere particolarità fisiche e psicologiche. Per favore, siate attenti al vostro stato. Se sentite che qualche asana che vi propongo di eseguire è per voi prematura, eseguitela non molto profondamente, a un livello di compromesso, oppure sostituitela del tutto con un''altra asana - tale che coinvolga approssimativamente allo stesso modo il corpo, ma sia più semplice per voi.<br>  <br><strong>7. Risposte alle domande</strong><br> Ogni settimana (di solito il sabato) tengo su Zoom consultazioni online di gruppo (webinar), durante le quali comunichiamo, sosteniamo la motivazione, discutiamo le difficoltà e le domande che emergono. Prima di ciascuna di queste consultazioni vi invierò un''email con l''indicazione della data e dell''ora in cui si svolgerà, nonché il link per parteciparvi. Ciò che interessa a voi sarà sicuramente interessante anche per molti altri. Perciò, discutere le domande durante le consultazioni di gruppo è più efficace. Se accadesse che l''orario della consultazione non vi sia comodo, in questo caso inviate le vostre domande via email prima del suo inizio. Risponderò loro durante la consultazione, e vi invierò il link alla registrazione, così potrete guardarla nel momento per voi più comodo. Le registrazioni delle consultazioni vengono conservate per una settimana.<br> <br>Vi auguro pratiche fruttuose!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>Me alegra que se hayan decidido durante un mes a trabajar de manera intencionada con el séptimo chakra, es decir, dirigir la atención hacia estados trascendentes que percibimos con sobrecogimiento del alma, como contacto con Dios. A primera vista, he enumerado estados naturales propios de muchas personas. Sin embargo, en la sociedad actúan muchos guiones tanto incentivadores como prohibitivos que gobiernan nuestra conducta, llevando a veces a que la vida se vuelva materialista, llena de miedos existenciales, de sensación de sinsentido… Realizando prácticas tanto en la esterilla de yoga como en la vida, reflexionando, corrigiendo sus pensamientos y actos, durante un mes se pueden obtener resultados importantes que se manifestarán tanto a nivel del cuerpo (sanación) como a nivel del fondo psicológico (satisfacción y felicidad).</p><p></p><p></p><p>Durante 30 días recibirá 30 prácticas dirigidas a armonizar el séptimo chakra. Lea atentamente esta carta para comprender qué y cómo sucederá. <br> <br><strong>1. La esencia misma</strong><br> Esto no es un curso de formación, sino un taller intensivo cuyo núcleo son las prácticas diarias de yoga. Estas prácticas las realizaba por las mañanas en directo, sincronizando la dirección de cada práctica con los ritmos planetarios de ese día. En este intensivo he reunido grabaciones de vídeo de las mejores prácticas, que estaban dirigidas precisamente al primer chakra (a veces en interacción con algún otro chakra), y las he complementado con prácticas conductuales (psicológicas). Como resultado, se ha obtenido una carga poderosísima para armonizar el ámbito de la salud. </p><p></p><p></p><p>Si usted no ha tomado mis cursos y no entiende qué tiene que ver aquí esa tal «séptimo chakra», le recomiendo combinar la realización de este intensivo con un prácticum o un curso en el que conduzco suavemente hacia la comprensión de lo que hacemos aquí. Es importante no simplemente «creerme», sino abrir en usted la comprensión a través de la experiencia personal, tanto en la esterilla de yoga como en la vida. Entonces las prácticas comienzan a funcionar mucho más profundamente. De lo contrario, obtenemos educación física, ya que es la comprensión (experiencia) básica del yoga que cada uno tiene. </p><p></p><p></p><p>Puede complementar este intensivo con los siguientes programas de estudio:<br> - Prácticum «Mes de la fuerza»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Curso «Haz realidad el sueño»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Prácticas de yoga</strong><br> Las prácticas de yoga que le esperan se diferencian de lo que puede encontrar en un centro de fitness. Supongo que para usted es importante el resultado, y no el teatro. Trabajamos con estados internos (es decir, con energías), uniendo meditación, pranayama y asanas en la medida necesaria para obtener el resultado deseado al nivel más profundo posible. La mayoría de las prácticas comienzan con una breve introducción, necesaria para que su conciencia cambie de lo cotidiano a la onda de la práctica, entre en el flujo energético correspondiente y se active su intención interna. Después sigue la práctica en sí, que en distintos días tiene distinta duración y composición de elementos. Después de la práctica, le recomiendo permanecer un tiempo en meditación y, tal vez, en el estado de conciencia que haya surgido, continuar realizando las asanas que su cuerpo le pida. La duración media de las prácticas es de 30-40 minutos. Pero algunas prácticas son más cortas y otras duran cerca de una hora. Es importante que durante la práctica nada le distraiga ni le apresure. Y además es muy importante: una vez comenzada la práctica, ¡no la interrumpa hasta que termine!!! Cada práctica es una historia viva que le conduce por un camino determinado. Si interrumpe la práctica, puede encontrarse en un estado con menos recursos que aquel en el que estaba al comenzarla. Aunque ahora estas palabras le parezcan una mistificación y esoterismo vacío, haga caso a mis recomendaciones. <br>  <br><strong>3. Prácticas conductuales</strong><br> Cada día, en la carta, junto con la práctica de yoga, le enviaré el «consejo del día». Intente percibirlo no como una idea inteligente más, de las cuales ya ha oído muchas. No tengo el objetivo de sorprenderle diciendo algo que aún no haya oído. Perciba este «consejo» como una tarea, ¡como una práctica conductual! Realice esta práctica en el día indicado. Y créame: se sentirá mucho más interesado, y este intensivo le aportará mucho más beneficio. Algunas de estas prácticas pueden parecerle más fáciles, otras más difíciles. Algunas más pragmáticas, otras más psicológicas. En cualquier caso, no es como si le propusiera hacer 20 sentadillas. Aquí trabajamos con sus patrones conductuales y psicológicos. Y la clave del éxito está en no luchar contra uno mismo, no generar una tensión interna adicional, sino, como en las asanas, respirar y relajarse. Por eso la práctica suena suave, como «consejo del día», para no activar una señal de alarma. Léalo, pruébeselo, intente durante el día seguir suavemente este consejo o al menos recordarlo, probándoselo de nuevo y regresando a la sensación de que lo sigue. Adáptese a los nuevos estados... En algunos casos, una sola práctica así puede extenderse durante varios días o incluso meses, porque sentirá su importancia y comenzará a incorporarla a su vida a nivel de hábito, es decir, corrigiendo la homeostasis actual del sistema. Y, aunque no establecí una conexión clara entre las prácticas conductuales y las prácticas de yoga que propongo en una misma carta, aun así puede realizar cada práctica de yoga en el estado que surja cuando se percibe a sí mismo siguiendo mi consejo. Sin embargo, esto no es en absoluto obligatorio, ya que cada una de estas dos prácticas es autosuficiente.<br>  <br><strong>4. Horario de las clases</strong><br> Cada día, a medianoche, se le abrirá una nueva práctica (la anterior desaparecerá, como el día anterior). Gracias a este enfoque, no se le irá acumulando una bola de nieve de prácticas sin hacer. A lo largo del día puede elegir el momento que más le convenga y practicar. Le recomiendo practicar por la mañana, para vivir el día en el estado obtenido como resultado de la práctica, y no irse a dormir. Perciba este intensivo no como una ilusión informática, sino como la vida real, en la que todo lo importante ocurre HOY, y la práctica de yoga se expande desde la esterilla al espacio de su manifestación en el mundo que usted percibe como el más real.</p><p></p><p></p><p>Por cierto, hay un pequeño matiz con la hora de recepción de la segunda práctica. Si se inscribió antes de las 18:00, recibirá la segunda práctica en la próxima medianoche. Si se inscribió después de las 18:00, recibirá la segunda práctica no en la próxima medianoche, sino en la siguiente. Es decir, tendrá un margen de tiempo por si no logra realizar la práctica el día de la inscripción al intensivo. <br>  <br><strong>5. No se fuerce</strong><br> Cuando compra un abono mensual en un centro de fitness, entiende que no es obligatorio ir todos los días, ¿verdad? Además, si adopta un ritmo demasiado rápido, puede abandonar las clases sin haber llegado ni siquiera a fin de mes... Con las prácticas de este intensivo rige la misma regla: ¡no sea codicioso! Practique a un ritmo que le resulte cómodo: un día sí y otro no, cada dos días... Claro que es bueno practicar todos los días, pero aún mejor es comprender sus objetivos a largo plazo y actuar en consecuencia. Lo más probable es que sus objetivos vayan más allá de un mes, y necesite actuar con regularidad durante un tiempo prolongado. Concebí este intensivo para que pueda recorrerlo mes tras mes tantas veces como sea necesario, hasta que se alcance el objetivo que se ha propuesto. Esta estrategia es más eficaz que entregarse a tope durante un mes y luego abandonar las prácticas o lanzarse en otra dirección.<br>  <br><strong>6. Técnica de seguridad</strong><br> Me preocupo por su salud y le recuerdo que solo usted es responsable de la adecuación de la ejecución de las asanas, pranayamas y meditaciones que le propondré a sus posibilidades físicas y a su estado psíquico. Es importante comprender que son clases en línea, y no puedo controlar su estado. Usted puede tener particularidades físicas y psicológicas. Por favor, sea atento a su estado. Si siente que alguna asana que le propongo realizar es prematura para usted, ejecútela no muy profundamente, en un nivel de compromiso, o sustitúyala por completo por otra asana, una que incluya el cuerpo aproximadamente de la misma manera pero que le resulte más sencilla.<br>  <br><strong>7. Respuestas a las preguntas</strong><br> Cada semana (normalmente los sábados) realizo en Zoom consultas grupales en línea (webinars), en las que conversamos, mantenemos la motivación y discutimos las dificultades y preguntas que surgen. Antes de cada una de estas consultas le enviaré una carta con la fecha y la hora de su realización, así como un enlace para unirse a ella. Lo que es interesante para usted seguramente también lo será para muchas otras personas. Por eso, la discusión de preguntas en las consultas grupales es lo más eficaz. Si ocurre que la hora de la consulta le resulta inconveniente, en ese caso envíe sus preguntas por correo electrónico antes de su comienzo. Las responderé en la consulta y le enviaré un enlace a la grabación para que pueda verla en el momento que le resulte cómodo. Las grabaciones de las consultas se conservan durante una semana.<br> <br>¡Le deseo prácticas fructíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Fico feliz que você tenha decidido trabalhar intencionalmente com o sétimo chakra durante um mês, ou seja, direcionar a atenção para estados transcendentes que percebemos com reverência, como um contato com Deus. À primeira vista, enumerei estados naturais próprios de muitas pessoas. No entanto, na sociedade atuam muitos cenários tanto incentivadores quanto proibitivos, que governam nosso comportamento, por vezes levando a que a vida se torne materialista, repleta de medos existenciais, sensação de falta de sentido… Ao realizar as práticas tanto no tapete de yoga quanto na vida, refletindo, corrigindo seus pensamentos e ações, ao longo de um mês é possível obter resultados importantes, que se manifestarão tanto no nível do corpo (melhora da saúde) quanto no nível do fundo psicológico (satisfação e felicidade).</p><p></p><p></p><p>Ao longo de 30 dias, você receberá 30 práticas voltadas para a harmonização do sétimo chakra. Leia atentamente esta carta para entender o que e como acontecerá. <br> <br><strong>1. A própria essência</strong><br> Este não é um curso de estudo, mas um praticum intensivo, cujo núcleo são as práticas diárias de yoga. Eu conduzia essas práticas pela manhã ao vivo, sincronizando a direção de cada prática com os ritmos planetários daquele dia. Neste intensivo, reuni gravações em vídeo das melhores práticas que eram direcionadas justamente ao primeiro chakra (às vezes em interação com algum outro chakra), e as complementei com práticas comportamentais (psicológicas). O resultado foi uma carga poderosíssima para harmonizar a esfera da saúde. </p><p></p><p></p><p>Se você não fez meus cursos e não entende o que tem a ver com isso algum «sétimo chakra» aí, recomendo combinar a realização deste intensivo com um praticum ou curso no qual eu conduzo suavemente à compreensão do que fazemos aqui. É importante não apenas «acreditar» em mim, mas abrir em você a compreensão por meio da experiência pessoal - tanto no tapete de yoga quanto na vida. Então as práticas começam a funcionar muito mais profundamente. Caso contrário, obtemos ginástica - pois esta é a compreensão (experiência) básica do yoga que cada um tem. </p><p></p><p></p><p>Você pode complementar este intensivo com os seguintes programas de estudo:<br> - Praticum «Mês da Força»: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Curso «Realize o Sonho»: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Práticas de yoga</strong><br> As práticas de yoga que você terá pela frente diferem daquilo que você pode encontrar em uma academia de ginástica. Presumo que para você o resultado é importante, e não a teatralidade. Trabalhamos com estados internos (ou seja, com energias), unindo meditação, pranayama e asanas na medida necessária para obter o resultado desejado no nível mais profundo possível. A maioria das práticas começa com uma pequena introdução, necessária para que sua consciência se desligue da cotidianidade e entre na onda da prática, você entre no fluxo energético correspondente e sua intenção interna se ative. Em seguida vem a própria prática, que em dias diferentes tem duração e composição de elementos diferentes. Depois da prática, recomendo que você fique algum tempo em meditação e, talvez, no estado de consciência que surgir, continue executando as asanas que seu corpo pedir. A duração média das práticas é de 30 a 40 minutos. Mas algumas práticas são mais curtas, e algumas duram cerca de uma hora. É importante que durante a prática nada o distraia nem o apresse. E é ainda muito importante - tendo começado a prática, não a interrompa até o final!!! Cada prática é uma história viva que o conduz por um determinado caminho. Se interromper a prática, você pode acabar em um estado com menos recursos do que aquele em que estava no início dela. Mesmo que agora estas palavras lhe pareçam mistificação e esoterismo vazio, escute minhas recomendações. <br>  <br><strong>3. Práticas comportamentais</strong><br> Todos os dias, no e-mail, junto com a prática de yoga, enviarei a você o «conselho do dia». Tente não percebê-lo como mais um pensamento inteligente, semelhante aos que você já ouviu muitas vezes. Não tenho o objetivo de surpreendê-lo dizendo algo que você ainda não ouviu. Perceba esse «conselho» como uma tarefa, como uma prática comportamental! Execute essa prática no dia em questão. E acredite - vai se tornar muito mais interessante para você, e este intensivo lhe trará muito mais benefício. Algumas dessas práticas podem parecer-lhe mais simples, outras mais difíceis. Algumas mais pragmáticas, outras mais psicológicas. Em qualquer caso, não é como se eu tivesse proposto a você agachar 20 vezes. Aqui trabalhamos com seus padrões comportamentais e psicológicos. E a chave do sucesso está em não lutar consigo mesmo, não provocar tensão interna adicional, mas, como nas asanas, respirar e relaxar. Por isso a prática soa suave - como «conselho do dia» - para não provocar o sinal de alarme. Leia, experimente, tente ao longo do dia seguir suavemente esse conselho ou ao menos lembrar dele, experimentando-o de novo e retornando à sensação de que o está seguindo. Adapte-se aos novos estados... Em alguns casos, uma dessas práticas pode se estender por vários dias ou até meses, porque você sentirá sua importância e começará a introduzi-la em sua vida no nível do hábito, ou seja, corrigindo a homeostase atual do sistema. E, embora eu não tenha estabelecido uma ligação clara entre as práticas comportamentais e as práticas de yoga que proponho em um mesmo e-mail, ainda assim você pode executar cada prática de yoga no estado que surgir quando você se percebe seguindo meu conselho. No entanto, isso não é de modo algum obrigatório, pois cada uma dessas duas práticas é autossuficiente.<br>  <br><strong>4. Horário das aulas</strong><br> Todos os dias, à meia-noite, uma nova prática será aberta para você (a anterior desaparecerá, como o dia anterior). Graças a essa abordagem, não se acumulará em você uma bola de neve de práticas não realizadas. Ao longo do dia, você pode escolher o horário que lhe for conveniente e praticar. Recomendo que você pratique pela manhã, para viver o dia no estado obtido como resultado da prática, e não para ir dormir. Perceba este intensivo não como uma ilusão de computador, mas como a vida real - na qual tudo o que é importante acontece HOJE, e a prática de yoga se expande do tapete para o espaço da sua manifestação naquele mundo que você percebe como o mais real!</p><p></p><p></p><p>A propósito, há um pequeno detalhe com o horário de recebimento da segunda prática. Se você se inscreveu antes das 18:00, receberá a segunda prática na próxima meia-noite. Mas se se inscreveu depois das 18:00, receberá a segunda prática não na próxima meia-noite, mas na meia-noite seguinte. Ou seja, você terá uma reserva de tempo caso não consiga realizar a prática no dia da inscrição no intensivo. <br>  <br><strong>5. Não se force</strong><br> Quando você compra uma mensalidade em uma academia, você entende que não precisa ir lá todos os dias, certo? Mais do que isso, se pegar um ritmo rápido demais, você pode abandonar os treinos antes mesmo do fim do mês... Em relação às práticas deste intensivo, vale a mesma regra - não seja ganancioso! Pratique no ritmo que lhe for conveniente - um dia sim, dois não... Claro, é bom praticar todos os dias, mas ainda melhor é entender suas tarefas de longo prazo e agir de acordo. Muito provavelmente, suas tarefas vão além de um mês, e você precisa agir regularmente por um longo tempo. Concebi este intensivo de modo que você possa percorrê-lo mês após mês, quantas vezes for necessário, até que o objetivo que você estabeleceu seja alcançado. Essa estratégia é mais eficaz do que se entregar a fundo por um mês e depois abandonar as práticas ou partir para outra direção.<br>  <br><strong>6. Técnica de segurança</strong><br> Eu me preocupo com sua saúde e lembro que somente você é responsável pela adequação da execução das asanas, pranayamas e meditações que eu proporei às suas possibilidades físicas e ao seu estado psíquico. É importante entender que estas são aulas on-line, e eu não posso controlar seu estado. Você pode ter particularidades físicas e psicológicas. Por favor, esteja atento ao seu estado. Se você sentir que alguma asana que proponho executar é prematura para você, execute-a não muito profundamente, em um nível de meio-termo, ou substitua-a totalmente por outra asana - que envolva o corpo de modo aproximadamente semelhante, mas seja mais simples para você.<br>  <br><strong>7. Respostas às perguntas</strong><br> Toda semana (normalmente aos sábados) realizo no Zoom consultorias on-line em grupo (webinars), nas quais conversamos, mantemos a motivação, discutimos as dificuldades e dúvidas que surgem. Antes de cada consultoria dessas, enviarei a você um e-mail com a data e o horário de sua realização, bem como o link para se juntar a ela. O que é interessante para você certamente também será interessante para muitas outras pessoas. Por isso, discutir as questões nas consultorias em grupo é o mais eficaz. Se acontecer de o horário da consultoria ser inconveniente para você, nesse caso envie suas perguntas por e-mail antes de ela começar. Eu responderei a elas na consultoria e enviarei a você o link da gravação, para que possa assisti-la no horário que lhe for conveniente. As gravações das consultorias ficam salvas por uma semana.<br> <br>Desejo a você práticas frutíferas!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-1-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>Ik ben blij dat je hebt besloten om een maand lang gericht met de zevende chakra te werken, dat wil zeggen de aandacht te richten op transcendente toestanden die wij met ontzag ervaren als contact met God. Op het eerste gezicht heb ik natuurlijke toestanden opgesomd die veel mensen eigen zijn. Echter, in de samenleving werken talrijke zowel aanmoedigende als verbiedende scenario''s die ons gedrag sturen, soms leidend tot een leven dat materialistisch wordt, vervuld van existentiële angsten, van een gevoel van zinloosheid… Door praktijken te beoefenen, zowel op de yogamat als in het leven, na te denken, je gedachten en daden bij te sturen, kun je in de loop van een maand belangrijke resultaten behalen, die zich zowel op het niveau van het lichaam (gezondheid) als op het niveau van de psychologische achtergrond (tevredenheid en geluk) zullen manifesteren.</p><p></p><p></p><p>Gedurende 30 dagen ontvang je 30 praktijken die gericht zijn op het harmoniseren van de zevende chakra. Lees deze brief aandachtig, zodat je begrijpt wat er gaat gebeuren en hoe. <br> <br><strong>1. De kern</strong><br> Dit is geen leercursus, maar een intensieve praktijk, waarvan de dagelijkse yogapraktijken de kern vormen. Deze praktijken gaf ik ''s ochtends live, waarbij ik de richting van elke praktijk afstemde op de planetaire ritmen van die dag. In dit intensief heb ik video-opnamen verzameld van de beste praktijken die juist op de eerste chakra waren gericht (soms in wisselwerking met een andere chakra), en deze aangevuld met gedragsmatige (psychologische) praktijken. Het resultaat is een uiterst krachtige impuls voor het harmoniseren van het gebied van gezondheid. </p><p></p><p></p><p>Als je mijn cursussen niet hebt gevolgd en niet begrijpt wat die ‘zevende chakra’ daar in vredesnaam mee te maken heeft, raad ik je aan dit intensief te combineren met een practicum of cursus waarin ik je geleidelijk naar het begrip breng waar we hier mee bezig zijn. Het is belangrijk om mij niet alleen maar te ‘geloven’, maar in jezelf begrip te openen via persoonlijke ervaring - zowel op de yogamat als in het leven. Dan beginnen de praktijken veel dieper te werken. Anders krijgen we gymnastiek - omdat dit het basisbegrip (de ervaring) van yoga is die iedereen heeft. </p><p></p><p></p><p>Dit intensief kun je aanvullen met de volgende leerprogramma''s:<br> - Practicum ‘Maand van kracht’: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a>  </p><p></p><p>- Cursus ‘Verwezenlijk de droom’: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a> <br>  <br><strong>2. Yogapraktijken</strong><br> Yogapraktijken die u te wachten staan, verschillen van wat u in een fitnesscentrum kunt tegenkomen. Ik ga ervan uit dat het u om het resultaat gaat, en niet om toneelspel. We werken met innerlijke toestanden (dat wil zeggen met energieën), waarbij ik meditatie, pranayama en asana''s verbind voor zover dat nodig is om het gewenste resultaat op een zo diep mogelijk niveau te bereiken. De meeste praktijken beginnen met een korte inleiding, die nodig is opdat uw bewustzijn van de alledaagsheid overschakelt naar de golf van de praktijk, u in de bijbehorende energetische stroom komt en uw innerlijke intentie wordt geactiveerd. Daarna volgt de praktijk zelf, die op verschillende dagen een verschillende duur en samenstelling van elementen heeft. Na de praktijk raad ik u aan enige tijd in meditatie te blijven, of misschien in de ontstane staat van bewustzijn door te gaan met het uitvoeren van de asana''s die uw lichaam zal vragen. De gemiddelde duur van de praktijken is 30-40 minuten. Maar sommige praktijken zijn korter, en sommige duren ongeveer een uur. Het is belangrijk dat niets u tijdens de praktijk afleidt en dat niets u opjaagt. En heel belangrijk: als u eenmaal aan de praktijk bent begonnen, onderbreek deze dan niet tot het einde!!! Elke praktijk is een levend verhaal dat u langs een bepaald pad leidt. Als u de praktijk onderbreekt, kunt u in een minder veerkrachtige toestand terechtkomen dan aan het begin ervan. Zelfs als deze woorden u nu als mystificatie en lege esoterie voorkomen, luister naar mijn aanbevelingen. <br>  <br><strong>3. Gedragspraktijken</strong><br> Elke dag zal ik u in de brief samen met de yogapraktijk een «advies van de dag» sturen. Probeer het niet te zien als nog een slimme gedachte, waarvan u er al vele malen soortgelijke hebt gehoord. Het is niet mijn doel u te verrassen door iets te zeggen wat u nog niet hebt gehoord. Zie dit «advies» als een opdracht, als een gedragspraktijk! Voer deze praktijk op die dag uit. En geloof me - het zal veel interessanter voor u worden, en dit intensief zal u veel meer nut brengen. Sommige van zulke praktijken kunnen u eenvoudiger lijken, sommige moeilijker. Sommige pragmatischer, sommige psychologischer. In ieder geval is het niet alsof ik u heb voorgesteld twintig keer te hurken. Hier werken we met uw gedragsmatige en psychologische patronen. En de sleutel tot succes is om niet met uzelf te vechten, geen extra innerlijke spanning op te roepen, maar zoals in de asana''s - te ademen en te ontspannen. Daarom klinkt de praktijk zacht - als &quot;advies van de dag&quot; - om geen alarmsignaal op te roepen. Lees het, pas het op uzelf toe, probeer dit advies gedurende de dag zachtjes te volgen of er ten minste aan te denken, het opnieuw toe te passen en terug te keren naar het gevoel dat u het volgt. Pas u aan de nieuwe toestanden aan... In sommige gevallen kan één zo''n praktijk zich over meerdere dagen of zelfs maanden uitstrekken, omdat u het belang ervan zult voelen, en het in uw leven op het niveau van een gewoonte zult gaan invoeren, dat wil zeggen door de huidige homeostase van het systeem bij te stellen. En hoewel ik geen duidelijke verbinding heb aangelegd tussen de gedragspraktijken en de yogapraktijken die ik in één brief aanbied, kunt u toch elke yogapraktijk uitvoeren in de toestand die ontstaat wanneer u zichzelf ziet als iemand die mijn advies volgt. Dat is echter helemaal niet verplicht, omdat elk van deze twee praktijken op zichzelf voldoende is.<br>  <br><strong>4. Lesschema</strong><br> Elke dag om middernacht gaat er een nieuwe praktijk voor u open (de vorige verdwijnt daarbij, zoals de vorige dag). Dankzij deze aanpak zal er bij u geen sneeuwbal van niet-uitgevoerde praktijken ontstaan. Binnen een etmaal kunt u een voor u geschikt tijdstip kiezen en oefenen. Ik raad u aan ''s ochtends te oefenen, zodat u de dag kunt doorbrengen in de toestand die u door de praktijk hebt verkregen, in plaats van naar bed te gaan. Zie dit intensief niet als een computerillusie, maar als het echte leven - waarin alles wat belangrijk is VANDAAG gebeurt, en de yogapraktijk zich van de mat uitbreidt naar de ruimte van uw manifestatie in die wereld die u als de meest werkelijke ervaart!</p><p></p><p></p><p>Trouwens, er is een kleine nuance met betrekking tot de tijd waarop u de tweede praktijk ontvangt. Als u zich vóór 18:00 hebt ingeschreven, ontvangt u de tweede praktijk bij de eerstvolgende middernacht. Als u zich na 18:00 hebt ingeschreven, ontvangt u de tweede praktijk niet bij de eerstvolgende, maar bij de daaropvolgende middernacht. Dat wil zeggen dat u extra tijd hebt voor het geval u er niet aan toe komt de praktijk uit te voeren op de dag van inschrijving voor het intensief. <br>  <br><strong>5. Doe uzelf geen geweld aan</strong><br> Wanneer u een maandabonnement bij een fitnesscentrum koopt, begrijpt u toch dat u er niet elke dag heen hoeft? Sterker nog, als u een te snel tempo aanneemt, kunt u de lessen laten vallen nog voordat u zelfs maar het einde van de maand hebt bereikt... Voor de praktijken van dit intensief geldt dezelfde regel - wees niet hebberig! Oefen in een tempo dat u bevalt - om de dag, om de twee dagen... Natuurlijk is het goed om elke dag te oefenen, maar nog beter is - uw langetermijntaken te begrijpen en dienovereenkomstig te handelen. Waarschijnlijk gaan uw taken verder dan één maand, en moet u langdurig regelmatig in actie komen. Dit intensief heb ik zo bedacht dat u het maand na maand kunt doorlopen, zo vaak als nodig, totdat het door u gestelde doel is bereikt. Deze strategie is effectiever dan één maand er flink tegenaan te gaan en daarna de praktijken te laten vallen of in een andere richting te schieten.<br>  <br><strong>6. Veiligheidstechniek</strong><br> Ik geef om uw gezondheid en herinner u eraan dat alleen u verantwoordelijk bent voor of de uitvoering van de asana''s, pranayama''s en meditaties die ik zal aanbieden adequaat is voor uw lichamelijke mogelijkheden en psychische toestand. Het is belangrijk te begrijpen dat dit online lessen zijn, en dat ik uw toestand niet kan controleren. U kunt lichamelijke en psychologische bijzonderheden hebben. Wees alstublieft aandachtig voor uw eigen toestand. Als u merkt dat een bepaalde asana die ik voorstel uit te voeren voor u voortijdig is, voer haar dan niet erg diep uit, op een compromisniveau, of vervang haar helemaal door een andere asana - een die ongeveer ook het lichaam betrekt, maar eenvoudiger voor u is.<br>  <br><strong>7. Antwoorden op vragen</strong><br> Elke week (meestal op zaterdag) geef ik in Zoom groepsgewijze onlineconsulten (webinars), waarin we met elkaar praten, de motivatie ondersteunen en opkomende moeilijkheden en vragen bespreken. Voor elk zo''n consult stuur ik u een bericht met de datum en tijd waarop het plaatsvindt, evenals een link om eraan deel te nemen. Wat voor u interessant is, zal zeker ook voor velen anderen interessant zijn. Daarom is het bespreken van vragen in groepsconsulten het meest effectief. Als het zo uitkomt dat het tijdstip van het consult u niet uitkomt, stuur uw vragen dan vóór het begin per e-mail. Ik zal ze tijdens het consult beantwoorden, en u stuur ik een link naar de opname, zodat u deze op een voor u geschikt moment kunt bekijken. Opnamen van consulten worden gedurende één week bewaard.<br> <br>Ik wens u vruchtbare praktijken!</p><p></p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('a7f0dee6-a032-5314-843e-c853d0baa792','5fd092ed-e49e-5482-9537-2b9073440a4a','Заключительное письмо',2,0,'{Интенсив Святость} Что дальше?','{"ru":"{Интенсив Святость} Что дальше?","en":"{Intensive «Holiness»} What next?","de":"{Intensivkurs «Heiligkeit»} Was kommt als Nächstes?","fr":"{Intensif « Sainteté »} Et ensuite ?","it":"{Intensivo «Santità»} E adesso?","es":"{Intensivo «Santidad»} ¿Qué sigue?","pt":"{Intensivo «Santidade»} O que vem a seguir?","nl":"{Intensief «Heiligheid»} Wat nu?"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png" alt="Интенсив «Святость»" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что вы регулярно занимались, и заметили, что стали воспринимать происходящее глубже, стали спокойней, счастливее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href="https://zamkovoi.yoga/i7">https://zamkovoi.yoga/i7</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href="https://zamkovoi.yoga/m1">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href="https://zamkovoi.yoga/m3">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href="https://zamkovoi.yoga/m4">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href="https://zamkovoi.yoga/m5">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href="https://zamkovoi.yoga/m6">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href="https://zamkovoi.yoga/m7">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href="https://zamkovoi.yoga/yoga2">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href="https://zamkovoi.yoga/tantra12">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href="https://zamkovoi.yoga/yoga3">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href="https://zamkovoi.yoga/yoga4">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href="https://zamkovoi.yoga/yoga5">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href="https://zamkovoi.yoga/yoga36">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href="https://zamkovoi.yoga/yogas">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что вы регулярно занимались, и заметили, что стали воспринимать происходящее глубже, стали спокойней, счастливее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","en":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the seventh chakra has come to an end. I hope that you have practiced regularly and have noticed that you began to perceive what is happening more deeply, became calmer, happier. Perhaps even in terms of health something has changed for the better… And now I suggest that you do not lose the wave and continue the practices! For many years you have strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all this, step by step discovering who you really are. Continuing movement in this direction will, of course, give you deeper results.</p><p></p><p> To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!</p><p></p><p>Sergei Zamkovoi</p>","de":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des siebten Chakras ausgerichtet waren, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig geübt haben und bemerkt haben, dass Sie das Geschehen tiefer wahrnehmen, ruhiger und glücklicher geworden sind. Vielleicht hat sich sogar in gesundheitlicher Hinsicht etwas zum Besseren verändert… Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und die Praktiken fortzusetzen! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten und psychologische Klischees gefestigt, und jetzt haben Sie erst begonnen, sich von all dem zu befreien, Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefere Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!</p><p></p><p>Sergei Zamkovoi</p>","fr":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Bonjour, {{name}} !<br> <br>Voilà que le mois de pratiques destinées à harmoniser le septième chakra est arrivé à son terme. J''espère que vous avez pratiqué régulièrement et que vous avez remarqué que vous avez commencé à percevoir ce qui se passe plus profondément, que vous êtes devenu plus calme, plus heureux. Peut-être même que, sur le plan de la santé, quelque chose a changé pour le mieux… Et maintenant, je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, en découvrant pas à pas qui vous êtes réellement. La continuation du mouvement dans cette direction vous donnera, sans aucun doute, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !</p><p></p><p>Sergei Zamkovoi</p>","it":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il settimo chakra. Spero che tu abbia praticato con regolarità e abbia notato di aver iniziato a percepire ciò che accade in modo più profondo, di provare maggiore calma, maggiore felicità. Forse, anche sul piano della salute qualcosa è cambiato in meglio… E ora ti propongo di non perdere l''onda e di continuare le pratiche! Per molti anni hai rafforzato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora hai solo iniziato a liberarti da tutto questo, scoprendo passo dopo passo chi sei davvero. Continuare a muoverti in questa direzione, senza dubbio, ti darà risultati più profondi.</p><p></p><p> Per iscriverti di nuovo a questo intensivo, segui il link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!</p><p></p><p>Sergei Zamkovoi</p>","es":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hola, {{name}}!<br> <br>He aquí que ha llegado a su fin el mes de prácticas dirigidas a armonizar el séptimo chakra. Espero que haya practicado con regularidad y haya notado que comenzó a percibir lo que sucede con mayor profundidad, que se ha vuelto más tranquilo, más feliz. Quizá incluso en el plano de la salud algo haya cambiado para mejor… Y ahora le propongo no perder la onda y continuar las prácticas. Durante muchos años usted fortaleció una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora apenas ha comenzado a liberarse de todo ello, abriendo paso a paso quién es usted en realidad. La continuación del movimiento en esta dirección, sin duda, le dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, vaya al enlace - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!</p><p></p><p>Sergei Zamkovoi</p>","pt":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Olá, {{name}}!<br> <br>Eis que chegou ao fim o mês de práticas voltadas para a harmonização do sétimo chakra. Espero que você tenha praticado regularmente e notado que passou a perceber o que acontece de forma mais profunda, tornou-se mais calmo, mais feliz. Talvez até, em termos de saúde, algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos, você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você realmente é. A continuação do movimento nessa direção, sem dúvida, dará a você resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!</p><p></p><p>Sergei Zamkovoi</p>","nl":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png\" alt=\"Интенсив «Святость»\" width=\"504\" height=\"119\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Hallo, {{name}}!<br> <br>Zo is de maand van praktijken gericht op het harmoniseren van de zevende chakra ten einde gekomen. Ik hoop dat je regelmatig hebt geoefend en hebt gemerkt dat je wat er gebeurt dieper bent gaan ervaren, rustiger en gelukkiger bent geworden. Misschien is er zelfs op het gebied van gezondheid iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en de praktijken voort te zetten! Jarenlang heb je een bepaald denken, bepaalde waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. De voortzetting van de beweging in deze richting zal je ongetwijfeld diepere resultaten geven.</p><p></p><p> Om je opnieuw voor dit intensief in te schrijven, ga je naar de link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!</p><p></p><p>Sergei Zamkovoi</p>"}'::jsonb,'{"ru":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Здравствуйте, {{name}}!<br> <br>Вот и подошёл к концу месяц практик, направленных на гармонизацию седьмой чакры. Я надеюсь, что вы регулярно занимались, и заметили, что стали воспринимать происходящее глубже, стали спокойней, счастливее. Возможно, даже в плане здоровья что-то изменилось в лучшую сторону… И сейчас я предлагаю вам не терять волну и продолжить практики! В течение многих лет вы укрепляли определенный образ мыслей, ценностей, привычек, психологических клише, и сейчас вы лишь начали от всего этого освобождаться, шаг за шагом открывая кто же вы есть на самом деле. Продолжение движения в этом направлении, безусловно, даст вам более глубокие результаты.</p><p></p><p> Чтобы вновь записаться на этот интенсив, перейдите по ссылке - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Если же вы чувствуете, что хотите сменить направление, то ознакомьтесь с другими моими практикумами и курсами. <br> <br>ПРАКТИКУМЫ:<br> - Месяц здоровья: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Месяц наслаждений: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Месяц силы: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Месяц любви: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Месяц свободы: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Месяц мудрости: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Месяц святости: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>КУРСЫ:<br> - Йога и здоровье: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Йога и женственность: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Тантра - мистерия взаимоотношений: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Осуществи мечту: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Планета любви: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Источник творческой силы: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 шагов йоги: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Путь души: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Всех благ!<br> Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"en":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Hello, {{name}}!<br> <br>So the month of practices aimed at harmonizing the seventh chakra has come to an end. I hope that you have practiced regularly and have noticed that you began to perceive what is happening more deeply, became calmer, happier. Perhaps even in terms of health something has changed for the better… And now I suggest that you do not lose the wave and continue the practices! For many years you have strengthened a certain way of thinking, values, habits, psychological clichés, and now you have only begun to free yourself from all this, step by step discovering who you really are. Continuing movement in this direction will, of course, give you deeper results.</p><p></p><p> To sign up for this intensive again, follow the link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>If you feel that you want to change direction, then take a look at my other workshops and courses. <br> <br>WORKSHOPS:<br> - Month of Health: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Month of Pleasures: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Month of Strength: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Month of Love: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Month of Freedom: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Month of Wisdom: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Month of Holiness: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURSES:<br> - Yoga and Health: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga and Femininity: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - the mystery of relationships: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Fulfill the Dream: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet of Love: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source of Creative Power: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Steps of Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Path of the Soul: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>All the best!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"de":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Guten Tag, {{name}}!<br> <br>Nun ist der Monat der Praktiken, die auf die Harmonisierung des siebten Chakras ausgerichtet waren, zu Ende gegangen. Ich hoffe, dass Sie regelmäßig geübt haben und bemerkt haben, dass Sie das Geschehen tiefer wahrnehmen, ruhiger und glücklicher geworden sind. Vielleicht hat sich sogar in gesundheitlicher Hinsicht etwas zum Besseren verändert… Und jetzt schlage ich Ihnen vor, die Welle nicht zu verlieren und die Praktiken fortzusetzen! Viele Jahre lang haben Sie eine bestimmte Denkweise, Werte, Gewohnheiten und psychologische Klischees gefestigt, und jetzt haben Sie erst begonnen, sich von all dem zu befreien, Schritt für Schritt zu entdecken, wer Sie wirklich sind. Die Fortsetzung der Bewegung in diese Richtung wird Ihnen zweifellos tiefere Ergebnisse bringen.</p><p></p><p> Um sich erneut für diesen Intensivkurs anzumelden, folgen Sie dem Link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Wenn Sie jedoch das Gefühl haben, die Richtung wechseln zu wollen, dann machen Sie sich mit meinen anderen Praktika und Kursen vertraut. <br> <br>PRAKTIKA:<br> - Monat der Gesundheit: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Monat der Genüsse: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Monat der Kraft: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Monat der Liebe: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Monat der Freiheit: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Monat der Weisheit: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Monat der Heiligkeit: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>KURSE:<br> - Yoga und Gesundheit: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga und Weiblichkeit: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - Mysterium der Beziehungen: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwirkliche den Traum: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planet der Liebe: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Quelle schöpferischer Kraft: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 Schritte des Yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Weg der Seele: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alles Gute!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"fr":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Bonjour, {{name}} !<br> <br>Voilà que le mois de pratiques destinées à harmoniser le septième chakra est arrivé à son terme. J''espère que vous avez pratiqué régulièrement et que vous avez remarqué que vous avez commencé à percevoir ce qui se passe plus profondément, que vous êtes devenu plus calme, plus heureux. Peut-être même que, sur le plan de la santé, quelque chose a changé pour le mieux… Et maintenant, je vous propose de ne pas perdre la vague et de poursuivre les pratiques ! Pendant de nombreuses années, vous avez renforcé une certaine manière de penser, des valeurs, des habitudes, des clichés psychologiques, et maintenant vous avez seulement commencé à vous en libérer, en découvrant pas à pas qui vous êtes réellement. La continuation du mouvement dans cette direction vous donnera, sans aucun doute, des résultats plus profonds.</p><p></p><p> Pour vous réinscrire à cet intensif, suivez le lien - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Si toutefois vous sentez que vous voulez changer de direction, alors prenez connaissance de mes autres ateliers et cours. <br> <br>ATELIERS :<br> - Mois de la santé : <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mois des plaisirs : <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mois de la force : <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mois de l’amour : <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mois de la liberté : <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mois de la sagesse : <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mois de la sainteté : <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>COURS :<br> - Yoga et santé: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga et féminité: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mystère des relations: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Réalise ton rêve: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planète de l''amour: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Source de force créatrice: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pas de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Chemin de l''âme: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Toutes les bénédictions !</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"it":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Salve, {{name}}!<br> <br>Ecco che è giunto al termine il mese di pratiche volte ad armonizzare il settimo chakra. Spero che tu abbia praticato con regolarità e abbia notato di aver iniziato a percepire ciò che accade in modo più profondo, di provare maggiore calma, maggiore felicità. Forse, anche sul piano della salute qualcosa è cambiato in meglio… E ora ti propongo di non perdere l''onda e di continuare le pratiche! Per molti anni hai rafforzato un certo modo di pensare, valori, abitudini, cliché psicologici, e ora hai solo iniziato a liberarti da tutto questo, scoprendo passo dopo passo chi sei davvero. Continuare a muoverti in questa direzione, senza dubbio, ti darà risultati più profondi.</p><p></p><p> Per iscriverti di nuovo a questo intensivo, segui il link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Se invece sentite di voler cambiare direzione, allora date un''occhiata agli altri miei praticum e corsi. <br> <br>PRATICUM:<br> - Mese della salute: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mese dei piaceri: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mese della forza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mese dell''amore: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mese della libertà: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mese della saggezza: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mese della santità: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CORSI:<br> - Yoga e salute: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e femminilità: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistero delle relazioni: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realizza il sogno: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Pianeta dell''amore: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte di forza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passi di yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Il cammino dell''anima: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Ogni bene!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"es":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Hola, {{name}}!<br> <br>He aquí que ha llegado a su fin el mes de prácticas dirigidas a armonizar el séptimo chakra. Espero que haya practicado con regularidad y haya notado que comenzó a percibir lo que sucede con mayor profundidad, que se ha vuelto más tranquilo, más feliz. Quizá incluso en el plano de la salud algo haya cambiado para mejor… Y ahora le propongo no perder la onda y continuar las prácticas. Durante muchos años usted fortaleció una determinada forma de pensar, valores, hábitos, clichés psicológicos, y ahora apenas ha comenzado a liberarse de todo ello, abriendo paso a paso quién es usted en realidad. La continuación del movimiento en esta dirección, sin duda, le dará resultados más profundos.</p><p></p><p> Para inscribirse de nuevo en este intensivo, vaya al enlace - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Si siente que quiere cambiar de dirección, eche un vistazo a mis otros talleres y cursos. <br> <br>TALLERES:<br> - Mes de la salud: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mes de los placeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mes de la fuerza: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mes del amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mes de la libertad: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mes de la sabiduría: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mes de la santidad: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga y salud: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga y feminidad: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - misterio de las relaciones: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Haz realidad tu sueño: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta del amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fuente de la fuerza creativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 pasos del yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Camino del alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>¡Todo lo mejor!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"pt":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Olá, {{name}}!<br> <br>Eis que chegou ao fim o mês de práticas voltadas para a harmonização do sétimo chakra. Espero que você tenha praticado regularmente e notado que passou a perceber o que acontece de forma mais profunda, tornou-se mais calmo, mais feliz. Talvez até, em termos de saúde, algo tenha mudado para melhor… E agora eu proponho que você não perca a onda e continue as práticas! Durante muitos anos, você fortaleceu um determinado modo de pensar, valores, hábitos, clichês psicológicos, e agora você apenas começou a se libertar de tudo isso, passo a passo descobrindo quem você realmente é. A continuação do movimento nessa direção, sem dúvida, dará a você resultados mais profundos.</p><p></p><p> Para se inscrever novamente neste intensivo, acesse o link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Se, porém, você sente que quer mudar de direção, conheça meus outros praticuns e cursos. <br> <br>PRATICUNS:<br> - Mês da saúde: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Mês dos prazeres: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Mês da força: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Mês do amor: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Mês da liberdade: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Mês da sabedoria: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Mês da santidade: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSOS:<br> - Yoga e saúde: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga e feminilidade: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mistério das relações: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Realize o sonho: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeta do amor: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Fonte da força criativa: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 passos de yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Caminho da alma: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Tudo de bom!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}],"nl":[{"id":"intensive-holiness-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/intensive-holiness/i7_email-dca50f88e501.png","alt":"Интенсив «Святость»","width":"100%","align":"center","naturalWidth":600,"naturalHeight":142,"marginTop":0,"marginBottom":24},{"id":"intensive-holiness-2-text","type":"text","html":"<p>Hallo, {{name}}!<br> <br>Zo is de maand van praktijken gericht op het harmoniseren van de zevende chakra ten einde gekomen. Ik hoop dat je regelmatig hebt geoefend en hebt gemerkt dat je wat er gebeurt dieper bent gaan ervaren, rustiger en gelukkiger bent geworden. Misschien is er zelfs op het gebied van gezondheid iets ten goede veranderd… En nu nodig ik je uit om de golf niet te verliezen en de praktijken voort te zetten! Jarenlang heb je een bepaald denken, bepaalde waarden, gewoonten en psychologische clichés versterkt, en nu ben je pas begonnen je daarvan te bevrijden, stap voor stap ontdekkend wie je werkelijk bent. De voortzetting van de beweging in deze richting zal je ongetwijfeld diepere resultaten geven.</p><p></p><p> Om je opnieuw voor dit intensief in te schrijven, ga je naar de link - <a href=\"https://zamkovoi.yoga/i7\">https://zamkovoi.yoga/i7</a> <br> <br>Als u echter voelt dat u van richting wilt veranderen, maak dan kennis met mijn andere praktijken en cursussen. <br> <br>PRAKTIJKEN:<br> - Maand van gezondheid: <a href=\"https://zamkovoi.yoga/m1\">https://zamkovoi.yoga/m1</a><br> - Maand van genot: <a href=\"https://zamkovoi.yoga/m2\">https://zamkovoi.yoga/m2</a><br> - Maand van kracht: <a href=\"https://zamkovoi.yoga/m3\">https://zamkovoi.yoga/m3</a><br> - Maand van liefde: <a href=\"https://zamkovoi.yoga/m4\">https://zamkovoi.yoga/m4</a><br> - Maand van vrijheid: <a href=\"https://zamkovoi.yoga/m5\">https://zamkovoi.yoga/m5</a><br> - Maand van wijsheid: <a href=\"https://zamkovoi.yoga/m6\">https://zamkovoi.yoga/m6</a><br> - Maand van heiligheid: <a href=\"https://zamkovoi.yoga/m7\">https://zamkovoi.yoga/m7</a><br> <br>CURSUSSEN:<br> - Yoga en gezondheid: <a href=\"https://zamkovoi.yoga/yoga1\">https://zamkovoi.yoga/yoga1</a><br> - Yoga en vrouwelijkheid: <a href=\"https://zamkovoi.yoga/yoga2\">https://zamkovoi.yoga/yoga2</a><br> - Tantra - mysterie van relaties: <a href=\"https://zamkovoi.yoga/tantra12\">https://zamkovoi.yoga/tantra12</a><br> - Verwezenlijk je droom: <a href=\"https://zamkovoi.yoga/yoga3\">https://zamkovoi.yoga/yoga3</a><br> - Planeet van de liefde: <a href=\"https://zamkovoi.yoga/yoga4\">https://zamkovoi.yoga/yoga4</a><br> - Bron van creatieve kracht: <a href=\"https://zamkovoi.yoga/yoga5\">https://zamkovoi.yoga/yoga5</a><br> - 36 stappen van yoga: <a href=\"https://zamkovoi.yoga/yoga36\">https://zamkovoi.yoga/yoga36</a><br> - Pad van de ziel: <a href=\"https://zamkovoi.yoga/yogas\">https://zamkovoi.yoga/yogas</a><br> <br>Alle goeds!</p><p></p><p>Sergei Zamkovoi</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.courses(slug,title,title_i18n,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,intro_email_step_id,completion_email_step_id,source_hash) values('intensive-holiness','Интенсив «Святость»','{"ru":"Интенсив «Святость»","en":"Intensive «Holiness»","de":"Intensivkurs «Heiligkeit»","fr":"Intensif « Sainteté »","it":"Intensivo «Santità»","es":"Intensivo «Santidad»","pt":"Intensivo «Santidade»","nl":"Intensief «Heiligheid»"}'::jsonb,'intensive','',1,1,1,'5fd092ed-e49e-5482-9537-2b9073440a4a','b0348150-dfc7-51ea-9449-88f913bd117f','a7f0dee6-a032-5314-843e-c853d0baa792','8ba8a23344a849542f8b3f04581ab68812c0256fef0777d195bd3633a312f959') on conflict(slug) do update set source_hash=excluded.source_hash;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-01','intensive-holiness',1,0,'День: 1','[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Совет дня:\n\nОщущайте своё тело как разумную Вселенную. Ваше тело - не инструмент для ваших хотелок, и не то, что нужно одевать, кормить, выгуливать, и оно всё-равно периодически болеет, мешая вам ходить на работу... Учитесь воспринимать своё тело - как божественный дар, как чудесным образом доверенный вам фрагмент космоса, мудрая и живая экосистема. Перестаньте чего-то от него добиваться или эксплуатировать его. Станьте его любящим хранителем: слушайте его потребности, питайте его чистой пищей, благодарите за возможность чувствовать, двигаться и дышать в этом мире..."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Tip of the day:\n\nFeel your body as an intelligent Universe. Your body is not a tool for your wants, and not something that needs to be dressed, fed, walked, and it still periodically gets sick, preventing you from going to work... Learn to perceive your body as a divine gift, as a miraculously entrusted fragment of the cosmos to you, a wise and living ecosystem. Stop trying to get something from it or exploit it. Become its loving keeper: listen to its needs, feed it pure food, thank it for the opportunity to feel, move and breathe in this world..."}],"de":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Tipp des Tages:\n\nFühlen Sie Ihren Körper als ein vernünftiges Universum. Ihr Körper ist kein Werkzeug für Ihre Gelüste und nicht etwas, das man anziehen, füttern, spazieren führen muss, und er wird trotzdem regelmäßig krank und hindert Sie daran, zur Arbeit zu gehen... Lernen Sie, Ihren Körper als göttliches Geschenk wahrzunehmen, als ein auf wundersame Weise Ihnen anvertrautes Fragment des Kosmos, als ein weises und lebendiges Ökosystem. Hören Sie auf, etwas von ihm zu erlangen oder ihn auszubeuten. Werden Sie sein liebevoller Hüter: Hören Sie auf seine Bedürfnisse, nähren Sie ihn mit reiner Nahrung, danken Sie ihm für die Möglichkeit, in dieser Welt zu fühlen, sich zu bewegen und zu atmen..."}],"fr":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Conseil du jour :\n\nRessentez votre corps comme un Univers intelligent. Votre corps n''est pas un instrument pour vos envies, ni quelque chose qu''il faut habiller, nourrir, promener, et qui, malgré tout, tombe périodiquement malade, vous empêchant d''aller au travail... Apprenez à percevoir votre corps - comme un don divin, comme un fragment de cosmos miraculeusement confié à vous, un écosystème sage et vivant. Cessez d''exiger quelque chose de lui ou de l''exploiter. Devenez son gardien aimant : écoutez ses besoins, nourrissez-le d''une nourriture pure, remerciez-le pour la possibilité de sentir, de bouger et de respirer dans ce monde..."}],"it":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSenti il tuo corpo come un Universo intelligente. Il tuo corpo non è uno strumento per i tuoi capricci, né qualcosa da vestire, nutrire, portare a spasso, e che comunque si ammala periodicamente, impedendoti di andare al lavoro... Impara a percepire il tuo corpo come un dono divino, come un frammento di cosmo miracolosamente affidatoti, un ecosistema saggio e vivo. Smetti di pretendere qualcosa da lui o di sfruttarlo. Diventa il suo custode amorevole: ascolta i suoi bisogni, nutrilo con cibo puro, ringrazialo per la possibilità di sentire, muoverti e respirare in questo mondo..."}],"es":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Consejo del día:\n\nSienta su cuerpo como un Universo inteligente. Su cuerpo no es un instrumento para sus caprichos, ni algo que hay que vestir, alimentar, sacar a pasear, y aun así periódicamente enferma, impidiéndole ir al trabajo... Aprenda a percibir su cuerpo como un regalo divino, como un fragmento del cosmos confiado a usted de manera milagrosa, un ecosistema sabio y vivo. Deje de exigirle algo o de explotarlo. Conviértase en su amoroso guardián: escuche sus necesidades, aliméntelo con comida pura, agradézcale por la posibilidad de sentir, moverse y respirar en este mundo..."}],"pt":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Dica do dia:\n\nSinta seu corpo como um Universo inteligente. Seu corpo não é uma ferramenta para os seus desejos, nem algo que precisa ser vestido, alimentado, passeado, e que mesmo assim adoece periodicamente, atrapalhando você de ir ao trabalho... Aprenda a perceber seu corpo como um dom divino, como um fragmento do cosmos milagrosamente confiado a você, um ecossistema sábio e vivo. Pare de exigir algo dele ou de explorá-lo. Torne-se seu guardião amoroso: escute suas necessidades, alimente-o com comida pura, agradeça pela possibilidade de sentir, mover-se e respirar neste mundo..."}],"nl":[{"type":"video","vimeoId":"1141367686"},{"type":"text","markdown":"### Tip van de dag:\n\nErvaar je lichaam als een verstandig universum. Je lichaam is geen instrument voor je grillen, en niet iets dat je moet aankleden, voeden, uitlaten, en dat toch periodiek ziek wordt en je belemmert om naar je werk te gaan... Leer je lichaam te beschouwen als een goddelijk geschenk, als een op wonderbaarlijke wijze aan jou toevertrouwd fragment van de kosmos, een wijs en levend ecosysteem. Stop met iets van je lichaam te willen afdwingen of het uit te buiten. Word een liefdevolle hoeder ervan: luister naar zijn behoeften, voed het met zuiver voedsel, dank het voor de mogelijkheid om in deze wereld te voelen, te bewegen en te ademen..."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-02','intensive-holiness',2,1,'День: 2','[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Совет дня:\n\nНачинайте день с приветствия миру. Прежде чем взять в руки телефон, посмотрите в окно. Почувствуйте утренний воздух, поблагодарите новый день за возможность жить, чувствовать и творить. Этот простой ритуал настраивает ваше восприятие на волну чуда. И вы можете продолжить, выполнив комплекс Сурья Намаскар. Но самое главное - выпоняйте его в этом же состоянии утренней благости. Затем вместе с собой несите эту волну дальше..."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Tip of the day:\n\nBegin the day by greeting the world. Before you pick up your phone, look out the window. Feel the morning air, thank the new day for the opportunity to live, feel and create. This simple ritual tunes your perception to the wave of miracle. And you can continue by performing the Surya Namaskar complex. But most importantly, perform it in this same state of morning grace. Then carry this wave further along with yourself..."}],"de":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Tipp des Tages:\n\nBeginnen Sie den Tag mit einem Gruß an die Welt. Bevor Sie zum Telefon greifen, schauen Sie aus dem Fenster. Fühlen Sie die Morgenluft, danken Sie dem neuen Tag für die Möglichkeit zu leben, zu fühlen und zu schaffen. Dieses einfache Ritual stimmt Ihre Wahrnehmung auf die Welle des Wunders ein. Und Sie können fortfahren, indem Sie den Komplex Surya Namaskar ausführen. Das Wichtigste ist jedoch - führen Sie ihn in genau diesem Zustand der morgendlichen Segensfülle aus. Tragen Sie diese Welle dann mit sich weiter..."}],"fr":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Conseil du jour :\n\nCommencez la journée en saluant le monde. Avant de prendre votre téléphone, regardez par la fenêtre. Sentez l''air du matin, remerciez le nouveau jour pour la possibilité de vivre, de sentir et de créer. Ce simple rituel accorde votre perception sur la vague du miracle. Et vous pouvez continuer en exécutant le complexe Surya Namaskar. Mais le plus important - exécutez-le dans ce même état de bénédiction matinale. Ensuite, emportez cette vague plus loin avec vous..."}],"it":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Consiglio del giorno:\n\nInizia la giornata con un saluto al mondo. Prima di prendere in mano il telefono, guarda fuori dalla finestra. Senti l''aria del mattino, ringrazia il nuovo giorno per la possibilità di vivere, sentire e creare. Questo semplice rituale sintonizza la tua percezione sull''onda del miracolo. E puoi continuare eseguendo la sequenza di Surya Namaskar. Ma la cosa più importante - eseguila in questo stesso stato di grazia mattutina. Poi porta con te quest''onda più avanti..."}],"es":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Consejo del día:\n\nComience el día saludando al mundo. Antes de tomar el teléfono en las manos, mire por la ventana. Sienta el aire de la mañana, agradezca al nuevo día por la posibilidad de vivir, sentir y crear. Este simple ritual sintoniza su percepción con la onda del milagro. Y puede continuar realizando el complejo Surya Namaskar. Pero lo más importante: ejecútelo en este mismo estado de bienaventuranza matutina. Luego, junto con usted, lleve esta onda más adelante..."}],"pt":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Dica do dia:\n\nComece o dia saudando o mundo. Antes de pegar o telefone, olhe pela janela. Sinta o ar da manhã, agradeça ao novo dia pela possibilidade de viver, sentir e criar. Esse simples ritual sintoniza sua percepção na onda do milagre. E você pode continuar, realizando a sequência Surya Namaskar. Mas o mais importante é executá-la nesse mesmo estado de bênção matinal. Depois, leve essa onda adiante junto com você..."}],"nl":[{"type":"video","vimeoId":"1151148075"},{"type":"text","markdown":"### Tip van de dag:\n\nBegin de dag met een groet aan de wereld. Voordat je je telefoon in handen neemt, kijk je uit het raam. Voel de ochtendlucht, dank de nieuwe dag voor de mogelijkheid om te leven, te voelen en te creëren. Dit eenvoudige ritueel stemt je waarneming af op de golf van het wonder. En je kunt doorgaan door de serie Surya Namaskar uit te voeren. Maar het allerbelangrijkste - voer die uit in dezelfde staat van ochtendzegen. Draag die golf vervolgens met je mee verder..."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-03','intensive-holiness',3,1,'День: 3','[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Совет дня:\n\nПозвольте себе присутствие трёх советников: Мудреца, Жрицы и Воина. Мудрец (ваш разум) проанализирует факты. Жрица (интуиция) почувствует поток. А Воин (воля) примет решение и возьмет за него ответственность. Когда все трое приходят к согласию, каждый ваш выбор будет правильным."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tip of the day:\n\nAllow yourself the presence of three advisors: the Sage, the Priestess and the Warrior. The Sage (your mind) will analyze the facts. The Priestess (intuition) will feel the flow. And the Warrior (will) will make a decision and take responsibility for it. When all three come to agreement, your every choice will be right."}],"de":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tipp des Tages:\n\nErlauben Sie sich die Anwesenheit dreier Ratgeber: des Weisen, der Priesterin und des Kriegers. Der Weise (Ihr Verstand) wird die Fakten analysieren. Die Priesterin (die Intuition) wird den Fluss fühlen. Und der Krieger (der Wille) wird eine Entscheidung treffen und die Verantwortung dafür übernehmen. Wenn alle drei zur Übereinstimmung kommen, wird jede Ihrer Entscheidungen richtig sein."}],"fr":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Conseil du jour :\n\nPermettez-vous la présence de trois conseillers : le Sage, la Prêtresse et le Guerrier. Le Sage (votre raison) analysera les faits. La Prêtresse (l''intuition) sentira le flux. Et le Guerrier (la volonté) prendra la décision et en assumera la responsabilité. Lorsque tous les trois parviennent à un accord, chacun de vos choix sera juste."}],"it":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPermetti a te stesso la presenza di tre consiglieri: il Saggio, la Sacerdotessa e il Guerriero. Il Saggio (la tua mente) analizzerà i fatti. La Sacerdotessa (l''intuito) sentirà il flusso. E il Guerriero (la volontà) prenderà una decisione e se ne assumerà la responsabilità. Quando tutti e tre giungono all''accordo, ogni tua scelta sarà giusta."}],"es":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Consejo del día:\n\nPermítase la presencia de tres consejeros: el Sabio, la Sacerdotisa y el Guerrero. El Sabio (su razón) analizará los hechos. La Sacerdotisa (la intuición) sentirá el flujo. Y el Guerrero (la voluntad) tomará la decisión y asumirá la responsabilidad por ella. Cuando los tres llegan a un acuerdo, cada elección suya será correcta."}],"pt":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Dica do dia:\n\nPermita-se a presença de três conselheiros: o Sábio, a Sacerdotisa e o Guerreiro. O Sábio (sua razão) analisará os fatos. A Sacerdotisa (intuição) sentirá o fluxo. E o Guerreiro (vontade) tomará a decisão e assumirá responsabilidade por ela. Quando todos os três chegam a um acordo, cada escolha sua será correta."}],"nl":[{"type":"video","vimeoId":"1150277253"},{"type":"text","markdown":"### Tip van de dag:\n\nSta jezelf de aanwezigheid van drie raadgevers toe: de Wijze, de Priesteres en de Krijger. De Wijze (je verstand) analyseert de feiten. De Priesteres (je intuïtie) voelt de stroom. En de Krijger (je wil) neemt een beslissing en draagt daar de verantwoordelijkheid voor. Wanneer alle drie tot overeenstemming komen, zal elke keuze die je maakt juist zijn."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-04','intensive-holiness',4,1,'День: 4','[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Совет дня:\n\nРазличайте сдачу потоку и пассивное бездействие. Сдаться - не значит бросить весла и ждать, пока вашу лодку разобьёт о скалы. Сдаться - значит перестать грести против течения, развернуть лодку и начать умело использовать силу потока, чтобы двигаться к своей цели быстрее и с меньшими усилиями. А может быть пришло время осознать, что у вас есть парус, и начать использовать его? Или у вас круизный лайнер? А может быть вы - чайка... по имени джонатан ливингстон? :) Двигаясь в потоке вы ощущаете своё постоянное развитие, а не только лиш перемещение в потоке."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tip of the day:\n\nDistinguish surrender to the flow from passive inaction. To surrender does not mean to throw down the oars and wait for your boat to be smashed against the rocks. To surrender means to stop rowing against the current, turn the boat around and begin skillfully using the power of the flow, in order to move toward your goal faster and with less effort. Or perhaps the time has come to realize that you have a sail, and to begin using it? Or do you have a cruise liner? Or perhaps you are a seagull... by the name of Jonathan Livingston? :) Moving in the flow, you feel your constant development, and not only mere movement in the flow."}],"de":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tipp des Tages:\n\nUnterscheiden Sie zwischen der Hingabe an den Fluss und passivem Nichtstun. Sich hinzugeben bedeutet nicht, die Ruder wegzuwerfen und zu warten, bis Ihr Boot an den Klippen zerschellt. Sich hinzugeben bedeutet, aufzuhören, gegen die Strömung zu rudern, das Boot zu wenden und die Kraft des Flusses geschickt zu nutzen, um sich schneller und mit weniger Anstrengung auf Ihr Ziel zuzubewegen. Und vielleicht ist es Zeit zu erkennen, dass Sie ein Segel haben, und es zu benutzen? Oder haben Sie ein Kreuzfahrtschiff? Vielleicht sind Sie aber eine Möwe... mit Namen Jonathan Livingston? :) Wenn Sie sich im Fluss bewegen, spüren Sie Ihre ständige Entwicklung und nicht nur eine bloße Fortbewegung im Fluss."}],"fr":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Conseil du jour :\n\nDistinguez l''abandon au flux et l''inaction passive. S''abandonner ne signifie pas jeter les rames et attendre que votre bateau se brise contre les rochers. S''abandonner signifie cesser de ramer contre le courant, retourner le bateau et commencer à utiliser habilement la force du flux pour avancer vers votre but plus vite et avec moins d''efforts. Et peut-être est-il temps de prendre conscience que vous avez une voile, et de commencer à l''utiliser ? Ou avez-vous un paquebot de croisière ? Et peut-être êtes-vous une mouette... nommée Jonathan Livingston ? :) En vous déplaçant dans le flux, vous ressentez votre développement constant, et non seulement un simple déplacement dans le flux."}],"it":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDistingui l''abbandono al flusso dalla passiva inazione. Abbandonarsi non significa gettare i remi e aspettare che la tua barca si schianti contro gli scogli. Abbandonarsi significa smettere di remare controcorrente, girare la barca e iniziare a usare abilmente la forza del flusso per muoverti verso il tuo obiettivo più velocemente e con meno sforzo. O forse è giunto il momento di rendersi conto che hai una vela e di iniziare a usarla? O hai una nave da crociera? O forse sei un gabbiano... di nome Jonathan Livingston? :) Muovendoti nel flusso percepisci il tuo sviluppo costante, e non solo lo spostamento nel flusso."}],"es":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Consejo del día:\n\nDistinga entre la entrega al flujo y la pasividad inactiva. Entregarse no significa soltar los remos y esperar a que su bote se estrelle contra las rocas. Entregarse significa dejar de remar contra la corriente, girar el bote y comenzar a usar con habilidad la fuerza del flujo para avanzar hacia su meta más rápido y con menos esfuerzo. ¿O tal vez ha llegado el momento de darse cuenta de que tiene una vela y comenzar a usarla? ¿O acaso tiene un crucero? ¿O quizá usted es una gaviota... llamada Jonathan Livingston? :) Moviéndose en el flujo, usted siente su desarrollo constante, y no solo un mero desplazamiento en el flujo."}],"pt":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Dica do dia:\n\nDistinga a entrega ao fluxo da inação passiva. Entregar-se não significa largar os remos e esperar que seu barco se despedace nas rochas. Entregar-se significa parar de remar contra a correnteza, virar o barco e começar a usar habilmente a força do fluxo para se mover em direção ao seu objetivo com mais rapidez e menos esforço. Ou talvez tenha chegado o momento de perceber que você tem uma vela e começar a usá-la? Ou você tem um navio de cruzeiro? Ou talvez você seja uma gaivota... chamada Jonathan Livingston? :) Movendo-se no fluxo, você sente seu desenvolvimento constante, e não apenas uma mera movimentação no fluxo."}],"nl":[{"type":"video","vimeoId":"1152831012"},{"type":"text","markdown":"### Tip van de dag:\n\nOnderscheid overgave aan de stroom van passieve inactiviteit. Je overgeven betekent niet de riemen loslaten en wachten tot je boot tegen de rotsen te pletter slaat. Je overgeven betekent ophouden tegen de stroom in te roeien, de boot omdraaien en de kracht van de stroom vakkundig gaan gebruiken om sneller en met minder inspanning je doel te bereiken. Of is het misschien tijd om te beseffen dat je een zeil hebt, en het te gaan gebruiken? Of heb je een cruiseschip? Of ben je misschien een meeuw... met de naam Jonathan Livingston? :) Terwijl je in de stroom beweegt, ervaar je je voortdurende ontwikkeling, en niet alleen maar een verplaatsing in de stroom."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-05','intensive-holiness',5,1,'День: 5','[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Совет дня:\n\nПроявляйте божественное творчество. Начиная новый проект или любое важное дело, вместо того чтобы придумывать и планировать, что вы хотите сделать и когда, войдите в состояние тихой, молитвенной пустоты. Отложите в сторону свое эго, свои амбиции и желание произвести впечатление. Представьте себя полым, чистым сосудом и мысленно пригласите Божественный Поток войти и творить через вас. А красота получившегося творения покажет насколько вы смогли отодвинуть в себе \"человеческое\", освободив пространство для божественного."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Tip of the day:\n\nManifest divine creativity. When starting a new project or any important matter, instead of inventing and planning what you want to do and when, enter a state of quiet, prayerful emptiness. Set aside your ego, your ambitions and the desire to make an impression. Imagine yourself as a hollow, clean vessel and mentally invite the Divine Flow to enter and create through you. And the beauty of the resulting creation will show how much you were able to push aside the “human” in yourself, freeing space for the divine."}],"de":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Tipp des Tages:\n\nBringen Sie göttliche Schöpferkraft zum Ausdruck. Wenn Sie ein neues Projekt oder eine beliebige wichtige Sache beginnen, treten Sie, anstatt sich auszudenken und zu planen, was Sie tun wollen und wann, in einen Zustand stiller, betender Leere ein. Legen Sie Ihr Ego, Ihre Ambitionen und den Wunsch, Eindruck zu machen, beiseite. Stellen Sie sich selbst als ein hohles, reines Gefäß vor und laden Sie den Göttlichen Fluss gedanklich ein, einzutreten und durch Sie zu schaffen. Und die Schönheit des entstandenen Werkes wird zeigen, wie weit Sie es vermochten, in sich das „Menschliche“ zurückzuschieben und dem Göttlichen Raum zu geben."}],"fr":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Conseil du jour :\n\nManifestez la créativité divine. En commençant un nouveau projet ou toute affaire importante, au lieu d''inventer et de planifier ce que vous voulez faire et quand, entrez dans un état de vide silencieux et priant. Mettez de côté votre ego, vos ambitions et votre désir de produire une impression. Imaginez-vous comme un vase creux et pur et invitez mentalement le Flux Divin à entrer et à créer à travers vous. Et la beauté de la création obtenue montrera à quel point vous avez pu écarter en vous l''« humain », libérant l''espace pour le divin."}],"it":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Consiglio del giorno:\n\nManifesta la creatività divina. Iniziando un nuovo progetto o qualsiasi impresa importante, invece di inventare e pianificare cosa vuoi fare e quando, entra nello stato di quieta vacuità orante. Metti da parte il tuo ego, le tue ambizioni e il desiderio di fare impressione. Immaginati come un vaso cavo e puro e invita mentalmente il Flusso Divino a entrare e a creare attraverso di te. E la bellezza dell''opera risultante mostrerà quanto sei riuscito ad allontanare in te l''«umano», liberando spazio per il divino."}],"es":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Consejo del día:\n\nManifieste la creatividad divina. Al comenzar un nuevo proyecto o cualquier asunto importante, en lugar de idear y planificar qué quiere hacer y cuándo, entre en un estado de vacío silencioso y orante. Deje a un lado su ego, sus ambiciones y el deseo de causar impresión. Imagínese como un vaso vacío y limpio e invite mentalmente al Flujo Divino a entrar y crear a través de usted. Y la belleza de la creación resultante mostrará hasta qué punto ha podido apartar en sí mismo lo \"humano\", liberando espacio para lo divino."}],"pt":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Dica do dia:\n\nManifeste a criatividade divina. Ao iniciar um novo projeto ou qualquer assunto importante, em vez de inventar e planejar o que você quer fazer e quando, entre no estado de vazio silencioso e orante. Deixe de lado seu ego, suas ambições e o desejo de causar impressão. Imagine-se um vaso vazio e puro e, mentalmente, convide o Fluxo Divino a entrar e criar através de você. E a beleza da criação resultante mostrará o quanto você conseguiu afastar em si o \"humano\", liberando espaço para o divino."}],"nl":[{"type":"video","vimeoId":"1153102220"},{"type":"text","markdown":"### Tip van de dag:\n\nLaat goddelijke creativiteit zich manifesteren. Wanneer je aan een nieuw project of een belangrijke zaak begint, ga dan, in plaats van te bedenken en te plannen wat je wilt doen en wanneer, in een staat van stille, biddende leegte. Zet je ego, je ambities en je verlangen om indruk te maken aan de kant. Stel jezelf voor als een hol, zuiver vat en nodig in gedachten de Goddelijke Stroom uit om binnen te komen en door jou heen te scheppen. En de schoonheid van het ontstane werk zal laten zien in hoeverre je het \"menselijke\" in jezelf hebt weten terug te schuiven en ruimte hebt vrijgemaakt voor het goddelijke."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-06','intensive-holiness',6,1,'День: 6','[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Совет дня:\n\nСовершайте подношения Богу через людей. Когда вы делаете доброе дело, особенно анонимно, вы совершаете не просто хороший поступок, а лишённый эгоистичных желаний акт служения. В такие минуты протяните своим вниманием связь между вашим действием и Богом, и ваше действие превратится в подношение на алтарь мироздания. И ответ на ваше действие придёт не человеческой благодарностью или денежными знаками (как это обычно происходит), а чистой божественной благодатью."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Tip of the day:\n\nMake offerings to God through people. When you do a good deed, especially anonymously, you perform not merely a good act, but an act of service devoid of selfish desires. In such moments, extend with your attention the connection between your action and God, and your action will turn into an offering on the altar of the universe. And the response to your action will come not as human gratitude or monetary tokens (as usually happens), but as pure divine grace."}],"de":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Tipp des Tages:\n\nBringen Sie Gott durch Menschen Opfergaben dar. Wenn Sie eine gute Tat vollbringen, besonders anonym, vollbringen Sie nicht einfach eine gute Handlung, sondern einen von egoistischen Wünschen befreiten Akt des Dienens. In solchen Augenblicken spannen Sie mit Ihrer Aufmerksamkeit die Verbindung zwischen Ihrer Handlung und Gott, und Ihre Handlung verwandelt sich in eine Opfergabe auf dem Altar des Weltalls. Und die Antwort auf Ihre Handlung wird nicht in menschlicher Dankbarkeit oder Geldscheinen kommen (wie es gewöhnlich geschieht), sondern in reiner göttlicher Gnade."}],"fr":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Conseil du jour :\n\nFaites des offrandes à Dieu à travers les gens. Lorsque vous faites une bonne action, surtout anonymement, vous accomplissez non pas simplement un bon acte, mais un acte de service dépourvu de désirs égoïstes. En ces instants, étendez par votre attention le lien entre votre action et Dieu, et votre action se transformera en offrande sur l''autel de l''univers. Et la réponse à votre action viendra non pas de la gratitude humaine ou de signes monétaires (comme cela se produit habituellement), mais d''une pure grâce divine."}],"it":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Consiglio del giorno:\n\nFai offerte a Dio attraverso le persone. Quando fai una buona azione, soprattutto in modo anonimo, compi non solo un buon gesto, ma un atto di servizio privo di desideri egoistici. In quei momenti estendi con la tua attenzione il collegamento tra la tua azione e Dio, e la tua azione si trasformerà in un''offerta sull''altare dell''universo. E la risposta alla tua azione non verrà come gratitudine umana o segni monetari (come di solito accade), ma come pura grazia divina."}],"es":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Consejo del día:\n\nOfrezca ofrendas a Dios a través de las personas. Cuando hace una buena obra, especialmente de forma anónima, no realiza simplemente una buena acción, sino un acto de servicio desprovisto de deseos egoístas. En esos momentos, extienda con su atención la conexión entre su acción y Dios, y su acción se convertirá en una ofrenda en el altar del universo. Y la respuesta a su acción no llegará como agradecimiento humano o signos monetarios (como suele ocurrir), sino como pura gracia divina."}],"pt":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Dica do dia:\n\nFaça oferendas a Deus por meio das pessoas. Quando você faz uma boa ação, especialmente de forma anônima, você realiza não apenas um bom ato, mas um ato de serviço desprovido de desejos egoístas. Nesses momentos, estenda com sua atenção a conexão entre sua ação e Deus, e sua ação se transformará em uma oferenda no altar do universo. E a resposta à sua ação virá não como gratidão humana ou sinais monetários (como costuma acontecer), mas como pura graça divina."}],"nl":[{"type":"video","vimeoId":"1150930259"},{"type":"text","markdown":"### Tip van de dag:\n\nBreng offers aan God via mensen. Wanneer je een goede daad verricht, vooral anoniem, verricht je niet zomaar een goede daad, maar een daad van dienstbaarheid die vrij is van egoïstische verlangens. Trek in zulke momenten met je aandacht de verbinding tussen je daad en God, en je daad verandert in een offer op het altaar van het heelal. En het antwoord op je daad zal niet komen in de vorm van menselijke dankbaarheid of geldelijke tekens (zoals gewoonlijk gebeurt), maar als zuivere goddelijke genade."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-07','intensive-holiness',7,1,'День: 7','[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Совет дня:\n\nОтноситесь к каждому завершению как к возвращению домой. Конец рабочего дня, закрытая дверь, осенний листопад, выдох перед сном или даже прощание с тем, что отжило - мы часто воспринимаем завершение как утрату. Но в большом ритме жизни любое завершение - это возвращение к истоку, где собирается сила для нового круга. Попробуйте провожать каждый закат и каждый завершённый этап не с сожалением, а как возвращение к истоку."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Tip of the day:\n\nTreat every completion as a return home. The end of the working day, a closed door, autumn leaf fall, an exhalation before sleep, or even saying goodbye to what has outlived its time—we often perceive completion as loss. But in the great rhythm of life, any completion is a return to the source, where strength gathers for a new cycle. Try to see off every sunset and every completed stage not with regret, but as a return to the source."}],"de":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Tipp des Tages:\n\nBehandeln Sie jede Vollendung wie eine Heimkehr. Das Ende des Arbeitstages, eine geschlossene Tür, fallendes Herbstlaub, ein Ausatmen vor dem Schlaf oder sogar der Abschied von dem, was sich überlebt hat - wir nehmen Vollendung oft als Verlust wahr. Doch im großen Rhythmus des Lebens ist jede Vollendung eine Rückkehr zum Ursprung, wo Kraft für einen neuen Kreis gesammelt wird. Versuchen Sie, jedem Sonnenuntergang und jedem abgeschlossenen Abschnitt nicht mit Bedauern entgegenzusehen, sondern als einer Rückkehr zum Ursprung."}],"fr":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Conseil du jour :\n\nConsidérez chaque achèvement comme un retour à la maison. La fin d''une journée de travail, une porte fermée, la chute des feuilles d''automne, l''expiration avant le sommeil ou même les adieux à ce qui a fait son temps - nous percevons souvent l''achèvement comme une perte. Mais dans le grand rythme de la vie, tout achèvement est un retour à la source, où se rassemble la force pour un nouveau cycle. Essayez d''accompagner chaque coucher de soleil et chaque étape achevée non pas avec regret, mais comme un retour à la source."}],"it":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Consiglio del giorno:\n\nConsidera ogni conclusione come un ritorno a casa. La fine della giornata lavorativa, una porta chiusa, la caduta delle foglie autunnali, un''espirazione prima di dormire o persino un addio a ciò che ha esaurito la sua funzione - spesso percepiamo la conclusione come una perdita. Ma nel grande ritmo della vita ogni conclusione è un ritorno all''origine, dove si raccoglie la forza per un nuovo ciclo. Prova ad accompagnare ogni tramonto e ogni fase conclusa non con rammarico, ma come un ritorno all''origine."}],"es":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Consejo del día:\n\nTrate cada finalización como un regreso a casa. El final de la jornada laboral, una puerta cerrada, la caída de las hojas otoñales, la exhalación antes de dormir o incluso la despedida de aquello que ha dejado de vivir: a menudo percibimos la finalización como una pérdida. Pero en el gran ritmo de la vida, cualquier finalización es un regreso al origen, donde se reúne la fuerza para un nuevo ciclo. Intente despedir cada atardecer y cada etapa concluida no con pesar, sino como un regreso al origen."}],"pt":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Dica do dia:\n\nTrate cada conclusão como um retorno para casa. O fim do expediente, uma porta fechada, a queda das folhas no outono, a expiração antes de dormir ou até a despedida daquilo que já viveu demais - muitas vezes percebemos a conclusão como uma perda. Mas no grande ritmo da vida, qualquer conclusão é um retorno à fonte, onde se reúne a força para um novo ciclo. Tente acompanhar cada pôr do sol e cada etapa concluída não com pesar, mas como um retorno à fonte."}],"nl":[{"type":"video","vimeoId":"1152119144"},{"type":"text","markdown":"### Tip van de dag:\n\nBeschouw elke afronding als een terugkeer naar huis. Het einde van de werkdag, een gesloten deur, de herfstbladeren die vallen, een uitademing voor het slapengaan of zelfs het afscheid nemen van wat is uitgediend - vaak ervaren we een afronding als een verlies. Maar in het grote ritme van het leven is elke afronding een terugkeer naar de bron, waar kracht wordt verzameld voor een nieuwe cyclus. Probeer elke zonsondergang en elke afgeronde fase niet met spijt uit te luiden, maar als een terugkeer naar de bron."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-08','intensive-holiness',8,1,'День: 8','[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Совет дня:\n\nОтпустите все свои концепции о Боге. Любое ваше представление о Боге - это лишь крошечный идол, ограничивающий Его безграничность. Чтобы познать Истину, будьте готовы отбросить всё, что вы о ней знаете. Абсолютно всё! В том числе ваши представления о том, что Бог - добр, гармоничен, мудр, силён, здоров... Чем больше у вас \"привязанностей\" - положительных или отрицательных - тем больше уроков вы будете получать, чтобы от них освободиться. Поэтому сделайте шаг в мистическую темноту, где ум умолкает, и душа встречается с тайной напрямую, без посредников в виде ваших ожиданий."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Tip of the day:\n\nLet go of all your concepts of God. Any of your ideas about God is merely a tiny idol limiting His boundlessness. To know the Truth, be ready to discard everything that you know about it. Absolutely everything! Including your ideas that God is good, harmonious, wise, strong, healthy... The more “attachments” you have—positive or negative—the more lessons you will receive in order to free yourself from them. Therefore take a step into the mystical darkness, where the mind falls silent, and the soul meets the mystery directly, without intermediaries in the form of your expectations."}],"de":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Tipp des Tages:\n\nLassen Sie alle Ihre Konzepte von Gott los. Jede Ihrer Vorstellungen von Gott ist nur ein winziger Götze, der Seine Grenzenlosigkeit einschränkt. Um die Wahrheit zu erkennen, seien Sie bereit, alles abzuwerfen, was Sie über sie wissen. Absolut alles! Darunter auch Ihre Vorstellungen davon, dass Gott gut, harmonisch, weise, stark, gesund ist... Je mehr „Bindungen“ Sie haben - positive oder negative -, desto mehr Lektionen werden Sie erhalten, um sich von ihnen zu befreien. Machen Sie daher einen Schritt in die mystische Dunkelheit, wo der Verstand verstummt und die Seele der Geheimnis direkt begegnet, ohne Vermittler in Gestalt Ihrer Erwartungen."}],"fr":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Conseil du jour :\n\nLâchez toutes vos conceptions de Dieu. Toute représentation que vous avez de Dieu n''est qu''une minuscule idole, limitant Son infinité. Pour connaître la Vérité, soyez prêt à rejeter tout ce que vous savez d''elle. Absolument tout ! Y compris vos représentations selon lesquelles Dieu est bon, harmonieux, sage, fort, sain... Plus vous avez d''« attachements » - positifs ou négatifs - plus vous recevrez de leçons pour vous en libérer. Alors faites un pas dans l''obscurité mystique, où le mental se tait, et l''âme rencontre le mystère directement, sans intermédiaires sous la forme de vos attentes."}],"it":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Consiglio del giorno:\n\nLascia andare tutte le tue concezioni di Dio. Qualsiasi tua rappresentazione di Dio è solo un minuscolo idolo che limita la Sua illimitatezza. Per conoscere la Verità, sii pronto a scartare tutto ciò che ne sai. Assolutamente tutto! Comprese le tue rappresentazioni secondo cui Dio è buono, armonioso, saggio, forte, sano... Più hai «attaccamenti» - positivi o negativi - più lezioni riceverai per liberartene. Perciò fai un passo nella tenebra mistica, dove la mente tace e l''anima incontra il mistero direttamente, senza intermediari sotto forma delle tue aspettative."}],"es":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Consejo del día:\n\nSuelte todas sus concepciones sobre Dios. Cualquier representación suya de Dios es solo un ídolo diminuto que limita Su infinitud. Para conocer la Verdad, esté dispuesto a desechar todo lo que sabe sobre ella. ¡Absolutamente todo! Incluidas sus ideas de que Dios es bondadoso, armonioso, sabio, fuerte, sano... Cuantas más \"ataduras\" tenga —positivas o negativas—, más lecciones recibirá para liberarse de ellas. Por eso, dé un paso hacia la oscuridad mística, donde la mente calla y el alma se encuentra con el misterio directamente, sin intermediarios en forma de sus expectativas."}],"pt":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Dica do dia:\n\nLiberte-se de todas as suas concepções sobre Deus. Qualquer representação sua de Deus é apenas um ídolo minúsculo, que limita Sua infinitude. Para conhecer a Verdade, esteja pronto para abandonar tudo o que você sabe sobre ela. Absolutamente tudo! Inclusive suas representações de que Deus é bom, harmonioso, sábio, forte, saudável... Quanto mais \"apegos\" você tiver - positivos ou negativos - mais lições receberá para se libertar deles. Portanto, dê um passo na escuridão mística, onde a mente silencia, e a alma encontra o mistério diretamente, sem intermediários na forma de suas expectativas."}],"nl":[{"type":"video","vimeoId":"1148411660"},{"type":"text","markdown":"### Tip van de dag:\n\nLaat al je concepten over God los. Elke voorstelling die je van God hebt, is slechts een klein afgodsbeeld dat Zijn grenzeloosheid beperkt. Om de Waarheid te kennen, moet je bereid zijn alles wat je erover weet weg te werpen. Absoluut alles! Ook je voorstellingen dat God goed, harmonieus, wijs, sterk, gezond is... Hoe meer \"gehechtheden\" je hebt - positieve of negatieve - hoe meer lessen je zult krijgen om je daarvan te bevrijden. Zet daarom een stap in de mystieke duisternis, waar de geest verstomt en de ziel de mysteriën rechtstreeks ontmoet, zonder bemiddelaars in de vorm van je verwachtingen."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-09','intensive-holiness',9,1,'День: 9','[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Совет дня:\n\nСоздайте в своем доме небольшой алтарь. Это может быть нерелигиозное, но священное для вас место. Положите туда предметы, которые соединяют вас с Высшим: красивый кристалл, фотографию заката, перо, найденное на прогулке... То есть не просто икону, купленную в церковной лавке, а предметы, с каждым из которых связано реальное воспоминание о моменте вашей жизни, когда вы отчётливо ощущали близость Бога или максимально возвышенные состояния. Этот островок святости станет прекрасным местом для вашей молитвы и настройки на высокие вибрации."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Tip of the day:\n\nCreate a small altar in your home. It can be a non-religious but sacred place for you. Put there objects that connect you with the Higher: a beautiful crystal, a photograph of a sunset, a feather found on a walk... That is, not just an icon bought in a church shop, but objects each of which is connected with a real memory of a moment in your life when you clearly felt the closeness of God or the most elevated states. This island of holiness will become a wonderful place for your prayer and attunement to high vibrations."}],"de":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Tipp des Tages:\n\nErrichten Sie in Ihrem Zuhause einen kleinen Altar. Das kann ein nichtreligiöser, aber für Sie heiliger Ort sein. Legen Sie dorthin Gegenstände, die Sie mit dem Höchsten verbinden: einen schönen Kristall, ein Foto eines Sonnenuntergangs, eine auf einem Spaziergang gefundene Feder... Das heißt nicht einfach eine in einem Kirchenladen gekaufte Ikone, sondern Gegenstände, mit denen jeweils eine wirkliche Erinnerung an einen Augenblick Ihres Lebens verbunden ist, in dem Sie die Nähe Gottes oder höchst erhabene Zustände deutlich empfunden haben. Diese Insel der Heiligkeit wird ein wunderbarer Ort für Ihr Gebet und Ihre Einstimmung auf hohe Schwingungen."}],"fr":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Conseil du jour :\n\nCréez dans votre maison un petit autel. Cela peut être un lieu non religieux, mais sacré pour vous. Déposez-y des objets qui vous relient au Plus Haut : un beau cristal, une photographie de coucher de soleil, une plume trouvée en promenade... C''est-à-dire non pas simplement une icône achetée dans une boutique d''église, mais des objets dont chacun est lié à un souvenir réel d''un moment de votre vie où vous avez clairement ressenti la proximité de Dieu ou des états extrêmement élevés. Cet îlot de sainteté deviendra un lieu merveilleux pour votre prière et pour vous accorder aux hautes vibrations."}],"it":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Consiglio del giorno:\n\nCrea nella tua casa un piccolo altare. Può essere un luogo non religioso, ma sacro per te. Metti lì oggetti che ti collegano al Supremo: un bel cristallo, la fotografia di un tramonto, una piuma trovata durante una passeggiata... Cioè non semplicemente un''icona comprata in un negozio di chiesa, ma oggetti a ciascuno dei quali è legato un ricordo reale del momento della tua vita in cui sentivi chiaramente la vicinanza di Dio o stati massimamente elevati. Questo isolotto di santità diventerà un luogo meraviglioso per la tua preghiera e per sintonizzarti su vibrazioni elevate."}],"es":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Consejo del día:\n\nCree en su casa un pequeño altar. Puede ser un lugar no religioso, pero sagrado para usted. Coloque allí objetos que lo conecten con lo Supremo: un cristal hermoso, una fotografía de un atardecer, una pluma encontrada durante un paseo... Es decir, no simplemente un icono comprado en la tienda de la iglesia, sino objetos con cada uno de los cuales está vinculado un recuerdo real del momento de su vida en que sintió con claridad la cercanía de Dios o estados máximamente elevados. Este islote de santidad se convertirá en un lugar maravilloso para su oración y para sintonizarse con las altas vibraciones."}],"pt":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Dica do dia:\n\nCrie em sua casa um pequeno altar. Pode ser um lugar não religioso, mas sagrado para você. Coloque ali objetos que conectam você ao Supremo: um cristal bonito, uma foto do pôr do sol, uma pena encontrada em uma caminhada... Ou seja, não apenas um ícone comprado na loja da igreja, mas objetos a cada um dos quais está ligada uma lembrança real de um momento da sua vida em que você sentiu claramente a proximidade de Deus ou estados maximamente elevados. Essa pequena ilha de santidade se tornará um lugar maravilhoso para sua oração e sintonia com vibrações elevadas."}],"nl":[{"type":"video","vimeoId":"1159541354"},{"type":"text","markdown":"### Tip van de dag:\n\nMaak in je huis een klein altaar. Het kan een niet-religieuze, maar voor jou heilige plek zijn. Leg daar voorwerpen neer die je met het Hoogste verbinden: een mooi kristal, een foto van een zonsondergang, een veer die je tijdens een wandeling hebt gevonden... Dus niet zomaar een icoon dat in een kerkwinkel is gekocht, maar voorwerpen waaraan elk een echte herinnering is verbonden aan een moment in je leven waarop je duidelijk de nabijheid van God of de meest verheven toestanden ervoer. Dit eilandje van heiligheid wordt een prachtige plek voor je gebed en voor het afstemmen op hoge vibraties."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-10','intensive-holiness',10,1,'День: 10','[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Совет дня:\n\nЗасыпая, растворяйтесь в свете. Перед сном, лежа в постели с закрытыми глазами, увидьте или представьте чистый белый свет, заполняющий всё пространство. Ощутите, как вы растворяетесь в нём и направляетесь к его источнику."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Tip of the day:\n\nAs you fall asleep, dissolve in the light. Before sleep, lying in bed with your eyes closed, see or imagine a pure white light filling all space. Feel how you dissolve in it and move toward its source."}],"de":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Tipp des Tages:\n\nWenn Sie einschlafen, lösen Sie sich im Licht auf. Sehen oder stellen Sie sich vor dem Schlaf, im Bett liegend mit geschlossenen Augen, ein reines weißes Licht vor, das den gesamten Raum erfüllt. Fühlen Sie, wie Sie sich in ihm auflösen und sich zu seiner Quelle begeben."}],"fr":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Conseil du jour :\n\nEn vous endormant, dissolvez-vous dans la lumière. Avant le sommeil, allongé dans le lit les yeux fermés, voyez ou imaginez une pure lumière blanche remplissant tout l''espace. Sentez comment vous vous dissolvez en elle et vous vous dirigez vers sa source."}],"it":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAddormentandoti, dissolviti nella luce. Prima di dormire, nel letto con gli occhi chiusi, vedi o immagina una luce bianca pura che riempie tutto lo spazio. Senti come ti dissolvi in essa e ti dirigi verso la sua fonte."}],"es":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Consejo del día:\n\nAl quedarse dormido, disuélvase en la luz. Antes de dormir, acostado en la cama con los ojos cerrados, vea o imagine una luz blanca pura que llena todo el espacio. Sienta cómo se disuelve en ella y se dirige hacia su fuente."}],"pt":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Dica do dia:\n\nAo adormecer, dissolva-se na luz. Antes de dormir, deitado na cama com os olhos fechados, veja ou imagine uma luz branca pura preenchendo todo o espaço. Sinta como você se dissolve nela e se dirige à sua fonte."}],"nl":[{"type":"video","vimeoId":"1133459364"},{"type":"text","markdown":"### Tip van de dag:\n\nTerwijl je in slaap valt, los je op in het licht. Voordat je gaat slapen, liggend in bed met gesloten ogen, zie of stel je een zuiver wit licht voor dat de hele ruimte vult. Voel hoe je erin oplost en je naar de bron ervan beweegt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-11','intensive-holiness',11,1,'День: 11','[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Совет дня:\n\nВсегда поступайте по совести - особенно если это вам невыгодно. Ваше истинное Я неразрывно связано с вашей совестью. И вы всегда чувствуете, какой выбор, какое действие совершается по совести, а какое нет. Следование этому знанию может быть неудобным для вашего эго, но каждый такой шаг укрепляет ваш внутренний стержень и приближает вас к Богу. Если такие действия приводят к невыгодному для вас результату, рассматривайте происходящее, как духовное очищение."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Tip of the day:\n\nAlways act according to your conscience—especially if it is disadvantageous to you. Your true Self is inseparably connected with your conscience. And you always feel which choice, which action is done according to conscience and which is not. Following this knowledge may be inconvenient for your ego, but every such step strengthens your inner core and brings you closer to God. If such actions lead to a result that is disadvantageous for you, regard what is happening as spiritual purification."}],"de":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Tipp des Tages:\n\nHandeln Sie immer nach dem Gewissen - besonders wenn es für Sie nachteilig ist. Ihr wahres Ich ist untrennbar mit Ihrem Gewissen verbunden. Und Sie spüren immer, welche Wahl, welche Handlung nach dem Gewissen geschieht und welche nicht. Diesem Wissen zu folgen kann für Ihr Ego unbequem sein, doch jeder solche Schritt stärkt Ihren inneren Kern und bringt Sie Gott näher. Wenn solche Handlungen zu einem für Sie nachteiligen Ergebnis führen, betrachten Sie das Geschehen als spirituelle Reinigung."}],"fr":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Conseil du jour :\n\nAgissez toujours selon votre conscience - surtout si cela ne vous est pas avantageux. Votre véritable Moi est inextricablement lié à votre conscience. Et vous sentez toujours quel choix, quelle action est accomplie selon la conscience, et laquelle ne l''est pas. Suivre cette connaissance peut être inconfortable pour votre ego, mais chacun de ces pas renforce votre axe intérieur et vous rapproche de Dieu. Si de telles actions conduisent à un résultat qui ne vous est pas avantageux, considérez ce qui se passe comme une purification spirituelle."}],"it":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAgisci sempre secondo coscienza - soprattutto se questo non ti conviene. Il tuo vero Sé è indissolubilmente legato alla tua coscienza. E senti sempre quale scelta, quale azione è compiuta secondo coscienza e quale no. Seguire questa conoscenza può essere scomodo per il tuo ego, ma ogni tale passo rafforza il tuo asse interiore e ti avvicina a Dio. Se tali azioni portano a un risultato svantaggioso per te, considera ciò che accade come una purificazione spirituale."}],"es":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Consejo del día:\n\nActúe siempre según la conciencia, especialmente si eso le resulta desfavorable. Su verdadero Yo está indisolublemente vinculado a su conciencia. Y usted siempre siente qué elección, qué acción se realiza según la conciencia y cuál no. Seguir este conocimiento puede ser incómodo para su ego, pero cada paso así fortalece su eje interno y lo acerca a Dios. Si tales acciones conducen a un resultado desfavorable para usted, considere lo que ocurre como una purificación espiritual."}],"pt":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Dica do dia:\n\nSempre aja conforme a consciência - especialmente se isso for desvantajoso para você. Seu verdadeiro Eu está indissociavelmente ligado à sua consciência. E você sempre sente qual escolha, qual ação é feita conforme a consciência e qual não é. Seguir esse conhecimento pode ser desconfortável para o seu ego, mas cada passo assim fortalece seu núcleo interno e aproxima você de Deus. Se tais ações levarem a um resultado desvantajoso para você, considere o que acontece como uma purificação espiritual."}],"nl":[{"type":"video","vimeoId":"1135986521"},{"type":"text","markdown":"### Tip van de dag:\n\nHandel altijd volgens je geweten - vooral als het je niet voordelig uitkomt. Je ware Zelf is onlosmakelijk verbonden met je geweten. En je voelt altijd welke keuze, welke daad volgens het geweten wordt gedaan en welke niet. Dit weten volgen kan ongemakkelijk zijn voor je ego, maar elke zulke stap versterkt je innerlijke ruggengraat en brengt je dichter bij God. Als zulke daden tot een voor jou nadelig resultaat leiden, beschouw wat er gebeurt dan als een spirituele zuivering."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-12','intensive-holiness',12,1,'День: 12','[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Совет дня:\n\nИщите не человеческого счастья, а блаженства соединения с Богом. Человеческое счастье зависит от внешних условий и всегда временно. Блаженство (Ананда) - это внутреннее состояние, рождающееся от соприкосновения с вашей божественной сутью. Перестаньте гоняться за мирскими удовольствиями и начните культивировать тихую, глубокую радость от самого факта своего Бытия."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Tip of the day:\n\nSeek not human happiness, but the bliss of union with God. Human happiness depends on external conditions and is always temporary. Bliss (Ananda) is an inner state born from contact with your divine essence. Stop chasing worldly pleasures and begin cultivating a quiet, deep joy from the very fact of your Being."}],"de":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Tipp des Tages:\n\nSuchen Sie nicht menschliches Glück, sondern die Glückseligkeit der Verbindung mit Gott. Menschliches Glück hängt von äußeren Bedingungen ab und ist immer vorübergehend. Glückseligkeit (Ananda) ist ein innerer Zustand, der aus der Berührung mit Ihrem göttlichen Wesen entsteht. Hören Sie auf, weltlichen Vergnügungen nachzujagen, und beginnen Sie, die stille, tiefe Freude am bloßen Fakt Ihres Seins zu kultivieren."}],"fr":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Conseil du jour :\n\nNe cherchez pas le bonheur humain, mais la béatitude de l''union avec Dieu. Le bonheur humain dépend de conditions extérieures et est toujours temporaire. La béatitude (Ananda) est un état intérieur qui naît du contact avec votre essence divine. Cessez de courir après les plaisirs mondains et commencez à cultiver une joie tranquille et profonde du simple fait de votre Être."}],"it":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Consiglio del giorno:\n\nCerca non la felicità umana, ma la beatitudine dell''unione con Dio. La felicità umana dipende dalle condizioni esterne ed è sempre temporanea. La beatitudine (Ananda) è uno stato interiore che nasce dal contatto con la tua essenza divina. Smetti di rincorrere i piaceri mondani e inizia a coltivare una gioia silenziosa e profonda per il fatto stesso del tuo Essere."}],"es":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Consejo del día:\n\nBusque no la felicidad humana, sino la bienaventuranza de la unión con Dios. La felicidad humana depende de las condiciones externas y siempre es temporal. La bienaventuranza (Ananda) es un estado interno que nace del contacto con su esencia divina. Deje de perseguir los placeres mundanos y comience a cultivar una alegría silenciosa y profunda por el hecho mismo de su Existencia."}],"pt":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Dica do dia:\n\nBusque não a felicidade humana, mas a bem-aventurança da união com Deus. A felicidade humana depende de condições externas e é sempre temporária. A bem-aventurança (Ananda) é um estado interno que nasce do contato com sua essência divina. Pare de correr atrás dos prazeres mundanos e comece a cultivar uma alegria silenciosa e profunda pelo próprio fato de seu Ser."}],"nl":[{"type":"video","vimeoId":"1158054855"},{"type":"text","markdown":"### Tip van de dag:\n\nZoek niet naar menselijk geluk, maar naar de gelukzaligheid van de vereniging met God. Menselijk geluk hangt af van uiterlijke omstandigheden en is altijd tijdelijk. Gelukzaligheid (Ananda) is een innerlijke staat die geboren wordt uit de aanraking met je goddelijke essentie. Stop met jagen op wereldse genoegens en begin een stille, diepe vreugde te cultiveren om het feit zelf van je Zijn."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-13','intensive-holiness',13,1,'День: 13','[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Совет дня:\n\nИзучайте мифы и религии как разные языки описания Бога. Древнегреческие мифы, махабхарата, евангелие, коран, сутры буддизма - всё это лишь разные языки, на которых человеческий дух в разные времена и в разных культурах пытался описать то, что находится за пределами жизни и смерти, то, что наполняет наше существование высшим смыслом. С интересом и уважением изучая каждый из этих языков, вы расширяете свой словарь, понимаете, что все пути ведут в одном направлении, и находите свой собственный путь."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Tip of the day:\n\nStudy myths and religions as different languages of describing God. Ancient Greek myths, the Mahabharata, the Gospel, the Quran, the sutras of Buddhism—all these are merely different languages in which the human spirit at different times and in different cultures tried to describe what lies beyond life and death, what fills our existence with higher meaning. Studying each of these languages with interest and respect, you expand your vocabulary, understand that all paths lead in one direction, and find your own path."}],"de":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Tipp des Tages:\n\nStudieren Sie Mythen und Religionen als verschiedene Sprachen der Beschreibung Gottes. Altgriechische Mythen, die Mahabharata, das Evangelium, der Koran, die Sutren des Buddhismus - all das sind nur verschiedene Sprachen, in denen der menschliche Geist zu verschiedenen Zeiten und in verschiedenen Kulturen versuchte zu beschreiben, was jenseits von Leben und Tod liegt, was unser Dasein mit höchstem Sinn erfüllt. Wenn Sie jede dieser Sprachen mit Interesse und Respekt studieren, erweitern Sie Ihren Wortschatz, verstehen, dass alle Wege in eine Richtung führen, und finden Ihren eigenen Weg."}],"fr":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Conseil du jour :\n\nÉtudiez les mythes et les religions comme différents langages de description de Dieu. Les mythes de la Grèce antique, la Mahabharata, l''Évangile, le Coran, les soutras du bouddhisme - tout cela n''est que différents langages par lesquels l''esprit humain, à différentes époques et dans différentes cultures, a tenté de décrire ce qui se trouve au-delà de la vie et de la mort, ce qui remplit notre existence d''un sens suprême. En étudiant chacun de ces langages avec intérêt et respect, vous élargissez votre vocabulaire, vous comprenez que tous les chemins mènent dans une même direction, et vous trouvez votre propre chemin."}],"it":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Consiglio del giorno:\n\nStudia i miti e le religioni come linguaggi diversi di descrizione di Dio. I miti dell''antica Grecia, il Mahabharata, il Vangelo, il Corano, i sutra del buddismo - tutto questo sono solo linguaggi diversi con cui lo spirito umano in tempi e culture diverse ha cercato di descrivere ciò che sta oltre la vita e la morte, ciò che riempie la nostra esistenza di senso supremo. Studiando ciascuno di questi linguaggi con interesse e rispetto, ampli il tuo vocabolario, comprendi che tutte le vie conducono in un''unica direzione e trovi il tuo cammino personale."}],"es":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Consejo del día:\n\nEstudie los mitos y las religiones como distintos lenguajes de descripción de Dios. Los mitos de la antigua Grecia, el Mahabharata, el Evangelio, el Corán, los sutras del budismo: todo ello son solo lenguajes distintos con los que el espíritu humano, en distintas épocas y culturas, intentó describir lo que está más allá de la vida y la muerte, lo que llena nuestra existencia de sentido supremo. Estudiando cada uno de estos lenguajes con interés y respeto, amplía su vocabulario, comprende que todos los caminos conducen en una misma dirección y encuentra su propio camino."}],"pt":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Dica do dia:\n\nEstude os mitos e as religiões como diferentes linguagens de descrição de Deus. Os mitos da Grécia Antiga, o Mahabharata, o Evangelho, o Corão, os sutras do budismo - tudo isso são apenas linguagens diferentes nas quais o espírito humano, em diferentes épocas e culturas, tentou descrever o que está para além da vida e da morte, o que preenche nossa existência com sentido supremo. Estudando cada uma dessas linguagens com interesse e respeito, você amplia seu vocabulário, entende que todos os caminhos levam em uma mesma direção e encontra seu próprio caminho."}],"nl":[{"type":"video","vimeoId":"1126389105"},{"type":"text","markdown":"### Tip van de dag:\n\nBestudeer mythen en religies als verschillende talen waarin God wordt beschreven. Oud-Griekse mythen, de Mahabharata, het Evangelie, de Koran, de soetra''s van het boeddhisme - dat zijn allemaal slechts verschillende talen waarin de menselijke geest in verschillende tijden en culturen heeft geprobeerd te beschrijven wat buiten leven en dood ligt, wat ons bestaan van de hoogste betekenis vervult. Door elk van deze talen met interesse en respect te bestuderen, verruim je je vocabulaire, begrijp je dat alle wegen in één richting leiden, en vind je je eigen weg."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-14','intensive-holiness',14,1,'День: 14','[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Совет дня:\n\nПомните, что получатель всех ваших действий - Бог. Что бы вы ни делали, обычно вы можете понимать какой человек является получателем ваших полученным от вас ресурсом, тоже что-то сделает, и адресат его действий тоже что-то сделает… Получается, что каждое ваше действие отзывается бесконечным и вечным эхом, и нет конечного получателя ни в пространстве, ни во времени. То есть вы взаимодействуете с бесконечным и вечным. Можете называть его Богом или любым другим именем. Понимание этого наполняет ваши действия особым смыслом."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Tip of the day:\n\nRemember that the recipient of all your actions is God. Whatever you do, usually you can understand which person is the recipient of your resources received from you, will also do something, and the addressee of his actions will also do something… It turns out that each of your actions resonates with an infinite and eternal echo, and there is no final recipient either in space or in time. That is, you interact with the infinite and eternal. You can call it God or any other name. Understanding this fills your actions with special meaning."}],"de":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Tipp des Tages:\n\nDenken Sie daran, dass der Empfänger all Ihrer Handlungen Gott ist. Was auch immer Sie tun, gewöhnlich können Sie verstehen, welcher Mensch der Empfänger Ihrer von Ihnen erhaltenen Ressource ist, auch er wird etwas tun, und der Adressat seiner Handlungen wird ebenfalls etwas tun… Es ergibt sich, dass jede Ihre Handlung in einem unendlichen und ewigen Echo widerhallt, und es gibt keinen endgültigen Empfänger weder im Raum noch in der Zeit. Das heißt, Sie interagieren mit dem Unendlichen und Ewigen. Sie können es Gott oder mit jedem anderen Namen nennen. Das Verständnis dessen erfüllt Ihre Handlungen mit besonderem Sinn."}],"fr":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Conseil du jour :\n\nSouvenez-vous que le destinataire de toutes vos actions est Dieu. Quoi que vous fassiez, vous pouvez habituellement comprendre quel être humain est le destinataire de vos ressources reçues de vous, fera lui aussi quelque chose, et le destinataire de ses actions fera lui aussi quelque chose… Il s''ensuit que chacune de vos actions résonne d''un écho infini et éternel, et qu''il n''existe pas de destinataire final, ni dans l''espace, ni dans le temps. C''est-à-dire que vous interagissez avec l''infini et l''éternel. Vous pouvez l''appeler Dieu ou tout autre nom. La compréhension de cela remplit vos actions d''un sens particulier."}],"it":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRicorda che il destinatario di tutte le tue azioni è Dio. Qualunque cosa tu faccia, di solito puoi capire quale persona è destinataria delle tue risorse, anch''essa farà qualcosa, e il destinatario delle sue azioni farà anch''esso qualcosa… Ne risulta che ogni tua azione risuona con un''eco infinita ed eterna, e non c''è un destinatario finale né nello spazio né nel tempo. Cioè, tu interagisci con l''infinito e l''eterno. Puoi chiamarlo Dio o con qualsiasi altro nome. Comprendere questo riempie le tue azioni di un significato speciale."}],"es":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Consejo del día:\n\nRecuerde que el receptor de todas sus acciones es Dios. Haga lo que haga, por lo general puede comprender qué persona es receptora de los recursos que recibió de usted, también hará algo, y el destinatario de sus acciones también hará algo… Resulta que cada acción suya resuena con un eco infinito y eterno, y no hay un receptor final ni en el espacio ni en el tiempo. Es decir, usted interactúa con lo infinito y eterno. Puede llamarlo Dios o con cualquier otro nombre. La comprensión de esto llena sus acciones de un significado especial."}],"pt":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Dica do dia:\n\nLembre-se de que o destinatário de todas as suas ações é Deus. Faça o que fizer, normalmente você pode entender que a pessoa que é a recebedora do seu recurso recebido de você também fará algo, e o destinatário das ações dela também fará algo… Acontece que cada ação sua ecoa como um eco infinito e eterno, e não há destinatário final nem no espaço nem no tempo. Ou seja, você interage com o infinito e o eterno. Você pode chamá-lo de Deus ou de qualquer outro nome. A compreensão disso preenche suas ações de um sentido especial."}],"nl":[{"type":"video","vimeoId":"1156739899"},{"type":"text","markdown":"### Tip van de dag:\n\nOnthoud dat de ontvanger van al je daden God is. Wat je ook doet, meestal kun je begrijpen welke persoon de ontvanger is van jouw handeling, dat ook hij, met de hulpbron die hij van jou heeft ontvangen, iets zal doen, en dat de ontvanger van zijn daden ook weer iets zal doen… Zo blijkt dat elke daad van jou weerklinkt in een eindeloze en eeuwige echo, en er is geen eindontvanger, noch in de ruimte, noch in de tijd. Dat wil zeggen, je hebt met het oneindige en eeuwige te maken. Je kunt het God noemen of elke andere naam. Het begrip hiervan vervult je daden met een bijzondere betekenis."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-15','intensive-holiness',15,1,'День: 15','[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Совет дня:\n\nВ моменты отчаяния открывайтесь Богу. Когда вам кажется, что всё рухнуло, что вы сделали всё возможное и сил больше нет, перестаньте бороться. Просто поднимите руки вверх в жесте принятия, соединитесь своим вниманием с Богом (Вселенной), намерения которого значительно масштабней ваших возможностей их понять, и искренне скажите: «Да будет воля твоя. Я тебе доверяю!». Этот акт капитуляции перед Высшим Замыслом не является поражением; это момент, когда ваша личная воля соединяется с волей Вселенной, и помощь приходит."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Tip of the day:\n\nIn moments of despair, open to God. When it seems to you that everything has collapsed, that you have done everything possible and have no strength left, stop fighting. Simply raise your hands upward in a gesture of acceptance, connect with your attention to God (the Universe), whose intentions are significantly larger than your ability to understand them, and sincerely say: “Thy will be done. I trust you!”. This act of capitulation before the Higher Design is not a defeat; it is the moment when your personal will unites with the will of the Universe, and help comes."}],"de":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Tipp des Tages:\n\nIn Momenten der Verzweiflung öffnen Sie sich Gott. Wenn es Ihnen scheint, dass alles zusammengebrochen ist, dass Sie alles Mögliche getan haben und keine Kraft mehr bleibt, hören Sie auf zu kämpfen. Heben Sie einfach die Hände empor in einer Geste der Annahme, verbinden Sie sich mit Ihrer Aufmerksamkeit mit Gott (dem Universum), dessen Absichten deutlich größer sind als Ihre Möglichkeiten, sie zu verstehen, und sagen Sie aufrichtig: „Dein Wille geschehe. Ich vertraue dir!“. Dieser Akt der Kapitulation vor dem Höchsten Plan ist keine Niederlage; es ist der Moment, in dem Ihr persönlicher Wille sich mit dem Willen des Universums verbindet und Hilfe kommt."}],"fr":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Conseil du jour :\n\nDans les moments de désespoir, ouvrez-vous à Dieu. Lorsque vous avez l''impression que tout s''est effondré, que vous avez fait tout le possible et que vous n''avez plus de forces, cessez de lutter. Levez simplement les bras en un geste d''acceptation, reliez votre attention à Dieu (l''Univers), dont les intentions dépassent largement vos capacités de les comprendre, et dites sincèrement : « Que ta volonté soit faite. Je te fais confiance ! ». Cet acte de capitulation devant le Dessein Suprême n''est pas une défaite ; c''est le moment où votre volonté personnelle s''unit à la volonté de l''Univers, et où l''aide arrive."}],"it":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Consiglio del giorno:\n\nNei momenti di disperazione apriti a Dio. Quando ti sembra che tutto sia crollato, che tu abbia fatto tutto il possibile e che le forze non ci siano più, smetti di lottare. Solleva semplicemente le mani in un gesto di accettazione, unisci la tua attenzione a Dio (l''Universo), le cui intenzioni sono molto più vaste delle tue possibilità di comprenderle, e di'' sinceramente: «Sia fatta la tua volontà. Io mi fido di te!». Questo atto di capitolazione davanti al Disegno Superiore non è una sconfitta; è il momento in cui la tua volontà personale si unisce alla volontà dell''Universo, e l''aiuto arriva."}],"es":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Consejo del día:\n\nEn los momentos de desesperación, ábrase a Dios. Cuando le parezca que todo se ha derrumbado, que ha hecho todo lo posible y ya no tiene fuerzas, deje de luchar. Simplemente levante las manos hacia arriba en un gesto de aceptación, conéctese con su atención con Dios (el Universo), cuyas intenciones son mucho más grandes que sus posibilidades de comprenderlas, y diga con sinceridad: «Hágase tu voluntad. ¡Confío en ti!». Este acto de capitulación ante el Plan Superior no es una derrota; es el momento en que su voluntad personal se une a la voluntad del Universo, y llega la ayuda."}],"pt":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Dica do dia:\n\nNos momentos de desespero, abra-se a Deus. Quando lhe parecer que tudo desabou, que você fez todo o possível e não há mais forças, pare de lutar. Simplesmente levante as mãos em um gesto de aceitação, conecte sua atenção com Deus (o Universo), cujas intenções são significativamente mais amplas do que suas capacidades de compreendê-las, e diga com sinceridade: «Faça-se a tua vontade. Eu confio em ti!». Esse ato de capitulação diante do Plano Superior não é uma derrota; é o momento em que sua vontade pessoal se une à vontade do Universo, e a ajuda chega."}],"nl":[{"type":"video","vimeoId":"1136780244"},{"type":"text","markdown":"### Tip van de dag:\n\nOpen je in momenten van wanhoop voor God. Wanneer het je lijkt dat alles is ingestort, dat je alles hebt gedaan wat mogelijk is en dat je geen kracht meer hebt, stop dan met vechten. Hef eenvoudig je armen op in een gebaar van aanvaarding, verbind je aandacht met God (het Universum), wiens bedoelingen veel groter zijn dan jouw vermogen om ze te begrijpen, en zeg oprecht: «Uw wil geschiede. Ik vertrouw op U!». Deze daad van overgave aan de Hogere Bedoeling is geen nederlaag; het is het moment waarop je persoonlijke wil zich verenigt met de wil van het Universum, en er hulp komt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-16','intensive-holiness',16,1,'День: 16','[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Совет дня:\n\nВ каждом человеке приветствуйте Бога или Богиню. За социальной маской, возрастом и статусом в каждом человеке проявляется божественная сила, в том числе архетипическая сила древнегреческих божеств. Перечитайте мифы древней Греции. Они помогут вам настроиться на нужную волну. И далее, глядя на женщину, с которой общаетесь, увидьте в ней проявление Афродиты, Деметры или Афины… А глядя на мужчину - Зевса, Гермеса, Аполлона или другого бога. Это превращает обычные отношения в мифологическое взаимодействие."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Tip of the day:\n\nWelcome God or Goddess in every person. Behind the social mask, age and status, in every person a divine force manifests, including the archetypal power of the ancient Greek deities. Re-read the myths of ancient Greece. They will help you tune in to the right wave. And then, looking at the woman you are speaking with, see in her a manifestation of Aphrodite, Demeter or Athena… And looking at a man - Zeus, Hermes, Apollo or another god. This turns ordinary relationships into a mythological interaction."}],"de":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Tipp des Tages:\n\nBegrüße in jedem Menschen Gott oder die Göttin. Hinter der sozialen Maske, dem Alter und dem Status zeigt sich in jedem Menschen eine göttliche Kraft, einschließlich der archetypischen Kraft der altgriechischen Gottheiten. Lies die Mythen des antiken Griechenlands erneut. Sie helfen dir, dich auf die richtige Welle einzustimmen. Und wenn du dann eine Frau ansiehst, mit der du sprichst, erkenne in ihr die Erscheinung von Aphrodite, Demeter oder Athene… Und wenn du einen Mann ansiehst - Zeus, Hermes, Apollon oder einen anderen Gott. Das verwandelt gewöhnliche Beziehungen in eine mythologische Interaktion."}],"fr":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Conseil du jour :\n\nSaluez Dieu ou la Déesse en chaque personne. Derrière le masque social, l’âge et le statut, en chaque personne se manifeste une force divine, y compris la force archétypale des divinités de la Grèce antique. Relisez les mythes de la Grèce antique. Ils vous aideront à vous accorder sur la bonne longueur d’onde. Et ensuite, en regardant la femme à qui vous parlez, voyez en elle une manifestation d’Aphrodite, de Déméter ou d’Athéna… Et en regardant un homme — Zeus, Hermès, Apollon ou un autre dieu. Cela transforme des relations ordinaires en une interaction mythologique."}],"it":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Consiglio del giorno:\n\nIn ogni persona salutate Dio o la Dea. Dietro la maschera sociale, l''età e lo status, in ogni persona si manifesta una forza divina, inclusa la forza archetipica delle divinità dell''antica Grecia. Rileggete i miti dell''antica Grecia. Vi aiuteranno a sintonizzarvi sulla giusta onda. E poi, guardando una donna con cui state parlando, vedete in lei una manifestazione di Afrodite, Demetra o Atena… E guardando un uomo: Zeus, Hermes, Apollo o un altro dio. Questo trasforma le relazioni ordinarie in un''interazione mitologica."}],"es":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Consejo del día:\n\nSaluda a Dios o a la Diosa en cada persona. Detrás de la máscara social, la edad y el estatus, en cada persona se manifiesta una fuerza divina, incluida la fuerza arquetípica de las deidades de la antigua Grecia. Relee los mitos de la antigua Grecia. Te ayudarán a sintonizarte con la onda necesaria. Y luego, mirando a la mujer con la que conversas, ve en ella la manifestación de Afrodita, Deméter o Atenea… Y mirando al hombre, a Zeus, Hermes, Apolo u otro dios. Esto transforma las relaciones ordinarias en una interacción mitológica."}],"pt":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Dica do dia:\n\nEm cada pessoa, saúdem Deus ou a Deusa. Por trás da máscara social, da idade e do status, em cada pessoa se manifesta uma força divina, incluindo a força arquetípica das divindades da Grécia Antiga. Releiam os mitos da Grécia Antiga. Eles ajudarão vocês a se sintonizarem com a onda certa. E, em seguida, olhando para a mulher com quem estão conversando, vejam nela a manifestação de Afrodite, Deméter ou Atena… E, olhando para o homem — Zeus, Hermes, Apolo ou outro deus. Isso transforma relações comuns em uma interação mitológica."}],"nl":[{"type":"video","vimeoId":"1156376980"},{"type":"text","markdown":"### Tip van de dag:\n\nGroet in ieder mens de God of de Godin. Achter het sociale masker, de leeftijd en de status manifesteert zich in ieder mens een goddelijke kracht, waaronder de archetypische kracht van de Oudgriekse godheden. Herlees de mythen van het oude Griekenland. Ze helpen je om op de juiste golf af te stemmen. En kijk vervolgens naar de vrouw met wie je spreekt en zie in haar een manifestatie van Aphrodite, Demeter of Athena… En kijk naar een man - Zeus, Hermes, Apollo of een andere god. Dit verandert gewone relaties in een mythologische interactie."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-17','intensive-holiness',17,1,'День: 17','[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Совет дня:\n\nНаблюдайте за синхрониями как за дорожными знаками от Вселенной. Случайные встречи, повторяющиеся числа, вовремя услышанная песня - воспринимайте не как совпадения, а как подсказки ваших невидимых сил поддержки. Благодарите за них, учитесь их читать, и со временем вы поймете, что вас всегда ведут и поддерживают."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Tip of the day:\n\nObserve synchronicities as road signs from the Universe. Random encounters, repeating numbers, a song heard at the right time - perceive them not as coincidences, but as hints from your invisible support forces. Give thanks for them, learn to read them, and over time you will understand that you are always guided and supported."}],"de":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Tipp des Tages:\n\nBeobachte Synchronizitäten wie Verkehrsschilder vom Universum. Zufällige Begegnungen, wiederkehrende Zahlen, ein rechtzeitig gehörtes Lied - nimm sie nicht als Zufälle wahr, sondern als Hinweise deiner unsichtbaren Unterstützungskräfte. Danke für sie, lerne, sie zu lesen, und mit der Zeit wirst du verstehen, dass du immer geführt und unterstützt wirst."}],"fr":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Conseil du jour :\n\nObservez les synchronicités comme des panneaux routiers de l’Univers. Les rencontres fortuites, les nombres répétitifs, une chanson entendue au bon moment — ne les percevez pas comme des coïncidences, mais comme des indices de vos forces de soutien invisibles. Remerciez-les, apprenez à les lire, et avec le temps vous comprendrez que vous êtes toujours guidé et soutenu."}],"it":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Consiglio del giorno:\n\nOsservate le sincronicità come segnali stradali dall''Universo. Incontri casuali, numeri che si ripetono, una canzone ascoltata al momento giusto: non considerateli come coincidenze, ma come indizi delle vostre invisibili forze di sostegno. Rendete grazie per essi, imparate a leggerli, e col tempo capirete che siete sempre guidati e sostenuti."}],"es":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Consejo del día:\n\nObserva las sincronicidades como señales de tráfico del Universo. Encuentros casuales, números repetidos, una canción escuchada a tiempo: percíbelos no como coincidencias, sino como pistas de tus fuerzas de apoyo invisibles. Agradece por ellas, aprende a leerlas, y con el tiempo comprenderás que siempre te guían y te sostienen."}],"pt":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Dica do dia:\n\nObservem as sincronicidades como sinais de trânsito vindos do Universo. Encontros casuais, números repetidos, uma canção ouvida na hora certa — percebam-nos não como coincidências, mas como pistas das suas forças invisíveis de apoio. Agradeçam por elas, aprendam a lê-las e, com o tempo, vocês compreenderão que sempre são guiados e sustentados."}],"nl":[{"type":"video","vimeoId":"1151495252"},{"type":"text","markdown":"### Tip van de dag:\n\nObserveer synchroniciteiten als wegwijzers van het Universum. Toevallige ontmoetingen, terugkerende getallen, een lied dat op het juiste moment wordt gehoord - beschouw ze niet als toeval, maar als aanwijzingen van je onzichtbare ondersteunende krachten. Wees dankbaar voor hen, leer ze te lezen, en na verloop van tijd zul je begrijpen dat je altijd wordt geleid en ondersteund."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-18','intensive-holiness',18,1,'День: 18','[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Совет дня:\n\nКогда путь завален, не спешите повернуть назад. Если вы бьётесь головой о стену, и уже думаете, что так Вселенная (Бог) указывает вам, что это не для вас, прежде чем бросить начатое, успокойтесь и обратитесть к Вселенной с просьбой показать обходной путь. После этого расслабьтесь и дайте время прийти ответу. Бывает так, что совсем рядом находится дверь или незаметная тропа, которая приведёт вас к цели более красивым и интересным путём."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Tip of the day:\n\nWhen the path is blocked, do not rush to turn back. If you are banging your head against a wall, and already think that this is how the Universe (God) is showing you that this is not for you, before abandoning what you have started, calm down and turn to the Universe with a request to show a bypass route. After that, relax and give time for the answer to come. It happens that very nearby there is a door or an inconspicuous path that will lead you to the goal by a more beautiful and interesting way."}],"de":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Tipp des Tages:\n\nWenn der Weg versperrt ist, beeile dich nicht, umzukehren. Wenn du mit dem Kopf gegen die Wand schlägst und schon denkst, dass das Universum (Gott) dir damit zeigt, dass es nicht für dich ist, dann beruhige dich, bevor du das Begonnene aufgibst, und bitte das Universum, dir einen Umweg zu zeigen. Danach entspanne dich und gib der Antwort Zeit zu kommen. Es kommt vor, dass ganz in der Nähe eine Tür oder ein unauffälliger Pfad ist, der dich auf einem schöneren und interessanteren Weg zu deinem Ziel führt."}],"fr":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Conseil du jour :\n\nQuand le chemin est encombré, ne vous empressez pas de faire demi-tour. Si vous vous cognez la tête contre un mur et pensez déjà que c’est ainsi que l’Univers (Dieu) vous indique que ce n’est pas pour vous, avant d’abandonner ce que vous avez commencé, calmez-vous et adressez-vous à l’Univers en lui demandant de vous montrer un chemin de contournement. Ensuite, détendez-vous et laissez le temps à la réponse d’arriver. Il arrive qu’une porte tout près, ou un sentier discret, vous conduise au but par une voie plus belle et plus intéressante."}],"it":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Consiglio del giorno:\n\nQuando il percorso è ostruito, non affrettatevi a tornare indietro. Se sbattete la testa contro un muro e pensate già che così l''Universo (Dio) vi stia indicando che questo non è per voi, prima di abbandonare ciò che avete iniziato, calmatevi e chiedete all''Universo di mostrarvi una via alternativa. Dopo di che rilassatevi e date tempo alla risposta di arrivare. A volte accade che proprio lì vicino ci sia una porta o un sentiero poco visibile che vi condurrà alla meta per una via più bella e interessante."}],"es":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Consejo del día:\n\nCuando el camino está bloqueado, no te apresures a volver atrás. Si te golpeas la cabeza contra la pared y ya piensas que así el Universo (Dios) te indica que esto no es para ti, antes de abandonar lo empezado, cálmate y dirígete al Universo con la petición de mostrar un camino alternativo. Después de esto, relájate y dale tiempo a que llegue la respuesta. Sucede que muy cerca hay una puerta o un sendero inadvertido que te llevará a la meta por un camino más hermoso e interesante."}],"pt":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Dica do dia:\n\nQuando o caminho está obstruído, não se apressem em voltar atrás. Se vocês batem a cabeça contra a parede e já pensam que assim o Universo (Deus) está lhes indicando que isso não é para vocês, antes de abandonar o que começaram, acalmem-se e dirijam-se ao Universo com o pedido de mostrar um caminho alternativo. Depois disso, relaxem e deem tempo para que a resposta chegue. Acontece que bem perto existe uma porta ou uma trilha imperceptível que os levará ao objetivo por um caminho mais bonito e interessante."}],"nl":[{"type":"video","vimeoId":"1158291041"},{"type":"text","markdown":"### Tip van de dag:\n\nWanneer de weg versperd is, haast je niet om terug te keren. Als je je hoofd tegen een muur stoot en al denkt dat het Universum (God) je zo laat zien dat dit niet voor jou is, bedaar dan voordat je opgeeft wat je begonnen bent en vraag het Universum om je een omweg te tonen. Ontspan daarna en geef de tijd om het antwoord te laten komen. Soms bevindt zich heel dichtbij een deur of een onopvallend pad dat je langs een mooiere en interessantere route naar je doel brengt."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-19','intensive-holiness',19,1,'День: 19','[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Совет дня:\n\nВоспринимайте каждый порог, как священную границу. Каждый день вы десятки раз переступаете пороги - когда выходите из дома, входите в новую комнату, открываете дверь в автомобиль... Обычно люди делают это на автопилоте, передвигая себя в физическом пространстве. Попробуйте остановиться на мгновение на пороге, сделать спокойный вдох и оставить прошлое позади. Пусть каждый ваш переход будет маленьким обрядом обновления, когда вы входите в новое жизненное пространство чистым и живым."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Tip of the day:\n\nPerceive every threshold as a sacred boundary. Every day you cross thresholds dozens of times - when you leave home, enter a new room, open the door of a car... Usually people do this on autopilot, moving themselves through physical space. Try to stop for a moment at the threshold, take a calm breath and leave the past behind. Let every crossing be a little ritual of renewal, when you enter a new life space clean and alive."}],"de":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Tipp des Tages:\n\nBetrachte jede Schwelle als heilige Grenze. Jeden Tag überschreitest du Dutzende Male Schwellen - wenn du das Haus verlässt, einen neuen Raum betrittst, die Autotür öffnest... Normalerweise tun Menschen das auf Autopilot, indem sie sich im physischen Raum fortbewegen. Versuche, einen Augenblick auf der Schwelle innezuhalten, einen ruhigen Atemzug zu nehmen und die Vergangenheit hinter dir zu lassen. Lass jeden deiner Übergänge ein kleines Ritual der Erneuerung sein, wenn du in einen neuen Lebensraum eintrittst - rein und lebendig."}],"fr":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Conseil du jour :\n\nPercevez chaque seuil comme une frontière sacrée. Chaque jour, vous franchissez des dizaines de fois des seuils — quand vous sortez de chez vous, entrez dans une nouvelle pièce, ouvrez la portière d’une voiture... Habituellement, les gens le font en mode automatique, en déplaçant leur corps dans l’espace physique. Essayez de vous arrêter un instant sur le seuil, de prendre une inspiration calme et de laisser le passé derrière vous. Que chacun de vos passages soit un petit rite de renouvellement, où vous entrez dans un nouvel espace de vie pur et vivant."}],"it":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPercepite ogni soglia come un confine sacro. Ogni giorno attraversate soglie decine di volte: quando uscite di casa, entrate in una nuova stanza, aprite la portiera dell''auto... Di solito le persone lo fanno in automatico, spostandosi nello spazio fisico. Provate a fermarvi per un istante sulla soglia, a fare un respiro calmo e a lasciare il passato dietro di voi. Che ogni vostro passaggio sia un piccolo rito di rinnovamento, quando entrate in un nuovo spazio vitale puri e vivi."}],"es":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Consejo del día:\n\nPercibe cada umbral como una frontera sagrada. Cada día cruzas umbrales decenas de veces: cuando sales de casa, entras en una nueva habitación, abres la puerta del automóvil... Normalmente las personas hacen esto en piloto automático, desplazándose en el espacio físico. Intenta detenerte un instante en el umbral, hacer una respiración tranquila y dejar el pasado atrás. Que cada uno de tus tránsitos sea un pequeño rito de renovación, cuando entras en un nuevo espacio vital limpio y vivo."}],"pt":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Dica do dia:\n\nPercebam cada limiar como uma fronteira sagrada. Todos os dias vocês cruzam limiares dezenas de vezes — quando saem de casa, entram em uma nova sala, abrem a porta do carro... Normalmente as pessoas fazem isso no piloto automático, movendo-se no espaço físico. Tentem parar por um instante no limiar, dar uma respiração calma e deixar o passado para trás. Que cada passagem sua seja um pequeno ritual de renovação, quando vocês entram em um novo espaço vital limpos e vivos."}],"nl":[{"type":"video","vimeoId":"1152447793"},{"type":"text","markdown":"### Tip van de dag:\n\nBeschouw elke drempel als een heilige grens. Elke dag steek je tientallen keren drempels over - wanneer je het huis verlaat, een nieuwe kamer binnengaat, de deur van een auto opent... Meestal doen mensen dit op de automatische piloot, terwijl ze zichzelf door de fysieke ruimte verplaatsen. Probeer even op de drempel te stoppen, een rustige ademhaling te nemen en het verleden achter je te laten. Laat elke overgang een klein ritueel van vernieuwing zijn, wanneer je een nieuwe levensruimte binnengaat, schoon en levend."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-20','intensive-holiness',20,1,'День: 20','[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Совет дня:\n\nРазличайте идеи от разума и Откровение от Духа. Идеи от разума - это плод размышлений и желание их проверить. Откровение от Духа приходит как внезапное, целостное знание, как вспышка света, озаряющая всё с абсолютной уверенностью, что так оно и есть. Это не мысль, которую вы думаете, а Истина, которая думает через вас. Именно за такими откровениями нужно следовать, даже если они кажутся нелогичными."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Tip of the day:\n\nDistinguish ideas from the mind and Revelation from the Spirit. Ideas from the mind are the fruit of reflection and the desire to test them. Revelation from the Spirit comes as sudden, integral knowledge, like a flash of light illuminating everything with absolute certainty that this is so. It is not a thought that you think, but the Truth that thinks through you. It is precisely such revelations that must be followed, even if they seem illogical."}],"de":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Tipp des Tages:\n\nUnterscheide zwischen Ideen aus dem Verstand und Offenbarung aus dem Geist. Ideen aus dem Verstand sind das Ergebnis von Nachdenken und der Wunsch, sie zu prüfen. Offenbarung aus dem Geist kommt als plötzliches, ganzheitliches Wissen, wie ein Lichtblitz, der alles erleuchtet - mit der absoluten Gewissheit, dass es so ist. Das ist kein Gedanke, den du denkst, sondern die Wahrheit, die durch dich denkt. Genau solchen Offenbarungen gilt es zu folgen, auch wenn sie unlogisch erscheinen."}],"fr":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Conseil du jour :\n\nDistinguez les idées venant du mental de la Révélation venant de l’Esprit. Les idées venant du mental sont le fruit de la réflexion et le désir de les vérifier. La Révélation venant de l’Esprit arrive comme une connaissance soudaine et globale, comme un éclair de lumière qui éclaire tout avec la certitude absolue que c’est bien ainsi. Ce n’est pas une pensée que vous pensez, mais la Vérité qui pense à travers vous. C’est précisément de telles révélations qu’il faut suivre, même si elles semblent illogiques."}],"it":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Consiglio del giorno:\n\nDistinguete le idee che vengono dalla mente dalla Rivelazione che viene dallo Spirito. Le idee che vengono dalla mente sono il frutto del ragionamento e il desiderio di verificarle. La Rivelazione che viene dallo Spirito arriva come una conoscenza improvvisa e integrale, come un lampo di luce che illumina tutto con la certezza assoluta che è proprio così. Non è un pensiero che voi pensate, ma la Verità che pensa attraverso di voi. Sono proprio tali rivelazioni che bisogna seguire, anche se sembrano illogiche."}],"es":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Consejo del día:\n\nDistingue las ideas que vienen de la mente de la Revelación que viene del Espíritu. Las ideas de la mente son el fruto de la reflexión y el deseo de comprobarlas. La Revelación del Espíritu llega como un conocimiento repentino e integral, como un destello de luz que ilumina todo con la absoluta certeza de que así es. No es un pensamiento que tú piensas, sino la Verdad que piensa a través de ti. Es precisamente a tales revelaciones a las que hay que seguir, incluso si parecen ilógicas."}],"pt":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Dica do dia:\n\nDistinguam as ideias que vêm da mente da Revelação que vem do Espírito. As ideias da mente são o fruto de reflexões e o desejo de verificá-las. A Revelação do Espírito chega como um conhecimento súbito e integral, como um clarão de luz que ilumina tudo com a certeza absoluta de que é assim. Não é um pensamento que vocês pensam, mas a Verdade que pensa através de vocês. É exatamente a essas revelações que se deve seguir, mesmo que pareçam ilógicas."}],"nl":[{"type":"video","vimeoId":"1151800420"},{"type":"text","markdown":"### Tip van de dag:\n\nOnderscheid ideeën van het verstand en Openbaring van de Geest. Ideeën van het verstand zijn de vrucht van overdenking en het verlangen ze te toetsen. Openbaring van de Geest komt als een plotselinge, integrale kennis, als een lichtflits die alles verlicht met de absolute zekerheid dat het zo is. Het is geen gedachte die je denkt, maar de Waarheid die door jou heen denkt. Juist zulke openbaringen moet je volgen, zelfs als ze onlogisch lijken."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-21','intensive-holiness',21,1,'День: 21','[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Совет дня:\n\nВоспринимайте творческий процесс как высшую форму молитвы. Процесс творчества, когда вы находитесь в потоке - это ваше самое искреннее общение с Богом. Когда замечаете малейшую волну творческого вдохновения, относитесь к ней с максимальным вниманием, понимая, что это Бог вышел на связь. И скорректируйте своё восприятие происходящего - чтобы не ожидать результата, а получать радость и удовлетворение в текущем моменте - от самого процесса единения с творческой силой Вселенной. Творческие кризисы в этом контексте - это не неудача и не проблема, а призыв к более глубокому смирению, искренности, и очищению канала связи с Богом."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Tip of the day:\n\nPerceive the creative process as the highest form of prayer. The process of creativity, when you are in the flow, is your most sincere communication with God. When you notice the slightest wave of creative inspiration, treat it with maximum attention, understanding that God has made contact. And adjust your perception of what is happening - so as not to expect a result, but to receive joy and satisfaction in the current moment - from the very process of union with the creative force of the Universe. Creative crises in this context are not a failure or a problem, but a call to deeper humility, sincerity, and purification of the channel of communication with God."}],"de":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Tipp des Tages:\n\nBetrachte den schöpferischen Prozess als höchste Form des Gebets. Der Prozess des Schaffens, wenn du im Fluss bist, ist deine aufrichtigste Kommunikation mit Gott. Wenn du die kleinste Welle schöpferischer Inspiration bemerkst, begegne ihr mit größter Aufmerksamkeit und verstehe, dass Gott sich gemeldet hat. Und korrigiere deine Wahrnehmung des Geschehens - um nicht auf ein Ergebnis zu warten, sondern Freude und Erfüllung im gegenwärtigen Moment zu empfangen - aus dem Prozess selbst der Vereinigung mit der schöpferischen Kraft des Universums. Schöpferische Krisen sind in diesem Kontext kein Versagen und kein Problem, sondern ein Ruf zu tieferer Demut, Aufrichtigkeit und Reinigung des Kanals der Verbindung mit Gott."}],"fr":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Conseil du jour :\n\nPercevez le processus créatif comme la forme suprême de la prière. Le processus de création, lorsque vous êtes dans le flux, est votre communication la plus sincère avec Dieu. Lorsque vous remarquez la moindre vague d’inspiration créatrice, accordez-lui la plus grande attention, en comprenant que c’est Dieu qui est entré en contact. Et ajustez votre perception de ce qui se passe — afin de ne pas attendre le résultat, mais de recevoir joie et satisfaction dans le moment présent — du processus même d’union avec la force créatrice de l’Univers. Les crises créatives, dans ce contexte, ne sont ni un échec ni un problème, mais un appel à une humilité plus profonde, à la sincérité et à la purification du canal de communication avec Dieu."}],"it":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPercepite il processo creativo come la forma più alta di preghiera. Il processo creativo, quando siete nel flusso, è la vostra più sincera comunicazione con Dio. Quando notate la minima onda di ispirazione creativa, trattatela con la massima attenzione, comprendendo che è Dio che si è messo in contatto. E correggete la vostra percezione di ciò che accade: per non aspettarvi un risultato, ma ricevere gioia e soddisfazione nel momento presente, dal processo stesso di unione con la forza creativa dell''Universo. Le crisi creative in questo contesto non sono un fallimento né un problema, ma un invito a una più profonda umiltà, sincerità e purificazione del canale di comunicazione con Dio."}],"es":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Consejo del día:\n\nPercibe el proceso creativo como la forma suprema de oración. El proceso de creación, cuando estás en el flujo, es tu comunicación más sincera con Dios. Cuando notes la más mínima ola de inspiración creativa, trátala con la máxima atención, comprendiendo que es Dios quien se ha puesto en contacto. Y corrige tu percepción de lo que ocurre: para no esperar el resultado, sino recibir alegría y satisfacción en el momento presente, del propio proceso de unión con la fuerza creativa del Universo. Las crisis creativas en este contexto no son un fracaso ni un problema, sino un llamado a una humildad más profunda, a la sinceridad y a la purificación del canal de conexión con Dios."}],"pt":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Dica do dia:\n\nPercebam o processo criativo como a forma mais elevada de oração. O processo de criação, quando vocês estão no fluxo, é a sua comunicação mais sincera com Deus. Quando notarem a menor onda de inspiração criativa, tratem-na com a máxima atenção, compreendendo que foi Deus quem entrou em contato. E corrijam a sua percepção do que acontece — para não esperar o resultado, mas receber alegria e satisfação no momento presente — do próprio processo de união com a força criativa do Universo. Crises criativas, nesse contexto, não são fracasso nem problema, mas um chamado a uma humildade mais profunda, à sinceridade e à purificação do canal de conexão com Deus."}],"nl":[{"type":"video","vimeoId":"1158690072"},{"type":"text","markdown":"### Tip van de dag:\n\nBeschouw het creatieve proces als de hoogste vorm van gebed. Het creatieve proces, wanneer je in de flow bent, is je meest oprechte communicatie met God. Wanneer je de kleinste golf van creatieve inspiratie opmerkt, behandel die dan met de grootste aandacht, in het besef dat God contact heeft opgenomen. En corrigeer je waarneming van wat er gebeurt - om niet op een resultaat te wachten, maar vreugde en voldoening in het huidige moment te ontvangen - van het proces zelf van eenwording met de creatieve kracht van het Universum. Creatieve crises zijn in deze context geen mislukking en geen probleem, maar een oproep tot diepere overgave, oprechtheid en zuivering van het kanaal van verbinding met God."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-22','intensive-holiness',22,1,'День: 22','[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Совет дня:\n\nОщущайте в своем теле священную жизненную силу. Дыхание, биение сердца, рост волос, все процессы жизнедеятельности - это проявления великой космической энергии, которая оживляет всю Вселенную. Чувствуя эту энергию в себе, вы соединяетесь с бесконечностью, со всеми формами жизни на всех духовных уровнях. Ваше тело становится не просто плотью, а волшебным ключом. И только вы сами ограничиваете свои возможности."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Tip of the day:\n\nFeel the sacred life force in your body. Breathing, heartbeat, hair growth, all processes of vital activity - these are manifestations of the great cosmic energy that animates the entire Universe. Feeling this energy in yourself, you connect with infinity, with all forms of life on all spiritual levels. Your body becomes not just flesh, but a magic key. And only you yourself limit your possibilities."}],"de":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Tipp des Tages:\n\nSpüre in deinem Körper die heilige Lebenskraft. Atem, Herzschlag, Haarwachstum, alle Prozesse der Lebenstätigkeit - das sind Erscheinungen der großen kosmischen Energie, die das gesamte Universum belebt. Wenn du diese Energie in dir fühlst, verbindest du dich mit der Unendlichkeit, mit allen Lebensformen auf allen spirituellen Ebenen. Dein Körper wird nicht einfach nur Fleisch, sondern ein magischer Schlüssel. Und nur du selbst begrenzt deine Möglichkeiten."}],"fr":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Conseil du jour :\n\nRessentez dans votre corps la force vitale sacrée. La respiration, les battements du cœur, la croissance des cheveux, tous les processus vitaux — sont des manifestations de la grande énergie cosmique qui anime tout l’Univers. En ressentant cette énergie en vous, vous vous reliez à l’infini, à toutes les formes de vie sur tous les plans spirituels. Votre corps devient non pas simplement de la chair, mais une clé magique. Et c’est vous seul qui limitez vos possibilités."}],"it":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Consiglio del giorno:\n\nSentite nel vostro corpo la sacra forza vitale. Il respiro, il battito del cuore, la crescita dei capelli, tutti i processi vitali: sono manifestazioni della grande energia cosmica che dà vita all''intero Universo. Sentendo questa energia in voi, vi connettete all''infinito, a tutte le forme di vita su tutti i livelli spirituali. Il vostro corpo diventa non semplice carne, ma una chiave magica. E solo voi stessi limitate le vostre possibilità."}],"es":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Consejo del día:\n\nSiente en tu cuerpo la sagrada fuerza vital. La respiración, el latido del corazón, el crecimiento del cabello, todos los procesos de la actividad vital son manifestaciones de la gran energía cósmica que vivifica todo el Universo. Al sentir esta energía en ti, te conectas con la infinidad, con todas las formas de vida en todos los niveles espirituales. Tu cuerpo se convierte no simplemente en carne, sino en una llave mágica. Y solo tú mismo limitas tus posibilidades."}],"pt":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Dica do dia:\n\nSintam no seu corpo a sagrada força vital. A respiração, o bater do coração, o crescimento dos cabelos, todos os processos vitais — são manifestações da grande energia cósmica que anima todo o Universo. Sentindo essa energia em vocês, vocês se conectam com o infinito, com todas as formas de vida em todos os níveis espirituais. Seu corpo deixa de ser apenas carne e se torna uma chave mágica. E são somente vocês mesmos que limitam suas possibilidades."}],"nl":[{"type":"video","vimeoId":"1133718432"},{"type":"text","markdown":"### Tip van de dag:\n\nVoel in je lichaam de heilige levenskracht. Ademhaling, hartslag, haargroei, alle processen van levensactiviteit - het zijn manifestaties van de grote kosmische energie die het hele Universum bezielt. Door deze energie in jezelf te voelen, verbind je je met de oneindigheid, met alle levensvormen op alle spirituele niveaus. Je lichaam wordt niet louter vlees, maar een magische sleutel. En alleen jijzelf beperkt je mogelijkheden."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-23','intensive-holiness',23,1,'День: 23','[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Совет дня:\n\nКрасоту мира созерцайте как письмена Бога, как священное Евангелие. Цветок, закат, узор на крыле бабочки - это буквы, которыми Бог пишет вам своё послание. Остановитесь и начните читать эту красоту точно также, как вы читаете Евангелие. Позвольте ей войти в вас и вызвать душевный трепет. Это будет лучшая молитва."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Tip of the day:\n\nContemplate the beauty of the world as God''s writing, as a sacred Gospel. A flower, a sunset, a pattern on a butterfly''s wing - these are letters with which God writes you His message. Stop and begin to read this beauty just as you read the Gospel. Allow it to enter you and evoke a spiritual thrill. This will be the best prayer."}],"de":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Tipp des Tages:\n\nBetrachte die Schönheit der Welt als Schrift Gottes, als heiliges Evangelium. Eine Blume, ein Sonnenuntergang, das Muster auf dem Flügel eines Schmetterlings - das sind Buchstaben, mit denen Gott dir seine Botschaft schreibt. Halte inne und beginne, diese Schönheit genauso zu lesen, wie du das Evangelium liest. Lass sie in dich eintreten und eine tiefe Ergriffenheit der Seele hervorrufen. Das wird das beste Gebet sein."}],"fr":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Conseil du jour :\n\nContemplez la beauté du monde comme les écrits de Dieu, comme un Évangile sacré. Une fleur, un coucher de soleil, un motif sur l’aile d’un papillon — ce sont des lettres par lesquelles Dieu vous écrit son message. Arrêtez-vous et commencez à lire cette beauté exactement comme vous lisez l’Évangile. Laissez-la entrer en vous et provoquer un frémissement de l’âme. Ce sera la meilleure prière."}],"it":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Consiglio del giorno:\n\nContemplate la bellezza del mondo come la scrittura di Dio, come un Vangelo sacro. Un fiore, un tramonto, il disegno sull''ala di una farfalla: sono le lettere con cui Dio vi scrive il suo messaggio. Fermatevi e cominciate a leggere questa bellezza proprio come leggete il Vangelo. Lasciate che entri in voi e susciti un fremito dell''anima. Questa sarà la migliore preghiera."}],"es":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Consejo del día:\n\nContempla la belleza del mundo como la escritura de Dios, como el Evangelio sagrado. Una flor, un atardecer, el dibujo en el ala de una mariposa: son letras con las que Dios te escribe su mensaje. Detente y empieza a leer esta belleza exactamente igual que como lees el Evangelio. Permítele entrar en ti y provocar un estremecimiento del alma. Esta será la mejor oración."}],"pt":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Dica do dia:\n\nContemplem a beleza do mundo como os escritos de Deus, como o Evangelho sagrado. Uma flor, um pôr do sol, o desenho na asa de uma borboleta — são letras com as quais Deus escreve para vocês a sua mensagem. Parem e comecem a ler essa beleza exatamente como vocês leem o Evangelho. Permitam que ela entre em vocês e provoque um arrepio na alma. Essa será a melhor oração."}],"nl":[{"type":"video","vimeoId":"1109898999"},{"type":"text","markdown":"### Tip van de dag:\n\nAanschouw de schoonheid van de wereld als de geschriften van God, als een heilig Evangelie. Een bloem, een zonsondergang, het patroon op de vleugel van een vlinder - het zijn letters waarmee God je zijn boodschap schrijft. Stop en begin deze schoonheid te lezen, precies zoals je het Evangelie leest. Laat haar in je binnenkomen en een ontroering van de ziel oproepen. Dat zal het beste gebed zijn."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-24','intensive-holiness',24,1,'День: 24','[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Совет дня:\n\nПрощая, вы приобщаетесь к космическому милосердию. Держать обиду - значит пытаться остановить в себе поток божественной энергии. Поэтому чувствовать обиду настолько неприятно. Прощение - это сознательное решение вновь открыть шлюзы и позволить потоку вселенской Любви и Милосердия омыть и вас, и того, кто вас обидел. Вы не оправдываете поступок, но вы освобождаете обе души из тюрьмы прошлого."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Tip of the day:\n\nBy forgiving, you become part of cosmic mercy. To hold a grudge means to try to stop within yourself the flow of divine energy. That is why feeling resentment is so unpleasant. Forgiveness is a conscious decision to reopen the locks and allow the flow of universal Love and Mercy to wash both you and the one who offended you. You do not justify the act, but you free both souls from the prison of the past."}],"de":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Tipp des Tages:\n\nIndem du vergibst, wirst du Teil des kosmischen Erbarmens. Eine Kränkung festzuhalten bedeutet, den Fluss der göttlichen Energie in dir aufhalten zu wollen. Deshalb fühlt sich Kränkung so unangenehm an. Vergebung ist die bewusste Entscheidung, die Schleusen wieder zu öffnen und den Strom der universellen Liebe und des Erbarmens zu erlauben, sowohl dich als auch denjenigen, der dich gekränkt hat, zu überspülen. Du rechtfertigst die Tat nicht, aber du befreist beide Seelen aus dem Gefängnis der Vergangenheit."}],"fr":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Conseil du jour :\n\nEn pardonnant, vous vous joignez à la miséricorde cosmique. Garder un ressentiment, c’est tenter d’arrêter en soi le flux de l’énergie divine. C’est pourquoi ressentir du ressentiment est si désagréable. Le pardon est une décision consciente de rouvrir les écluses et de laisser le flux de l’Amour et de la Miséricorde universels vous laver, vous et celui qui vous a offensé. Vous ne justifiez pas l’acte, mais vous libérez les deux âmes de la prison du passé."}],"it":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPerdonando, partecipate alla misericordia cosmica. Serbare rancore significa cercare di fermare in voi il flusso dell''energia divina. Per questo provare rancore è così sgradevole. Il perdono è una decisione consapevole di riaprire le chiuse e permettere al flusso dell''Amore e della Misericordia universali di lavare voi e colui che vi ha offeso. Non giustificate l''atto, ma liberate entrambe le anime dalla prigione del passato."}],"es":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Consejo del día:\n\nAl perdonar, te unes a la misericordia cósmica. Guardar un resentimiento significa intentar detener en ti el flujo de la energía divina. Por eso es tan desagradable sentir resentimiento. El perdón es una decisión consciente de abrir de nuevo las compuertas y permitir que el flujo del Amor y la Misericordia universales os limpien tanto a ti como a quien te ofendió. No justificas el acto, pero liberas ambas almas de la prisión del pasado."}],"pt":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Dica do dia:\n\nAo perdoar, vocês se unem à misericórdia cósmica. Guardar ressentimento significa tentar deter em si o fluxo da energia divina. Por isso sentir ressentimento é tão desagradável. O perdão é uma decisão consciente de reabrir as comportas e permitir que o fluxo do Amor e da Misericórdia universais lave vocês e aquele que os ofendeu. Vocês não justificam o ato, mas libertam ambas as almas da prisão do passado."}],"nl":[{"type":"video","vimeoId":"1155673978"},{"type":"text","markdown":"### Tip van de dag:\n\nDoor te vergeven neem je deel aan kosmische barmhartigheid. Wrok koesteren betekent proberen de stroom van goddelijke energie in jezelf tegen te houden. Daarom voelt wrok zo onaangenaam. Vergeving is een bewuste beslissing om de sluizen weer te openen en de stroom van universele Liefde en Barmhartigheid jou en degene die je heeft gekwetst te laten overspoelen. Je rechtvaardigt de daad niet, maar je bevrijdt beide zielen uit de gevangenis van het verleden."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-25','intensive-holiness',25,1,'День: 25','[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Совет дня:\n\nВаша лучшая практика - излучать свет своей внутренней святости. Прежде чем спасать мир, зажгите светильник в собственном храме души. Ваше состояние умиротворённости, благости, и внутренней чистоты само по себе является мощнейшим целительным излучением. Когда вы находитесь в гармонии с Высшим, ваш свет помогает многим людям проходить житейские бури и видеть Путь."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Tip of the day:\n\nYour best practice is to radiate the light of your inner holiness. Before saving the world, light the lamp in your own temple of the soul. Your state of peacefulness, goodness, and inner purity is in itself a most powerful healing radiation. When you are in harmony with the Highest, your light helps many people pass through the storms of life and see the Path."}],"de":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Tipp des Tages:\n\nDeine beste Praxis ist, das Licht deiner inneren Heiligkeit auszustrahlen. Bevor du die Welt rettest, entzünde die Lampe im eigenen Tempel der Seele. Dein Zustand von Frieden, Güte und innerer Reinheit ist an sich schon eine gewaltige heilende Ausstrahlung. Wenn du in Harmonie mit dem Höchsten bist, hilft dein Licht vielen Menschen, die Stürme des Alltags zu durchstehen und den Weg zu sehen."}],"fr":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Conseil du jour :\n\nVotre meilleure pratique est de rayonner la lumière de votre sainteté intérieure. Avant de sauver le monde, allumez la lampe dans le temple de votre propre âme. Votre état de paix, de bonté et de pureté intérieure est en soi un puissant rayonnement guérisseur. Lorsque vous êtes en harmonie avec le Plus Haut, votre lumière aide de nombreuses personnes à traverser les tempêtes de la vie et à voir le Chemin."}],"it":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Consiglio del giorno:\n\nLa vostra migliore pratica è irradiare la luce della vostra santità interiore. Prima di salvare il mondo, accendete la lampada nel tempio della vostra stessa anima. Il vostro stato di pace, bontà e purezza interiore è di per sé un potentissimo raggio curativo. Quando siete in armonia con l''Altissimo, la vostra luce aiuta molte persone ad attraversare le tempeste della vita e a vedere la Via."}],"es":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Consejo del día:\n\nTu mejor práctica es irradiar la luz de tu santidad interior. Antes de salvar el mundo, enciende la lámpara en tu propio templo del alma. Tu estado de paz, bondad y pureza interior es en sí mismo una potentísima radiación sanadora. Cuando estás en armonía con lo Superior, tu luz ayuda a muchas personas a atravesar las tormentas de la vida y a ver el Camino."}],"pt":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Dica do dia:\n\nSua melhor prática é irradiar a luz da sua santidade interior. Antes de salvar o mundo, acendam a lâmpada no próprio templo da alma. Seu estado de serenidade, bondade e pureza interior é, por si só, uma irradiação curativa poderosíssima. Quando vocês estão em harmonia com o Altíssimo, sua luz ajuda muitas pessoas a atravessar as tempestades da vida e a ver o Caminho."}],"nl":[{"type":"video","vimeoId":"1152694364"},{"type":"text","markdown":"### Tip van de dag:\n\nJe beste praktijk is het uitstralen van het licht van je innerlijke heiligheid. Voordat je de wereld redt, steek de lamp aan in je eigen tempel van de ziel. Je toestand van vrede, goedheid en innerlijke zuiverheid is op zichzelf een uiterst krachtige genezende straling. Wanneer je in harmonie bent met het Hoogste, helpt jouw licht vele mensen om de stormen van het leven door te komen en de Weg te zien."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-26','intensive-holiness',26,1,'День: 26','[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Совет дня:\n\nПосадите семя и отпустите контроль над его ростом. Каждое действие выполняйте на наиболее целостной и возвышенной волне, с максимальной любовью и отдачей (не на волне желаний, затыкающих дыры потребностей). А затем доверьте результат Высшим Силам. Вы не можете заставить розу цвести быстрее, дергая за бутон. Ваша задача - сажать лучшие семена, а остальное - таинство Жизни."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Tip of the day:\n\nPlant a seed and release control over its growth. Perform every action on the most holistic and elevated wave, with maximum love and dedication (not on the wave of desires plugging the holes of needs). And then entrust the result to the Higher Forces. You cannot make a rose bloom faster by pulling at the bud. Your task is to plant the best seeds, and the rest is the mystery of Life."}],"de":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Tipp des Tages:\n\nPflanze einen Samen und gib die Kontrolle über sein Wachstum ab. Führe jede Handlung auf der ganzheitlichsten und erhabensten Welle aus, mit größter Liebe und Hingabe (nicht auf der Welle der Wünsche, die Löcher der Bedürfnisse stopfen). Und dann vertraue das Ergebnis den Höheren Kräften an. Du kannst eine Rose nicht schneller zum Blühen bringen, indem du an der Knospe ziehst. Deine Aufgabe ist es, die besten Samen zu säen, und der Rest ist das Mysterium des Lebens."}],"fr":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Conseil du jour :\n\nPlantez une graine et lâchez le contrôle sur sa croissance. Accomplissez chaque action sur la vague la plus intègre et la plus élevée, avec un maximum d’amour et de don (non pas sur la vague des désirs qui bouchent les trous des besoins). Ensuite, confiez le résultat aux Forces Supérieures. Vous ne pouvez pas forcer une rose à fleurir plus vite en tirant sur son bouton. Votre tâche est de planter les meilleures graines, et le reste est le mystère de la Vie."}],"it":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Consiglio del giorno:\n\nPiantate un seme e lasciate andare il controllo sulla sua crescita. Ogni azione compitela sull''onda più integra ed elevata, con il massimo amore e dedizione (non sull''onda dei desideri che tappano le falle dei bisogni). E poi affidate il risultato alle Forze Superiori. Non potete far sbocciare più in fretta una rosa tirandone il bocciolo. Il vostro compito è piantare i semi migliori, il resto è il mistero della Vita."}],"es":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Consejo del día:\n\nPlanta una semilla y suelta el control sobre su crecimiento. Realiza cada acción en la onda más íntegra y elevada, con el máximo amor y entrega (no en la onda de los deseos que tapan los agujeros de las necesidades). Y después confía el resultado a las Fuerzas Superiores. No puedes hacer que una rosa florezca más rápido tirando del capullo. Tu tarea es plantar las mejores semillas, y el resto es el misterio de la Vida."}],"pt":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Dica do dia:\n\nPlantem a semente e abandonem o controle sobre o seu crescimento. Realizem cada ação na onda mais íntegra e elevada, com o máximo de amor e entrega (não na onda dos desejos que tapam buracos de necessidades). E então confiem o resultado às Forças Superiores. Vocês não podem fazer uma rosa florescer mais rápido puxando o botão. Sua tarefa é plantar as melhores sementes, e o resto é o mistério da Vida."}],"nl":[{"type":"video","vimeoId":"1154211772"},{"type":"text","markdown":"### Tip van de dag:\n\nPlant een zaadje en laat de controle over de groei ervan los. Verricht elke handeling op de meest integrale en verheven golf, met maximale liefde en toewijding (niet op de golf van verlangens die de gaten van behoeften dichten). En vertrouw het resultaat daarna toe aan de Hogere Krachten. Je kunt een roos niet sneller laten bloeien door aan de knop te trekken. Jouw taak is de beste zaden te planten, en de rest is het mysterie van het Leven."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-27','intensive-holiness',27,1,'День: 27','[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Совет дня:\n\nПримите свою Тень как неоткрытую часть Божественного. Не боритесь со своими \"тёмными\" сторонами, а исследуйте их с состраданием. В вашей зависти может скрываться жажда полноты бытия, в вашем гневе - искаженное стремление к справедливости. Вы очень мало знаете о себе. Интегрируя свою Тень, вы не становитесь хуже, вы становитесь целостнее, возвращая изгнанные части своей души обратно в свет божественного принятия и любви, давая им возможность исцеления."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Tip of the day:\n\nAccept your Shadow as an undiscovered part of the Divine. Do not fight your \"dark\" sides, but explore them with compassion. In your envy there may hide a thirst for the fullness of being, in your anger - a distorted striving for justice. You know very little about yourself. By integrating your Shadow, you do not become worse, you become more whole, returning the exiled parts of your soul back into the light of divine acceptance and love, giving them the opportunity for healing."}],"de":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Tipp des Tages:\n\nNimm deinen Schatten als unentdeckten Teil des Göttlichen an. Bekämpfe deine \"dunklen\" Seiten nicht, sondern erforsche sie mit Mitgefühl. In deinem Neid kann eine Sehnsucht nach der Fülle des Daseins verborgen sein, in deinem Zorn ein verzerrtes Streben nach Gerechtigkeit. Du weißt sehr wenig über dich selbst. Indem du deinen Schatten integrierst, wirst du nicht schlechter, du wirst ganzheitlicher, indem du die verbannten Teile deiner Seele zurück in das Licht göttlicher Annahme und Liebe bringst und ihnen die Möglichkeit der Heilung gibst."}],"fr":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Conseil du jour :\n\nAccueillez votre Ombre comme une partie non révélée du Divin. Ne combattez pas vos côtés « sombres », mais explorez-les avec compassion. Dans votre envie peut se cacher une soif de plénitude de l’être, dans votre colère — une aspiration déformée à la justice. Vous savez très peu de choses sur vous-même. En intégrant votre Ombre, vous ne devenez pas pire, vous devenez plus entier, en ramenant les parties exilées de votre âme à la lumière de l’acceptation et de l’amour divins, en leur donnant la possibilité de guérir."}],"it":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Consiglio del giorno:\n\nAccogliete la vostra Ombra come una parte non ancora scoperta del Divino. Non combattete i vostri lati \"oscuri\", ma esplorateli con compassione. Nella vostra invidia può nascondersi la sete di pienezza dell''essere, nella vostra ira un distorto anelito alla giustizia. Sapete molto poco di voi stessi. Integrando la vostra Ombra non diventate peggiori, diventate più integri, riportando le parti esiliate della vostra anima di nuovo nella luce dell''accoglienza e dell''amore divini, dando loro la possibilità di guarire."}],"es":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Consejo del día:\n\nAcepta tu Sombra como una parte no descubierta de lo Divino. No luches contra tus lados \"oscuros\", sino investígalos con compasión. En tu envidia puede esconderse la sed de plenitud del ser, en tu ira, una aspiración distorsionada a la justicia. Sabes muy poco sobre ti mismo. Al integrar tu Sombra, no te vuelves peor, te vuelves más íntegro, devolviendo las partes desterradas de tu alma a la luz de la aceptación y el amor divinos, dándoles la posibilidad de sanación."}],"pt":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Dica do dia:\n\nAceitem a sua Sombra como uma parte não descoberta do Divino. Não lutem contra os seus lados \"sombrios\", mas investiguem-nos com compaixão. Na sua inveja pode esconder-se a sede de plenitude do ser; na sua raiva, um desejo distorcido de justiça. Vocês sabem muito pouco sobre si mesmos. Ao integrar a sua Sombra, vocês não se tornam piores, tornam-se mais inteiros, devolvendo as partes exiladas da sua alma à luz da aceitação e do amor divinos, dando-lhes a possibilidade de cura."}],"nl":[{"type":"video","vimeoId":"1158693970"},{"type":"text","markdown":"### Tip van de dag:\n\nOmarm je Schaduw als een nog niet ontsloten deel van het Goddelijke. Vecht niet tegen je \"donkere\" kanten, maar onderzoek ze met mededogen. In je afgunst kan een honger naar volheid van bestaan schuilgaan, in je woede - een vervormd streven naar gerechtigheid. Je weet heel weinig over jezelf. Door je Schaduw te integreren word je niet slechter, je wordt integraler, terwijl je de verbannen delen van je ziel terugbrengt in het licht van goddelijke aanvaarding en liefde, en hun de mogelijkheid tot genezing geeft."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-28','intensive-holiness',28,1,'День: 28','[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Совет дня:\n\nОсознайте, как ваша вера формирует реальность. Вера - это не пассивное чувство, а активная творческая сила. Ваше глубокое, непоколебимое убеждение в том, что мир устроен определённым образом - формирует соответствующую реальнсть. Хотите оказаться в другой реальности? Не нужно над этим работать, вкладываться и т.п. - сформируйте её своей верой. \"По вере вашей да будет вам\" - Евангелие от Матфея 9:29. Технически всё просто - нужно лишь искренне верить. И всё-таки получается не всегда, так как часто \"человеческое\" подменяет собой божественное. В этом случае разберитесь с природой своего желания изменить реальность (От кого бежите? Что вас держит в этой реальности?). Поддержка в том, что ваша вера буквально каждое мгновение в форме \"реальности\" проявляет вас для вас же."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Tip of the day:\n\nBecome aware of how your faith shapes reality. Faith is not a passive feeling, but an active creative force. Your deep, unshakable conviction that the world is arranged in a certain way - forms a corresponding reality. Want to find yourself in another reality? You do not need to work on it, invest in it, etc. - form it with your faith. \"According to your faith be it unto you\" - Gospel of Matthew 9:29. Technically everything is simple - you only need to sincerely believe. And yet it does not always work out, since often the \"human\" replaces the divine. In this case, sort out the nature of your desire to change reality (What are you running from? What keeps you in this reality?). The support is that your faith literally every moment in the form of \"reality\" manifests you to yourself."}],"de":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Tipp des Tages:\n\nErkenne, wie dein Glaube die Realität formt. Glaube ist kein passives Gefühl, sondern eine aktive schöpferische Kraft. Deine tiefe, unerschütterliche Überzeugung, dass die Welt auf eine bestimmte Weise eingerichtet ist, formt eine entsprechende Realität. Willst du dich in einer anderen Realität wiederfinden? Du musst nicht daran arbeiten, dich hineinlegen und Ähnliches - forme sie durch deinen Glauben. \"Euch geschehe nach eurem Glauben\" - Evangelium nach Matthäus 9:29. Technisch ist alles einfach - man muss nur aufrichtig glauben. Und doch gelingt es nicht immer, weil oft das \"Menschliche\" das Göttliche ersetzt. In diesem Fall ergründe die Natur deines Wunsches, die Realität zu verändern (Vor wem fliehst du? Was hält dich in dieser Realität?). Die Unterstützung besteht darin, dass dein Glaube buchstäblich jeden Augenblick in Form von \"Realität\" dich für dich selbst manifestiert."}],"fr":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Conseil du jour :\n\nPrenez conscience de la manière dont votre foi façonne la réalité. La foi n’est pas un sentiment passif, mais une force créatrice active. Votre conviction profonde et inébranlable que le monde est organisé d’une certaine manière — façonne une réalité correspondante. Voulez-vous vous retrouver dans une autre réalité ? Il n’est pas nécessaire d’y travailler, de vous y investir, etc. — formez-la par votre foi. « Selon votre foi, qu’il vous soit fait » — Évangile selon Matthieu 9:29. Techniquement, tout est simple — il suffit de croire sincèrement. Et pourtant, cela ne fonctionne pas toujours, car souvent « l’humain » remplace le divin. Dans ce cas, examinez la nature de votre désir de changer la réalité (De quoi fuyez-vous ? Qu’est-ce qui vous retient dans cette réalité ?). Le soutien réside dans le fait que votre foi, littéralement à chaque instant, vous manifeste pour vous-même sous la forme de la « réalité »."}],"it":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Consiglio del giorno:\n\nRendetevi conto di come la vostra fede plasma la realtà. La fede non è un sentimento passivo, ma una forza creativa attiva. La vostra profonda, incrollabile convinzione che il mondo sia fatto in un certo modo forma la realtà corrispondente. Volete trovarvi in un''altra realtà? Non dovete lavorarci sopra, investirci, ecc.: formatela con la vostra fede. \"Secondo la vostra fede vi sia fatto\" - Vangelo di Matteo 9:29. Tecnicamente è tutto semplice: basta credere sinceramente. Eppure non sempre funziona, perché spesso l''\"umano\" prende il posto del divino. In questo caso indagate la natura del vostro desiderio di cambiare la realtà (Da chi fuggite? Che cosa vi trattiene in questa realtà?). Il sostegno sta nel fatto che la vostra fede, letteralmente in ogni istante, nella forma della \"realtà\", manifesta voi a voi stessi."}],"es":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Consejo del día:\n\nToma conciencia de cómo tu fe forma la realidad. La fe no es un sentimiento pasivo, sino una fuerza creativa activa. Tu convicción profunda e inquebrantable de que el mundo está organizado de una determinada manera forma la realidad correspondiente. ¿Quieres encontrarte en otra realidad? No hace falta trabajar en ello, invertir, etc.: forma esa realidad con tu fe. \"Conforme a vuestra fe os sea hecho\" - Evangelio de Mateo 9:29. Técnicamente todo es simple: solo hay que creer sinceramente. Y sin embargo, no siempre resulta, ya que a menudo \"lo humano\" sustituye a lo divino. En este caso, comprende la naturaleza de tu deseo de cambiar la realidad (¿De quién huyes? ¿Qué te retiene en esta realidad?). El apoyo está en que tu fe, literalmente cada instante, en forma de \"realidad\" te manifiesta ante ti mismo."}],"pt":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Dica do dia:\n\nCompreendam como a sua fé forma a realidade. A fé não é um sentimento passivo, mas uma força criativa ativa. Sua convicção profunda e inabalável de que o mundo é organizado de determinada maneira forma a realidade correspondente. Querem estar em outra realidade? Não é preciso trabalhar nisso, investir etc. — formem-na com a sua fé. \"Conforme a sua fé, assim seja feito a vocês\" — Evangelho de Mateus 9:29. Tecnicamente tudo é simples — basta crer sinceramente. E, no entanto, nem sempre dá certo, pois muitas vezes o \"humano\" substitui o divino. Nesse caso, examinem a natureza do seu desejo de mudar a realidade (De quem vocês estão fugindo? O que os mantém nessa realidade?). O apoio está em que a sua fé, literalmente a cada instante, em forma de \"realidade\", manifesta vocês para vocês mesmos."}],"nl":[{"type":"video","vimeoId":"1155457669"},{"type":"text","markdown":"### Tip van de dag:\n\nBesef hoe je geloof de werkelijkheid vormt. Geloof is geen passief gevoel, maar een actieve scheppende kracht. Je diepe, onwankelbare overtuiging dat de wereld op een bepaalde manier in elkaar zit - vormt een overeenkomstige werkelijkheid. Wil je je in een andere werkelijkheid bevinden? Je hoeft er niet aan te werken, je erin te investeren enz. - vorm haar met je geloof. \"Naar uw geloof zal het u geschieden\" - Evangelie van Matteüs 9:29. Technisch is alles eenvoudig - je hoeft alleen maar oprecht te geloven. En toch lukt het niet altijd, omdat vaak het \"menselijke\" het goddelijke vervangt. In dat geval onderzoek je de aard van je verlangen om de werkelijkheid te veranderen (Voor wie vlucht je? Wat houdt je in deze werkelijkheid?). De ondersteuning ligt daarin dat je geloof letterlijk elk moment in de vorm van \"werkelijkheid\" jou voor jezelf manifesteert."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-29','intensive-holiness',29,1,'День: 29','[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Совет дня:\n\nГоворите осознанно, понимая, что слова творят миры. Каждая произнесённая вами фраза - это заклинание. Перестаньте использовать речь для жалоб, осуждения и сплетен. Говорите о том, что хотите видеть в своей жизни. Используйте слова для благословения, для выражения красоты, для утверждения истины. Ваша речь - это инструмент священной магии."}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Tip of the day:\n\nSpeak consciously, understanding that words create worlds. Every phrase you utter is a spell. Stop using speech for complaints, condemnation and gossip. Speak about what you want to see in your life. Use words for blessing, for expressing beauty, for affirming truth. Your speech is an instrument of sacred magic."}],"de":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Tipp des Tages:\n\nSprich bewusst und im Verständnis, dass Worte Welten erschaffen. Jeder von dir ausgesprochene Satz ist ein Zauberspruch. Höre auf, Sprache für Klagen, Verurteilung und Klatsch zu verwenden. Sprich über das, was du in deinem Leben sehen möchtest. Nutze Worte zum Segnen, zum Ausdruck von Schönheit, zum Bestätigen der Wahrheit. Deine Sprache ist ein Instrument der heiligen Magie."}],"fr":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Conseil du jour :\n\nParlez consciemment, en comprenant que les mots créent des mondes. Chaque phrase que vous prononcez est une incantation. Cessez d’utiliser la parole pour vous plaindre, condamner et commérer. Parlez de ce que vous voulez voir dans votre vie. Utilisez les mots pour bénir, pour exprimer la beauté, pour affirmer la vérité. Votre parole est un instrument de magie sacrée."}],"it":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Consiglio del giorno:\n\nParlate in modo consapevole, comprendendo che le parole creano mondi. Ogni frase che pronunciate è un incantesimo. Smettete di usare il linguaggio per lamentarvi, giudicare e spettegolare. Parlate di ciò che volete vedere nella vostra vita. Usate le parole per benedire, per esprimere la bellezza, per affermare la verità. Il vostro parlare è uno strumento di magia sacra."}],"es":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Consejo del día:\n\nHabla con conciencia, comprendiendo que las palabras crean mundos. Cada frase que pronuncias es un conjuro. Deja de usar el habla para quejarte, condenar y chismear. Habla de aquello que quieres ver en tu vida. Usa las palabras para bendecir, para expresar la belleza, para afirmar la verdad. Tu habla es un instrumento de magia sagrada."}],"pt":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Dica do dia:\n\nFalem com consciência, entendendo que as palavras criam mundos. Cada frase que vocês pronunciam é um encantamento. Parem de usar a fala para queixas, condenação e fofocas. Falem sobre o que querem ver na sua vida. Usem as palavras para abençoar, para expressar a beleza, para afirmar a verdade. Sua fala é um instrumento de magia sagrada."}],"nl":[{"type":"video","vimeoId":"1158696866"},{"type":"text","markdown":"### Tip van de dag:\n\nSpreek bewust, in het besef dat woorden werelden scheppen. Elke zin die je uitspreekt is een bezwering. Stop met je taal te gebruiken voor klachten, veroordeling en roddel. Spreek over wat je in je leven wilt zien. Gebruik woorden om te zegenen, om schoonheid uit te drukken, om de waarheid te bevestigen. Je taal is een instrument van heilige magie."}]}'::jsonb,null) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,blocks_i18n,email_step_id) values('intensive-holiness-30','intensive-holiness',30,1,'День: 30','[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты, и после выполнения этой практики у вас может возникнуть вопрос - «Что дальше?»… И тут перед вами большой выбор практикумов, интенсивов и курсов, которые я подготовил для гармонизации самых разных сфер жизни и внутренних психологических состояний. Чтобы сориентироваться, сначала определитесь с направлением - что сейчас вас более всего трогает, то есть вызывает дискомфорт, тревожит, воодушевляет… (где есть яркие эмоции - там есть энергия для развития), а затем подумайте сколько времени вы готовы посвятить урокам и практикам. Если сложно определиться, напишите мне или задайте вопрос на вебинаре. Ниже я перечислил практикумы и курсы, которые могут вас заинтересовать:\n\n\nПРАКТИКУМЫ:\n - Месяц здоровья: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Месяц наслаждений: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Месяц силы: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Месяц любви: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Месяц свободы: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Месяц мудрости: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Месяц святости: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nКУРСЫ:\n - Йога и здоровье: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Йога и женственность: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Тантра - мистерия взаимоотношений: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Осуществи мечту: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Планета любви: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Источник творческой силы: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 шагов йоги: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Путь души: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]'::jsonb,'{"en":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### What''s next?\n\nI hope this month of practices has brought you tangible results, and after completing this practice you may have a question — “What’s next?”… And here before you is a large choice of workshops, intensives, and courses that I have prepared for harmonizing a wide variety of areas of life and inner psychological states. To get your bearings, first decide on the direction — what touches you most right now, that is, causes discomfort, worries, inspires… (where there are vivid emotions, there is energy for development), and then think about how much time you are ready to devote to lessons and practices. If it is difficult to decide, write to me or ask a question at the webinar. Below I have listed the workshops and courses that may interest you:\n\n\nWORKSHOPS:\n - Month of Health: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Month of Pleasures: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Month of Strength: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Month of Love: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Month of Freedom: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Month of Wisdom: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Month of Holiness: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURSES:\n - Yoga and Health: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga and Femininity: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - the mystery of relationships: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Fulfill the Dream: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet of Love: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source of Creative Power: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Steps of Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Path of the Soul: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"de":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### Was kommt als Nächstes?\n\nIch hoffe, dass dieser Monat der Praktiken Ihnen spürbare Ergebnisse gebracht hat, und nach der Ausführung dieser Praxis kann bei Ihnen die Frage aufkommen - „Was kommt als Nächstes?“… Und hier haben Sie eine große Auswahl an Praxisprogrammen, Intensivkursen und Kursen, die ich zur Harmonisierung der verschiedensten Lebensbereiche und inneren psychologischen Zustände vorbereitet habe. Zur Orientierung bestimmen Sie zuerst die Richtung - was Sie gerade am meisten berührt, also Unbehagen auslöst, beunruhigt, begeistert… (wo starke Emotionen sind, dort ist Energie für Entwicklung), und dann überlegen Sie, wie viel Zeit Sie bereit sind, den Lektionen und Praktiken zu widmen. Wenn es schwerfällt, sich zu entscheiden, schreiben Sie mir oder stellen Sie eine Frage im Webinar. Unten habe ich Praxisprogramme und Kurse aufgelistet, die Sie interessieren könnten:\n\n\nPRAKTIKA:\n - Monat der Gesundheit: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Monat der Genüsse: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Monat der Kraft: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Monat der Liebe: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Monat der Freiheit: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Monat der Weisheit: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Monat der Heiligkeit: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nKURSE:\n - Yoga und Gesundheit: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga und Weiblichkeit: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - Mysterium der Beziehungen: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwirkliche den Traum: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planet der Liebe: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Quelle schöpferischer Kraft: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 Schritte des Yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Weg der Seele: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"fr":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### Et ensuite ?\n\nJ''espère que ce mois de pratiques vous a apporté des résultats sensibles, et qu''après avoir réalisé cette pratique, une question peut surgir : « Et ensuite ? »... Et ici s''ouvre devant vous un grand choix de séminaires pratiques, d''intensifs et de cours que j''ai préparés pour harmoniser les domaines les plus divers de la vie et les états psychologiques intérieurs. Pour vous orienter, déterminez d''abord la direction : ce qui vous touche le plus actuellement, c''est-à-dire provoque de l''inconfort, inquiète, inspire... (là où il y a des émotions vives, il y a de l''énergie pour le développement), puis réfléchissez au temps que vous êtes prêt à consacrer aux leçons et aux pratiques. S''il est difficile de vous décider, écrivez-moi ou posez une question lors du webinaire. Ci-dessous, j''ai énuméré les séminaires pratiques et les cours qui peuvent vous intéresser :\n\n\nATELIERS :\n - Mois de la santé : [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mois des plaisirs : [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mois de la force : [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mois de l’amour : [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mois de la liberté : [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mois de la sagesse : [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mois de la sainteté : [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCOURS :\n - Yoga et santé: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga et féminité: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mystère des relations: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Réalise ton rêve: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planète de l''amour: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Source de force créatrice: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pas de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Chemin de l''âme: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"it":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### E adesso?\n\nSpero che questo mese di pratiche vi abbia portato risultati tangibili, e dopo aver completato questa pratica possa sorgervi la domanda: «E adesso?»… E qui davanti a voi c''è una grande scelta di laboratori pratici, intensivi e corsi che ho preparato per armonizzare le più diverse sfere della vita e gli stati psicologici interiori. Per orientarvi, prima definite la direzione: ciò che adesso vi tocca di più, cioè vi crea disagio, vi preoccupa, vi ispira… (dove ci sono emozioni vive, lì c''è energia per lo sviluppo), e poi pensate a quanto tempo siete pronti a dedicare alle lezioni e alle pratiche. Se è difficile decidere, scrivetemi o fate una domanda al webinar. Qui sotto ho elencato i laboratori pratici e i corsi che potrebbero interessarvi:\n\n\nPRATICUM:\n - Mese della salute: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mese dei piaceri: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mese della forza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mese dell''amore: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mese della libertà: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mese della saggezza: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mese della santità: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCORSI:\n - Yoga e salute: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e femminilità: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistero delle relazioni: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realizza il sogno: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Pianeta dell''amore: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte di forza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passi di yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Il cammino dell''anima: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"es":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### ¿Qué sigue?\n\nEspero que este mes de prácticas le haya traído resultados tangibles, y que después de realizar esta práctica pueda surgirle la pregunta: «¿Qué sigue?»… Y aquí tiene ante usted una gran elección de talleres prácticos, intensivos y cursos que he preparado para armonizar las más diversas esferas de la vida y estados psicológicos internos. Para orientarse, primero defina la dirección: qué es lo que ahora más lo toca, es decir, le causa malestar, le preocupa, le inspira… (donde hay emociones vivas, allí hay energía para el desarrollo), y luego piense cuánto tiempo está dispuesto a dedicar a las lecciones y prácticas. Si le resulta difícil decidirse, escríbame o haga la pregunta en el webinar. A continuación he enumerado los talleres prácticos y cursos que pueden interesarle:\n\n\nTALLERES:\n - Mes de la salud: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mes de los placeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mes de la fuerza: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mes del amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mes de la libertad: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mes de la sabiduría: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mes de la santidad: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga y salud: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga y feminidad: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - misterio de las relaciones: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Haz realidad tu sueño: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta del amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fuente de la fuerza creativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 pasos del yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Camino del alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"pt":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### O que vem a seguir?\n\nEspero que este mês de práticas tenha trazido a você resultados perceptíveis, e, após realizar esta prática, pode surgir em você a pergunta - «O que vem a seguir?»… E aqui você tem uma grande escolha de práticas, intensivos e cursos que preparei para harmonizar as mais diversas áreas da vida e estados psicológicos internos. Para se orientar, primeiro defina a direção - o que agora mais toca você, ou seja, causa desconforto, o preocupa, o inspira… (onde há emoções intensas, ali há energia para o desenvolvimento), e depois pense quanto tempo você está disposto a dedicar às aulas e práticas. Se for difícil decidir, escreva para mim ou faça uma pergunta no webinar. Abaixo listei as práticas e cursos que podem interessar a você:\n\n\nPRATICUNS:\n - Mês da saúde: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Mês dos prazeres: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Mês da força: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Mês do amor: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Mês da liberdade: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Mês da sabedoria: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Mês da santidade: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSOS:\n - Yoga e saúde: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga e feminilidade: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mistério das relações: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Realize o sonho: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeta do amor: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Fonte da força criativa: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 passos de yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Caminho da alma: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}],"nl":[{"type":"video","vimeoId":"1155850861"},{"type":"text","markdown":"### Wat nu?\n\nIk hoop dat deze maand van praktijken je voelbare resultaten heeft gebracht, en dat na het uitvoeren van deze praktijk bij je de vraag kan opkomen - «Wat nu?»… En hier heb je een grote keuze aan prakticums, intensives en cursussen die ik heb voorbereid voor het harmoniseren van de meest uiteenlopende levensgebieden en innerlijke psychologische toestanden. Om je te oriënteren, bepaal eerst de richting - wat je nu het meest raakt, dat wil zeggen ongemak veroorzaakt, je bezighoudt, inspireert… (waar levendige emoties zijn - daar is energie voor ontwikkeling), en bedenk daarna hoeveel tijd je bereid bent aan lessen en praktijken te besteden. Als het moeilijk is om te kiezen, schrijf me of stel een vraag tijdens het webinar. Hieronder heb ik de prakticums en cursussen opgesomd die je mogelijk interesseren:\n\n\nPRAKTIJKEN:\n - Maand van gezondheid: [https://zamkovoi.yoga/m1](https://zamkovoi.yoga/m1)\n - Maand van genot: [https://zamkovoi.yoga/m2](https://zamkovoi.yoga/m2)\n - Maand van kracht: [https://zamkovoi.yoga/m3](https://zamkovoi.yoga/m3)\n - Maand van liefde: [https://zamkovoi.yoga/m4](https://zamkovoi.yoga/m4)\n - Maand van vrijheid: [https://zamkovoi.yoga/m5](https://zamkovoi.yoga/m5)\n - Maand van wijsheid: [https://zamkovoi.yoga/m6](https://zamkovoi.yoga/m6)\n - Maand van heiligheid: [https://zamkovoi.yoga/m7](https://zamkovoi.yoga/m7)\n\n\nCURSUSSEN:\n - Yoga en gezondheid: [https://zamkovoi.yoga/yoga1](https://zamkovoi.yoga/yoga1)\n - Yoga en vrouwelijkheid: [https://zamkovoi.yoga/yoga2](https://zamkovoi.yoga/yoga2)\n - Tantra - mysterie van relaties: [https://zamkovoi.yoga/tantra12](https://zamkovoi.yoga/tantra12)\n - Verwezenlijk je droom: [https://zamkovoi.yoga/yoga3](https://zamkovoi.yoga/yoga3)\n - Planeet van de liefde: [https://zamkovoi.yoga/yoga4](https://zamkovoi.yoga/yoga4)\n - Bron van creatieve kracht: [https://zamkovoi.yoga/yoga5](https://zamkovoi.yoga/yoga5)\n - 36 stappen van yoga: [https://zamkovoi.yoga/yoga36](https://zamkovoi.yoga/yoga36)\n - Pad van de ziel: [https://zamkovoi.yoga/yogas](https://zamkovoi.yoga/yogas)"}]}'::jsonb,null) on conflict(id) do nothing;
